begin;

alter table public.abilities add column if not exists item_type text;
alter table public.abilities add column if not exists item_rarity text;
alter table public.abilities add column if not exists attunement text;
alter table public.abilities add column if not exists dm_edited boolean not null default false;

alter table public.abilities drop constraint if exists abilities_system_metadata_check;
alter table public.abilities drop constraint if exists abilities_kind_check;

alter table public.abilities add constraint abilities_kind_check
  check (ability_kind in ('class_feature', 'feat', 'magic_item', 'custom'));

alter table public.abilities add constraint abilities_system_metadata_check
  check (
    not is_system
    or (
      slug is not null
      and (
        (ability_kind = 'class_feature' and class_key is not null and level_required is not null)
        or (ability_kind = 'feat' and class_key is null)
        or (
          ability_kind = 'magic_item'
          and class_key is null
          and level_required is null
          and item_type is not null
          and item_rarity is not null
        )
      )
    )
  );

create index if not exists abilities_magic_item_idx
  on public.abilities (item_rarity, category, name)
  where ability_kind = 'magic_item';

with magic_item_data as (
  select value as item
  from jsonb_array_elements($magic_item_data$[{"slug":"srd52-magic-item-adamantine-armor","name":"Adamantine Armor","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":1,"action_type":null,"uses":null,"recharge":null,"summary":"This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you're wearing it, any Critical Hit against you becomes a normal hit.","description":"This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you're wearing it, any Critical Hit against you becomes a normal hit.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","uncommon","2024 rules"],"source_type":"srd","item_type":"Armor (Any Medium or Heavy, Except Hide Armor)","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-ammunition-1-2-or-3","name":"Ammunition, +1, +2, or +3","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":2,"action_type":null,"uses":null,"recharge":null,"summary":"You have a bonus to attack rolls and damage rolls made with this piece of magic ammunition. The bonus is determined by the rarity of the ammunition. Once it hits a target, the ammunition is no longer magical.","description":"You have a bonus to attack rolls and damage rolls made with this piece of magic ammunition. The bonus is determined by the rarity of the ammunition. Once it hits a target, the ammunition is no longer magical.\n\nThis ammunition is typically found or sold in quantities of ten or twenty pieces. Ten pieces of this ammunition are equivalent in value to a potion of the same rarity.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","varies","2024 rules"],"source_type":"srd","item_type":"Weapon (Any Ammunition)","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-ammunition-of-slaying","name":"Ammunition of Slaying","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":3,"action_type":null,"uses":null,"recharge":null,"summary":"This magic ammunition is meant to slay creatures of a particular type, which the GM chooses or determines randomly by rolling on the table below.","description":"This magic ammunition is meant to slay creatures of a particular type, which the GM chooses or determines randomly by rolling on the table below. If a creature of that type takes damage from the ammunition, the creature makes a DC 17 Constitution saving throw, taking an extra 6d10 Force damage on a failed save or half as much extra damage on a successful one.\n\nAfter dealing its extra damage to a creature, the ammunition becomes nonmagical.\n\n| 1d100 | Creature Type | 1d100 | Creature Type |\n| --- | --- | --- | --- |\n| 01–10 | Aberrations | 51–60 | Fey |\n| 11–15 | Beasts | 61–70 | Fiends |\n| 16–20 | Celestials | 71–75 | Giants |\n| 21–25 | Constructs | 76–80 | Monstrosities |\n| 26–35 | Dragons | 81–85 | Oozes |\n| 36–45 | Elementals | 86–90 | Plants |\n| 46–50 | Humanoids | 91–00 | Undead |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules"],"source_type":"srd","item_type":"Weapon (Any Ammunition)","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-amulet-of-health","name":"Amulet of Health","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":4,"action_type":null,"uses":null,"recharge":null,"summary":"Your Constitution is 19 while you wear this amulet. It has no effect on you if your Constitution is 19 or higher without it.","description":"Your Constitution is 19 while you wear this amulet. It has no effect on you if your Constitution is 19 or higher without it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-amulet-of-proof-against-detection-and-location","name":"Amulet of Proof against Detection and Location","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":5,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this amulet, you can't be targeted by Divination spells or perceived through magical scrying sensors unless you allow it.","description":"While wearing this amulet, you can't be targeted by Divination spells or perceived through magical scrying sensors unless you allow it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-amulet-of-the-planes","name":"Amulet of the Planes","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":6,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this amulet, you can take a Magic action to name a location that you are familiar with on another plane of existence.","description":"While wearing this amulet, you can take a Magic action to name a location that you are familiar with on another plane of existence. Then make a DC 15 Intelligence (Arcana) check. On a successful check, you cast _Plane Shift_. On a failed check, you and each creature and object within 15 feet of you travel to a random destination determined by rolling 1d100 and consulting the following table.\n\n| 1d100 | Destination |\n| --- | --- |\n| 01–60 | Random location on the plane you named |\n| 61–70 | Random location on an Inner Plane determined by rolling 1d6: on a 1, the Plane of Air; on a 2, the Plane of Earth; on a 3, the Plane of Fire; on a 4, the Plane of Water; on a 5, the Feywild; on a 6, the Shadowfell |\n| 71–80 | Random location on an Outer Plane determined by rolling 1d8: on a 1, Arborea; on a 2, Arcadia; on a 3, the Beastlands; on a 4, Bytopia; on a 5, Elysium; on a 6, Mechanus; on a 7, Mount Celestia; on an 8, Ysgard |\n| 81–90 | Random location on an Outer Plane determined by rolling 1d8: on a 1, the Abyss; on a 2, Acheron; on a 3, Carceri; on a 4, Gehenna; on a 5, Hades; on a 6, Limbo; on a 7, the Nine Hells; on an 8, Pandemonium |\n| 91–00 | Random location on the Astral Plane |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-animated-shield","name":"Animated Shield","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":7,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this Shield, you can take a Bonus Action to cause it to animate.","description":"While holding this Shield, you can take a Bonus Action to cause it to animate. The Shield leaps into the air and hovers in your space to protect you as if you were wielding it, leaving your hands free. The Shield remains animate for 1 minute, until you take a Bonus Action to end this effect, or until you die or have the Incapacitated condition, at which point the Shield falls to the ground or into your hand if you have one free.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Shield)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-apparatus-of-the-crab","name":"Apparatus of the Crab","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":8,"action_type":null,"uses":null,"recharge":null,"summary":"This item first appears to be a sealed iron barrel weighing 500 pounds.","description":"This item first appears to be a sealed iron barrel weighing 500 pounds. The barrel has a hidden catch, which can be found with a successful DC 20 Intelligence (Investigation) check. Releasing the catch unlocks a hatch at one end of the barrel, allowing two Medium or smaller creatures to crawl inside. Ten levers are set in a row at the far end, each in a neutral position, able to move up or down. When certain levers are used, the apparatus transforms to resemble a giant lobster.\n\nThe _Apparatus of the Crab_ is a Large object with the following statistics: AC 20; HP 200; Speed 30 ft., Swim 30 ft. (or 0 ft. for both if the legs aren't extended); Immunity to Poison and Psychic damage.\n\nTo be used as a vehicle, the apparatus requires one pilot. While the apparatus's hatch is closed, the compartment is airtight and watertight. The compartment holds enough air for 10 hours of breathing, divided by the number of breathing creatures inside.\n\nThe apparatus floats on water. It can also go underwater to a depth of 900 feet. Below that, the vehicle takes 2d6 Bludgeoning damage each minute from pressure.\n\nA creature in the compartment can take a Utilize action to move as many as two of the apparatus's levers up or down. After each use, a lever goes back to its neutral position. Each lever, from left to right, functions as shown in the Apparatus of the Crab Levers table.\n\n**Apparatus of the Crab Levers**\n\n| Lever | Up | Down |\n| --- | --- | --- |\n| 1 | Legs extend, allowing the apparatus to walk and swim. | Legs retract, reducing the apparatus's Speed and Swim Speed to 0 and making it unable to benefit from bonuses to speed. |\n| 2 | Forward window shutter opens. | Forward window shutter closes. |\n| 3 | Side window shutters open (two per side). | Side window shutters close (two per side). |\n| 4 | Two claws extend from the front side of the apparatus. | The claws retract. |\n| 5 | Each extended claw makes the following melee attack: +8 to hit, reach 5 ft. Hit: 7 (2d6) Bludgeoning damage. | Each extended claw makes the following melee attack: +8 to hit, reach 5 ft. Hit: The target has the Grappled condition (escape DC 15). |\n| 6 | The apparatus walks or swims forward provided its legs are extended. | The apparatus walks or swims backward provided its legs are extended. |\n| 7 | The apparatus turns 90 degrees counterclockwise provided its legs are extended. | The apparatus turns 90 degrees clockwise provided its legs are extended. |\n| 8 | Eyelike fixtures emit Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. | The light turns off. |\n| 9 | The apparatus sinks up to 20 feet if it's in liquid. | The apparatus rises up to 20 feet if it's in liquid. |\n| 10 | The rear hatch unseals and opens. | The rear hatch closes and seals. |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-armor-1-2-or-3","name":"Armor, +1, +2, or +3","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":9,"action_type":null,"uses":null,"recharge":null,"summary":"You have a bonus to Armor Class while wearing this armor. The bonus is determined by its rarity.","description":"You have a bonus to Armor Class while wearing this armor. The bonus is determined by its rarity.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","varies","2024 rules"],"source_type":"srd","item_type":"Armor (Any Light, Medium, or Heavy)","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-armor-of-invulnerability","name":"Armor of Invulnerability","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":10,"action_type":null,"uses":null,"recharge":null,"summary":"You have Resistance to Bludgeoning, Piercing, and Slashing damage while you wear this armor.","description":"You have Resistance to Bludgeoning, Piercing, and Slashing damage while you wear this armor.\n\n**_Metal Shell._** You can take a Magic action to give yourself Immunity to Bludgeoning, Piercing, and Slashing damage for 10 minutes or until you are no longer wearing the armor. Once this property is used, it can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Plate Armor)","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-armor-of-resistance","name":"Armor of Resistance","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":11,"action_type":null,"uses":null,"recharge":null,"summary":"You have Resistance to one type of damage while you wear this armor. The GM chooses the type or determines it randomly by rolling on the following table.","description":"You have Resistance to one type of damage while you wear this armor. The GM chooses the type or determines it randomly by rolling on the following table.\n\n| 1d10 | Damage Type | 1d10 | Damage Type |\n| --- | --- | --- | --- |\n| 1 | Acid | 6 | Necrotic |\n| 2 | Cold | 7 | Poison |\n| 3 | Fire | 8 | Psychic |\n| 4 | Force | 9 | Radiant |\n| 5 | Lightning | 10 | Thunder |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Any Light, Medium, or Heavy)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-armor-of-vulnerability","name":"Armor of Vulnerability","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":12,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this armor, you have Resistance to one of the following damage types: Bludgeoning, Piercing, or Slashing. The GM chooses the type or determines it randomly.","description":"While wearing this armor, you have Resistance to one of the following damage types: Bludgeoning, Piercing, or Slashing. The GM chooses the type or determines it randomly.\n\n_Curse._ This armor is cursed, a fact that is revealed only when the _Identify_ spell is cast on the armor or you attune to it. Attuning to the armor curses you until you are targeted by a _Remove Curse_ spell or similar magic; removing the armor fails to end the curse. While cursed, you have Vulnerability to two of the three damage types associated with the armor (not the one to which it grants Resistance).","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Any Light, Medium, or Heavy)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-arrow-catching-shield","name":"Arrow-Catching Shield","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":13,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +2 bonus to Armor Class against ranged attack rolls while you wield this Shield. This bonus is in addition to the Shield's normal bonus to AC.","description":"You gain a +2 bonus to Armor Class against ranged attack rolls while you wield this Shield. This bonus is in addition to the Shield's normal bonus to AC.\n\nWhenever an attacker makes a ranged attack roll against a target within 5 feet of you, you can take a Reaction to become the target of the attack instead.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Shield)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-bag-of-beans","name":"Bag of Beans","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":14,"action_type":null,"uses":null,"recharge":null,"summary":"This heavy cloth bag contains 3d4 dry beans when found. The bag weighs half a pound regardless of how many beans it contains and becomes a non magical item when it no longer contains any beans.","description":"This heavy cloth bag contains 3d4 dry beans when found. The bag weighs half a pound regardless of how many beans it contains and becomes a non-magical item when it no longer contains any beans.\n\nIf you dump one or more beans out of the bag, they explode in a 10-foot-radius Sphere centered on them. All the dumped beans are destroyed in the explosion, and each creature in the Sphere, including you, makes a DC 15 Dexterity saving throw, taking 5d4 Force damage on a failed save or half as much damage on a successful one.\n\nIf you remove a bean from the bag, plant it in dirt or sand, and then water it, the bean disappears as it produces an effect 1 minute later from the ground where it was planted. The GM can choose an effect from the following table or determine it randomly.\n\n| 1d100 | Effect |\n| --- | --- |\n| 01 | 5d4 toadstools sprout. If a creature eats a toadstool, roll any die. On an odd roll, the eater must succeed on a DC 15 Constitution saving throw or take 5d6 Poison damage and have the Poisoned condition for 1 hour. On an even roll, the eater gains 5d6 Temporary Hit Points for 1 hour. |\n| 02–10 | A geyser erupts and spouts water, beer, mayonnaise, tea, vinegar, wine, or oil (GM's choice) 30 feet into the air for 1d4 minutes. |\n| 11–20 | A Treant sprouts. Roll any die. On an odd roll, the treant is Chaotic Evil. On an even roll, the treant is Chaotic Good. |\n| 21–30 | An animate but immobile stone statue in your likeness rises and makes verbal threats against you. If you leave it and others come near, it describes you as the most heinous of villains and directs the newcomers to find and attack you. If you are on the same plane of existence as the statue, it knows where you are. The statue becomes inanimate after 24 hours. |\n| 31–40 | A campfire with green flames springs forth and burns for 24 hours or until it is extinguished. |\n| 41–50 | Three Shrieker Fungi sprout. |\n| 51–60 | 1d4 + 4 bright-pink toads crawl forth. Whenever a toad is touched, it transforms into a Large or smaller monster of the GM's choice that acts in accordance with its alignment and nature. The monster remains for 1 minute, then disappears in a puff of bright-pink smoke. |\n| 61–70 | A hungry Bulette burrows up and attacks. |\n| 71–80 | A fruit tree grows. It has 1d10 + 20 fruit, 1d8 of which act as randomly determined potions. The tree vanishes after 1 hour. Picked fruit remains, retaining any magic for 30 days. |\n| 81–90 | A nest of 1d4 + 3 rainbow-colored eggs springs up. Any creature that eats an egg makes a DC 20 Constitution saving throw. On a successful save, a creature permanently increases its lowest ability score by 1, randomly choosing among equally low scores. On a failed save, the creature takes 10d6 Force damage from an internal explosion. |\n| 91–95 | A pyramid with a 60-foot-square base bursts upward. Inside is a burial chamber containing a Mummy, a Mummy Lord, or some other Undead of the GM's choice. Its sarcophagus contains treasure of the GM's choice. |\n| 96–00 | A giant beanstalk sprouts, growing to a height of the GM's choice. The top leads where the GM chooses, such as to a great view, a cloud giant's castle, or another plane of existence. |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-bag-of-devouring","name":"Bag of Devouring","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":15,"action_type":null,"uses":null,"recharge":null,"summary":"This bag resembles a Bag of Holding but is a feeding orifice for a gigantic extradimensional creature. Turning the bag inside out closes the orifice.","description":"This bag resembles a _Bag of Holding_ but is a feeding orifice for a gigantic extradimensional creature. Turning the bag inside out closes the orifice.\n\nThe extradimensional creature attached to the bag can sense whatever is placed inside the bag. Animal or vegetable matter placed wholly in the bag is devoured and lost forever. When part of a living creature is placed in the bag, as happens when someone reaches inside it, there is a 50 percent chance that the creature is pulled inside the bag. A creature inside the bag can take an action to try to escape, doing so with a successful DC 15 Strength (Athletics) check. Another creature can take an action to reach into the bag to pull a creature out, doing so with a successful DC 20 Strength (Athletics) check, provided the puller isn't pulled inside the bag first. Any creature that starts its turn inside the bag is devoured, its body destroyed.\n\nInanimate objects can be stored in the bag, which can hold a cubic foot of such material. However, once each day, the bag swallows any objects inside it and spits them out into another plane of existence. The GM determines the time and plane.\n\nIf the bag is pierced or torn, it is destroyed, and anything contained within it is transported to a random location on the Astral Plane.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-bag-of-holding","name":"Bag of Holding","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":16,"action_type":null,"uses":null,"recharge":null,"summary":"This bag has an interior space considerably larger than its outside dimensions—roughly 2 feet square and 4 feet deep on the inside.","description":"This bag has an interior space considerably larger than its outside dimensions—roughly 2 feet square and 4 feet deep on the inside. The bag can hold up to 500 pounds, not exceeding a volume of 64 cubic feet. The bag weighs 5 pounds, regardless of its contents. Retrieving an item from the bag requires a Utilize action.\n\nIf the bag is overloaded, pierced, or torn, it is destroyed, and its contents are scattered in the Astral Plane. If the bag is turned inside out, its contents spill forth unharmed, but the bag must be put right before it can be used again. The bag holds enough air for 10 minutes of breathing, divided by the number of breathing creatures inside.\n\nPlacing a _Bag of Holding_ inside an extradimensional space created by a _Handy Haversack_, _Portable Hole_, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within a 10-foot-radius Sphere centered on the gate is sucked through it to a random location on the Astral Plane. The gate then closes. The gate is one-way and can't be reopened.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-bag-of-tricks","name":"Bag of Tricks","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":17,"action_type":null,"uses":null,"recharge":null,"summary":"This bag made from gray, rust, or tan cloth appears empty. Reaching inside the bag, however, reveals the presence of a small, fuzzy object.","description":"This bag made from gray, rust, or tan cloth appears empty. Reaching inside the bag, however, reveals the presence of a small, fuzzy object.\n\nYou can take a Magic action to pull the fuzzy object from the bag and throw it up to 20 feet. When the object lands, it transforms into a creature you determine by rolling on the table that corresponds to the bag's color. See \"Monsters\" for the creature's stat block. The creature vanishes at the next dawn or when it is reduced to 0 Hit Points.\n\nThe creature is Friendly to you and your allies, and it acts immediately after you on your Initiative count. You can take a Bonus Action to command how the creature moves and what action it takes on its next turn, such as attacking an enemy. In the absence of such orders, the creature acts in a fashion appropriate to its nature.\n\nOnce three fuzzy objects have been pulled from the bag, the bag can't be used again until the next dawn.\n\n**Gray Bag of Tricks**\n\n| 1d8 | Creature | 1d8 | Creature |\n| --- | --- | --- | --- |\n| 1 | Weasel | 5 | Panther |\n| 2 | Giant Rat | 6 | Giant Badger |\n| 3 | Badger | 7 | Dire Wolf |\n| 4 | Boar | 8 | Giant Elk |\n\n**Rust Bag of Tricks**\n\n| 1d8 | Creature | 1d8 | Creature |\n| --- | --- | --- | --- |\n| 1 | Rat | 5 | Giant Goat |\n| 2 | Owl | 6 | Giant Boar |\n| 3 | Mastiff | 7 | Lion |\n| 4 | Goat | 8 | Brown Bear |\n\n**Tan Bag of Tricks**\n\n| 1d8 | Creature | 1d8 | Creature |\n| --- | --- | --- | --- |\n| 1 | Jackal | 5 | Black Bear |\n| 2 | Ape | 6 | Giant Weasel |\n| 3 | Baboon | 7 | Giant Hyena |\n| 4 | Axe Beak | 8 | Tiger |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-bead-of-force","name":"Bead of Force","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":18,"action_type":null,"uses":null,"recharge":null,"summary":"This small black sphere measures 3/4 of an inch in diameter and weighs an ounce. Typically, 1d4 + 4 Beads of Force are found together.","description":"This small black sphere measures 3/4 of an inch in diameter and weighs an ounce. Typically, 1d4 + 4 _Beads of Force_ are found together.\n\nYou can take a Magic action to throw the bead up to 60 feet. The bead explodes in a 10-foot-radius Sphere on impact and is destroyed. Each creature\nin the Sphere must succeed on a DC 15 Dexterity saving throw or take 5d4 Force damage. A sphere of transparent force then encloses the area for 1 minute. Any creature that failed the save and is completely within the area is trapped inside this sphere. Creatures that succeeded on the save or are partially within the area are pushed away from the center of the sphere until they are no longer inside it. Only breathable air can pass through the sphere's wall. No attack or other effect can pass through.\n\nAn enclosed creature can take a Utilize action to push against the sphere's wall, moving the sphere up to half the creature's Speed. The sphere can be picked up, and its magic causes it to weigh only 1 pound, regardless of the weight of creatures inside.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-bead-of-nourishment","name":"Bead of Nourishment","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":19,"action_type":null,"uses":null,"recharge":null,"summary":"This flavorless, gelatinous bead dissolves on your tongue and provides as much nourishment as 1 day of Rations.","description":"This flavorless, gelatinous bead dissolves on your tongue and provides as much nourishment as 1 day of Rations.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","common","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Common","attunement":null},{"slug":"srd52-magic-item-belt-of-dwarvenkind","name":"Belt of Dwarvenkind","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":20,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this belt, you gain the following benefits:","description":"While wearing this belt, you gain the following benefits:\n\n**Dwarvish.** You know Dwarvish.\n\n**Friend of Dwarvenkind.** You have Advantage on Charisma (Persuasion) checks made to interact with dwarves and duergar.\n\n**Toughness.** Your Constitution increases by 2, to a maximum of 20.\n\nIn addition, while attuned to the belt, you have a 50 percent chance each day at dawn of growing a full beard if you can grow one, or a thicker beard if you already have one.\n\nIf you aren't a dwarf or duergar, you gain the following additional benefits while wearing the belt:\n\n**Darkvision.** You have Darkvision with a range of 60 feet.\n\n**Resilience.** You have Resistance to Poison damage. You also have Advantage on saving throws you make to avoid or end the Poisoned condition.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-belt-of-giant-strength","name":"Belt of Giant Strength","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":21,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this belt, your Strength changes to a score granted by the belt.","description":"While wearing this belt, your Strength changes to a score granted by the belt. The type of giant determines the score (see the table below). The item has no effect on you if your Strength without the belt is equal to or greater than the belt's score.\n\n| Belt | Str. | Rarity |\n| --- | --- | --- |\n| Belt of Giant Strength (hill) | 21 | Rare |\n| Belt of Giant Strength (frost or stone) | 23 | Very Rare |\n| Belt of Giant Strength (fire) | 25 | Very Rare |\n| Belt of Giant Strength (cloud) | 27 | Legendary |\n| Belt of Giant Strength (storm) | 29 | Legendary |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","varies","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Varies","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-berserker-axe","name":"Berserker Axe","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":22,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. In addition, while you are attuned to this weapon, your Hit Point maximum increases by 1 for each level you have attained.","description":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. In addition, while you are attuned to this weapon, your Hit Point maximum increases by 1 for each level you have attained.\n\n_Curse._ This weapon is cursed, and becoming attuned to it extends the curse to you. As long as you remain cursed, you are unwilling to part with the weapon, keeping it within reach at all times. You also have Disadvantage on attack rolls with weapons other than this one.\n\nWhenever another creature damages you while the weapon is in your possession, you must succeed on a DC 15 Wisdom saving throw or go berserk. This berserk state ends when you start your turn and there are no creatures within 60 feet of you that you can see or hear.\n\nWhile berserk, you regard the creature nearest to you that you can see or hear as your enemy. If there are multiple possible creatures, choose one at random. On each of your turns, you must move as close to the creature as possible and take the Attack action, targeting the creature. If you're unable to get close enough to the creature to attack it with the weapon, your turn ends after you've used up all your available movement. If the creature dies or can no longer be seen or heard by you, the next nearest creature that you can see or hear becomes your new target.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Battleaxe, Greataxe, or Halberd)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-boots-of-elvenkind","name":"Boots of Elvenkind","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":23,"action_type":null,"uses":null,"recharge":null,"summary":"While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have Advantage on Dexterity (Stealth) checks.","description":"While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have Advantage on Dexterity (Stealth) checks.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-boots-of-levitation","name":"Boots of Levitation","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":24,"action_type":null,"uses":null,"recharge":null,"summary":"While you wear these boots, you can cast Levitate on yourself.","description":"While you wear these boots, you can cast _Levitate_ on yourself.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-boots-of-speed","name":"Boots of Speed","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":25,"action_type":null,"uses":null,"recharge":null,"summary":"While you wear these boots, you can take a Bonus Action to click the boots' heels together.","description":"While you wear these boots, you can take a Bonus Action to click the boots' heels together. If you do, the boots double your Speed, and any creature that makes an Opportunity Attack against you has Disadvantage on the attack roll. If you click your heels together again, you end the effect.\n\nWhen you've used the boots' property for a total of 10 minutes, the magic ceases to function for you until you finish a Long Rest.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-boots-of-striding-and-springing","name":"Boots of Striding and Springing","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":26,"action_type":null,"uses":null,"recharge":null,"summary":"While you wear these boots, your Speed becomes 30 feet unless your Speed is higher, and your Speed isn't reduced by you carrying weight in excess of your carrying capacity or wearing Heavy Armor.","description":"While you wear these boots, your Speed becomes 30 feet unless your Speed is higher, and your Speed isn't reduced by you carrying weight in excess of your carrying capacity or wearing Heavy Armor.\n\nOnce on each of your turns, you can jump up to 30 feet by spending only 10 feet of movement.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-boots-of-the-winterlands","name":"Boots of the Winterlands","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":27,"action_type":null,"uses":null,"recharge":null,"summary":"These furred boots are snug and feel warm. While wearing them, you gain the following benefits.","description":"These furred boots are snug and feel warm. While wearing them, you gain the following benefits.\n\n_Cold Resistance._ You have Resistance to Cold damage and can tolerate temperatures of 0 degrees Fahrenheit or lower without any additional protection.\n\n_Winter Strider._ You ignore Difficult Terrain created by ice or snow.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-bowl-of-commanding-water-elementals","name":"Bowl of Commanding Water Elementals","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":28,"action_type":null,"uses":null,"recharge":null,"summary":"While this bowl is filled with water and you are within 5 feet of it, you can take a Magic action to summon a Water Elemental.","description":"While this bowl is filled with water and you are within 5 feet of it, you can take a Magic action to summon a Water Elemental. The elemental appears in an unoccupied space as close to the bowl as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The bowl can't be used this way again until the next dawn.\n\nThe bowl is about 1 foot in diameter and half as deep. It holds about 3 gallons.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-bracers-of-archery","name":"Bracers of Archery","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":29,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing these bracers, you have proficiency with the Longbow and Shortbow, and you gain a +2 bonus to damage rolls made with such weapons.","description":"While wearing these bracers, you have proficiency with the Longbow and Shortbow, and you gain a +2 bonus to damage rolls made with such weapons.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-bracers-of-defense","name":"Bracers of Defense","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":30,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing these bracers, you gain a +2 bonus to Armor Class if you are wearing no armor and using no Shield.","description":"While wearing these bracers, you gain a +2 bonus to Armor Class if you are wearing no armor and using no Shield.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-brazier-of-commanding-fire-elementals","name":"Brazier of Commanding Fire Elementals","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":31,"action_type":null,"uses":null,"recharge":null,"summary":"While you are within 5 feet of this brazier, you can take a Magic action to summon a Fire Elemental.","description":"While you are within 5 feet of this brazier, you can take a Magic action to summon a Fire Elemental. The elemental appears in an unoccupied space as close to the brazier as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The brazier can't be used this way again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-brooch-of-shielding","name":"Brooch of Shielding","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":32,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this brooch, you have Resistance to Force damage, and you have Immunity to damage from the Magic Missile spell.","description":"While wearing this brooch, you have Resistance to Force damage, and you have Immunity to damage from the _Magic Missile_ spell.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-broom-of-flying","name":"Broom of Flying","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":33,"action_type":null,"uses":null,"recharge":null,"summary":"This wooden broom functions like a mundane broom until you stand astride it and take a Magic action to make it hover beneath you, at which time it can be ridden in the air.","description":"This wooden broom functions like a mundane broom until you stand astride it and take a Magic action to make it hover beneath you, at which time it can be ridden in the air. It has a Fly Speed of 50 feet. It can carry up to 400 pounds, but its Fly Speed becomes 30 feet while carrying over 200 pounds. The broom stops hovering when you land or when you're no longer riding it.\n\nAs a Magic action, you can send the broom to travel alone to a destination within 1 mile of you if you name the location and are familiar with it. The broom comes back to you when you take a Magic action and use a command word if the broom is still within 1 mile of you.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-candle-of-invocation","name":"Candle of Invocation","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":34,"action_type":null,"uses":null,"recharge":null,"summary":"This candle's magic is activated when the candle is lit, which requires a Magic action.","description":"This candle's magic is activated when the candle is lit, which requires a Magic action. After burning for 4 hours, the candle is destroyed. You can snuff it out early for use at a later time. Deduct the time it burned in increments of 1 minute from its total burn time.\n\nWhile lit, the candle sheds Dim Light in a 30-foot radius. While you are within that light, you have Advantage on D20 Tests. In addition, a Cleric or Druid in the light can cast level 1 spells they have prepared without expending spell slots.\n\nAlternatively, when you light the candle for the first time, you can cast _Gate_ with it. Doing so destroys the candle. The portal created by the spell\nlinks to a particular Outer Plane chosen by the GM or determined by rolling on the following table.\n\n| 1d100 | Outer Plane | 1d100 | Outer Plane |\n| --- | --- | --- | --- |\n| 01–05 | Abyss | 55–59 | Gehenna |\n| 06–10 | Acheron | 60–64 | Hades |\n| 11–17 | Arborea | 65–69 | Limbo |\n| 18–25 | Arcadia | 70–77 | Mechanus |\n| 26–33 | Beastlands | 78–85 | Mount Celestia |\n| 34–41 | Bytopia | 86–90 | Nine Hells |\n| 42–46 | Carceri | 91–95 | Pandemonium |\n| 47–54 | Elysium | 96–00 | Ysgard |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cape-of-the-mountebank","name":"Cape of the Mountebank","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":35,"action_type":null,"uses":null,"recharge":null,"summary":"This cape smells faintly of brimstone. While wearing it, you can use it to cast Dimension Door as a Magic action. This property can't be used again until the next dawn.","description":"This cape smells faintly of brimstone. While wearing it, you can use it to cast _Dimension Door_ as a Magic action. This property can't be used again until the next dawn.\n\nWhen you teleport with that spell, you leave behind a cloud of smoke. The space you left is Lightly Obscured by that smoke until the end of your next turn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-carpet-of-flying","name":"Carpet of Flying","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":36,"action_type":null,"uses":null,"recharge":null,"summary":"You can make this carpet hover and fly by taking a Magic action and using the carpet's command word. It moves according to your directions if you are within 30 feet of it.","description":"You can make this carpet hover and fly by taking a Magic action and using the carpet's command word. It moves according to your directions if you are within 30 feet of it.\n\nFour sizes of _Carpet of Flying_ exist. The GM chooses the size of a given carpet or determines it randomly by rolling on the following table. A carpet can carry up to twice the weight shown on the table, but its Fly Speed is halved if it carries more than its normal capacity.\n\n| 1d100 | Size | Capacity | Fly Speed |\n| --- | --- | --- | --- |\n| 01–20 | 3 ft. × 5 ft. | 200 lb. | 80 feet |\n| 21–55 | 4 ft. × 6 ft. | 400 lb. | 60 feet |\n| 56–80 | 5 ft. × 7 ft. | 600 lb. | 40 feet |\n| 81–00 | 6 ft. × 9 ft. | 800 lb. | 30 feet |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-censer-of-controlling-air-elementals","name":"Censer of Controlling Air Elementals","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":37,"action_type":null,"uses":null,"recharge":null,"summary":"While gently swinging this censer, you can take a Magic action to summon an Air Elemental.","description":"While gently swinging this censer, you can take a Magic action to summon an Air Elemental. The elemental appears in an unoccupied space as close to the censer as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The censer can't be used this way again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-chime-of-opening","name":"Chime of Opening","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":38,"action_type":null,"uses":null,"recharge":null,"summary":"This hollow metal tube measures about 1 foot long and weighs 1 pound.","description":"This hollow metal tube measures about 1 foot long and weighs 1 pound. As a Magic action, you can strike the chime to cast _Knock_. The spell's customary knocking sound is replaced by the clear, ringing tone of the chime, which is audible out to 300 feet.\n\nThe chime can be used 10 times. After the tenth time, it cracks and becomes useless.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-circlet-of-blasting","name":"Circlet of Blasting","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":39,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this circlet, you can cast Scorching Ray with it (+5 to hit). The circlet can't cast this spell again until the next dawn.","description":"While wearing this circlet, you can cast _Scorching Ray_ with it (+5 to hit). The circlet can't cast this spell again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-cloak-of-arachnida","name":"Cloak of Arachnida","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":40,"action_type":null,"uses":null,"recharge":null,"summary":"This fine garment is made of black silk interwoven with faint, silvery threads. While wearing it, you gain the following benefits.","description":"This fine garment is made of black silk interwoven with faint, silvery threads. While wearing it, you gain the following benefits.\n\n_Poison Resistance._ You have Resistance to Poison damage.\n\n_Spider Climb._ You have a Climb Speed equal to your Speed and can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free.\n\n_Spider Walk._ You can't be caught in webs of any sort and can move through webs as if they were Difficult Terrain.\n\n_Web._ You can cast _Web_ (save DC 13). The web created by the spell fills twice its normal area. Once used, this property can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cloak-of-displacement","name":"Cloak of Displacement","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":41,"action_type":null,"uses":null,"recharge":null,"summary":"While you wear this cloak, it magically projects an illusion that makes you appear to be standing in a place near your actual location, causing any creature to have Disadvantage on attack rolls against you.","description":"While you wear this cloak, it magically projects an illusion that makes you appear to be standing in a place near your actual location, causing any creature to have Disadvantage on attack rolls against you. If you take damage, the property ceases to function until the start of your next turn. This property is suppressed while your Speed is 0.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cloak-of-elvenkind","name":"Cloak of Elvenkind","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":42,"action_type":null,"uses":null,"recharge":null,"summary":"While you wear this cloak, Wisdom (Perception) checks made to perceive you have Disadvantage, and you have Advantage on Dexterity (Stealth) checks.","description":"While you wear this cloak, Wisdom (Perception) checks made to perceive you have Disadvantage, and you have Advantage on Dexterity (Stealth) checks.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cloak-of-invisibility","name":"Cloak of Invisibility","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":43,"action_type":null,"uses":null,"recharge":null,"summary":"This cloak has 3 charges and regains 1d3 expended charges daily at dawn.","description":"This cloak has 3 charges and regains 1d3 expended charges daily at dawn. While wearing the cloak, you can take a Magic action to pull its hood over your\nhead and expend 1 charge to give yourself the Invisible condition for 1 hour. The effect ends early if you pull the hood down (no action required) or cease wearing the cloak.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cloak-of-protection","name":"Cloak of Protection","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":44,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to Armor Class and saving throws while you wear this cloak.","description":"You gain a +1 bonus to Armor Class and saving throws while you wear this cloak.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cloak-of-the-bat","name":"Cloak of the Bat","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":45,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this cloak, you have Advantage on Dexterity (Stealth) checks.","description":"While wearing this cloak, you have Advantage on Dexterity (Stealth) checks. In an area of Dim Light or Darkness, you can grip the edges of the cloak and use it to gain a Fly Speed of 40 feet. If you ever fail to grip the cloak's edges while flying in this way, or if you are no longer in Dim Light or Darkness, you lose this Fly Speed.\n\nWhile wearing the cloak in an area of Dim Light or Darkness, you can cast _Polymorph_ on yourself, shape-shifting into a Bat. While in that form, you retain your Intelligence, Wisdom, and Charisma scores. The cloak can't be used this way again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cloak-of-the-manta-ray","name":"Cloak of the Manta Ray","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":46,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this cloak, you can breathe underwater, and you have a Swim Speed of 60 feet.","description":"While wearing this cloak, you can breathe underwater, and you have a Swim Speed of 60 feet.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-crystal-ball","name":"Crystal Ball","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":47,"action_type":null,"uses":null,"recharge":null,"summary":"While touching this crystal orb, you can cast Scrying (save DC 17) with it.","description":"While touching this crystal orb, you can cast _Scrying_ (save DC 17) with it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-crystal-ball-of-mind-reading","name":"Crystal Ball of Mind Reading","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":48,"action_type":null,"uses":null,"recharge":null,"summary":"While touching this crystal orb, you can cast Scrying (save DC 17) with it.","description":"While touching this crystal orb, you can cast _Scrying_ (save DC 17) with it. In addition, you can cast _Detect Thoughts_ (save DC 17) targeting creatures you can see within 30 feet of the spell's sensor. You don't need to concentrate on this _Detect Thoughts_ spell to maintain it during its duration, but it ends if the _Scrying_ spell ends.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-crystal-ball-of-telepathy","name":"Crystal Ball of Telepathy","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":49,"action_type":null,"uses":null,"recharge":null,"summary":"While touching this crystal orb, you can cast Scrying (save DC 17) with it.","description":"While touching this crystal orb, you can cast _Scrying_ (save DC 17) with it. In addition, you can communicate telepathically with creatures you can see within 30 feet of the spell's sensor. You can also cast _Suggestion_ (save DC 17) through the sensor on one of those creatures. You don't need to concentrate on this _Suggestion_ to maintain it during its duration, but it ends if _Scrying_ ends. You can't cast _Suggestion_ in this way again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-crystal-ball-of-true-seeing","name":"Crystal Ball of True Seeing","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":50,"action_type":null,"uses":null,"recharge":null,"summary":"While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you have Truesight with a range of 120 feet centered on the spell's sensor.","description":"While touching this crystal orb, you can cast _Scrying_ (save DC 17) with it. In addition, you have Truesight with a range of 120 feet centered on the spell's sensor.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cube-of-force","name":"Cube of Force","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":51,"action_type":null,"uses":null,"recharge":null,"summary":"This cube is about an inch across.","description":"This cube is about an inch across. Each face has a distinct marking on it. You can press one of those faces, expend the number of charges required for it, and thereby cast the spell associated with it (save DC 17), as shown in the Cube of Force Faces table.\n\nThe cube starts with 10 charges, and it regains 1d6 expended charges daily at dawn.\n\n**Cube of Force Faces**\n\n| Spell | Charge Cost |\n| --- | --- |\n| Mage Armor | 1 |\n| Shield | 1 |\n| Tiny Hut | 3 |\n| Private Sanctum | 4 |\n| Resilient Sphere | 4 |\n| Wall of Force | 5 |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-cubic-gate","name":"Cubic Gate","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":52,"action_type":null,"uses":null,"recharge":null,"summary":"This cube is 3 inches across and radiates palpable magical energy.","description":"This cube is 3 inches across and radiates palpable magical energy. The six sides of the cube are each keyed to a different plane of existence, one of which is the Material Plane. The other sides are linked to planes determined by the GM.\n\nThe cube has 3 charges and regains 1d3 expended charges daily at dawn. As a Magic action, you can expend 1 of the cube's charges to cast one of the following spells using the cube.\n\n_Gate._ Pressing one side of the cube, you cast _Gate_, opening a portal to the plane of existence keyed to that side.\n\n_Plane Shift._ Pressing one side of the cube twice, you cast _Plane Shift_, transporting the targets to the plane of existence keyed to that side.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-dagger-of-venom","name":"Dagger of Venom","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":53,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","description":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.\n\nYou can take a Bonus Action to magically coat the blade with poison. The poison remains for 1 minute or until an attack using this weapon hits a creature. That creature must succeed on a DC 15 Constitution saving throw or take 2d10 Poison damage and have the Poisoned condition for 1 minute. The weapon can't be used this way again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules"],"source_type":"srd","item_type":"Weapon (Dagger)","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-dancing-sword","name":"Dancing Sword","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":54,"action_type":null,"uses":null,"recharge":null,"summary":"You can take a Bonus Action to toss this magic weapon into the air.","description":"You can take a Bonus Action to toss this magic weapon into the air. When you do so, the weapon begins to hover, flies up to 30 feet, and attacks one creature of your choice within 5 feet of itself. The weapon uses your attack roll and adds your ability modifier to damage rolls.\n\nWhile the weapon hovers, you can take a Bonus Action to cause it to fly up to 30 feet to another spot within 30 feet of you. As part of the same Bonus Action, you can cause the weapon to attack one creature within 5 feet of the weapon.\n\nAfter the hovering weapon attacks for the fourth time, it flies back to you and tries to return to your hand. If you have no hand free, the weapon falls to the ground in your space. If the weapon has no unobstructed path to you, it moves as close to you as it can and then falls to the ground. It also ceases to hover if you grasp it or are more than 30 feet away from it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Greatsword, Longsword, Rapier, Scimitar, or Shortsword)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-decanter-of-endless-water","name":"Decanter of Endless Water","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":55,"action_type":null,"uses":null,"recharge":null,"summary":"This stoppered flask sloshes when shaken, as if it contains water. The decanter weighs 2 pounds.","description":"This stoppered flask sloshes when shaken, as if it contains water. The decanter weighs 2 pounds.\n\nYou can take a Magic action to remove the stopper and issue one of three command words, whereupon an amount of fresh water or salt water (your choice) pours out of the flask. The water stops pouring out at the start of your next turn. Choose from the following command words:\n\n**Splash.** The decanter produces 1 gallon of water.\n**Fountain.** The decanter produces 5 gallons of water.\n**Geyser.** The decanter produces 30 gallons of water that gushes forth in a Line 30 feet long and 1 foot wide. If you're holding the decanter, you can aim the geyser in one direction (no action required). One creature of your choice in the Line must succeed on a DC 13 Strength saving throw or take 1d4 Bludgeoning damage and have the Prone condition. Instead of a creature, you can target one object in the Line that isn't being worn or carried and that weighs no more than 200 pounds. The object is knocked over by the geyser.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-deck-of-illusions","name":"Deck of Illusions","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":56,"action_type":null,"uses":null,"recharge":null,"summary":"This box contains a set of cards. A full deck has 34 cards: 32 depicting specific creatures and two with a mirrored surface. A deck found as treasure is usually missing 1d20 − 1 cards.","description":"This box contains a set of cards. A full deck has 34 cards: 32 depicting specific creatures and two with a mirrored surface. A deck found as treasure is usually missing 1d20 − 1 cards.\n\nThe magic of the deck functions only if its cards are drawn at random. You can take a Magic action to draw a card at random from the deck and throw it to the ground at a point within 30 feet of yourself. An illusion of a creature, determined by rolling on the Deck of Illusions table, forms over the thrown card and remains until dispelled. The illusory creature created by the card looks and behaves like a real creature of its kind, except that it can do no harm. While you are within 120 feet of the illusory creature and can see it, you can take a Magic action to move it anywhere within 30 feet of its card.\n\nAny physical interaction with the illusory creature reveals it to be false, because objects pass through it. A creature that takes a Study action to visually inspect the illusory creature identifies it as an illusion with a successful DC 15 Intelligence (Investigation) check. The illusion lasts until its card is moved or the illusion is dispelled (using a _Dispel Magic_ spell or a similar effect). When the illusion ends, the image on its card disappears, and that card can't be used again.\n\n**Deck of Illusions**\n\n| 1d100 | Illusion* |\n| --- | --- |\n| 01–03 | Adult Red Dragon |\n| 04–06 | Archmage |\n| 07–09 | Assassin |\n| 10–12 | Bandit Captain |\n| 13–15 | Basilisk |\n| 16–18 | Berserker |\n| 19–21 | Bugbear Warrior |\n| 22–24 | Cloud Giant |\n| 25–27 | Druid |\n| 28–30 | Erinyes |\n| 31–33 | Ettin |\n| 34–36 | Fire Giant |\n| 37–39 | Frost Giant |\n| 40–42 | Gnoll Warrior |\n| 43–45 | Goblin Warrior |\n| 46–48 | Guardian Naga |\n| 49–51 | Hill Giant |\n| 52–54 | Hobgoblin Warrior |\n| 55–57 | Incubus |\n| 58–60 | Iron Golem |\n| 61–63 | Knight |\n| 64–66 | Kobold Warrior |\n| 67–69 | Lich |\n| 70–72 | Medusa |\n| 73–75 | Night Hag |\n| 76–78 | Ogre |\n| 79–81 | Oni |\n| 82–84 | Priest |\n| 85–87 | Succubus |\n| 88–90 | Troll |\n| 91–93 | Veteran Warrior |\n| 94–96 | Wyvern |\n| 97–00 | The card drawer |\n\n\\*Stat blocks for these creatures (except the card drawer) appear in \"Monsters.\"","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-defender","name":"Defender","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":57,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon.","description":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon.\n\nThe first time you attack with the weapon on each of your turns, you can transfer some or all of the weapon's bonus to your Armor Class. For example, you could reduce the bonus to your attack rolls and damage rolls to +1 and gain a +2 bonus to Armor Class. The adjusted bonuses remain in effect until the start of your next turn, although you must hold the weapon to gain a bonus to AC from it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Any Melee Weapon)","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-demon-armor","name":"Demon Armor","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":58,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this armor, you gain a +1 bonus to Armor Class, and you know Abyssal.","description":"While wearing this armor, you gain a +1 bonus to Armor Class, and you know Abyssal. In addition, the armor's clawed gauntlets allow your Unarmed Strikes to deal 1d8 Slashing damage instead of the usual Bludgeoning damage, and you gain a +1 bonus to the attack and damage rolls of your Unarmed Strikes.\n\n_Curse._ Once you don this cursed armor, you can't doff it unless you are targeted by a _Remove Curse_ spell or similar magic. While wearing the armor, you have Disadvantage on attack rolls against demons and on saving throws against their spells and special abilities.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Any Light, Medium, or Heavy)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-dimensional-shackles","name":"Dimensional Shackles","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":59,"action_type":null,"uses":null,"recharge":null,"summary":"You can take a Utilize action to place these shackles on a creature that has the Incapacitated condition.","description":"You can take a Utilize action to place these shackles on a creature that has the Incapacitated condition. The shackles adjust to fit a creature of Small to Large size. The shackles prevent a creature bound by them from using any method of extradimensional movement, including teleportation or travel to a different plane of existence. They don't prevent the creature from passing through an interdimensional portal.\n\nYou and any creature you designate when you use the shackles can take a Utilize action to remove them. Once every 30 days, the bound creature can make a DC 30 Strength (Athletics) check. On a successful check, the creature breaks free and destroys the shackles.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-dragon-orb","name":"Dragon Orb","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":60,"action_type":null,"uses":null,"recharge":null,"summary":"An orb is an etched crystal globe about 10 inches in diameter. When used, it grows to about 20 inches in diameter, and mist swirls inside it.","description":"An orb is an etched crystal globe about 10 inches in diameter. When used, it grows to about 20 inches in diameter, and mist swirls inside it.\n\nWhile attuned to an orb, you can take a Magic action to peer into the orb's depths. You must then make a DC 15 Charisma saving throw. On a successful save, you control the orb for as long as you remain attuned to it. On a failed save, the orb imposes the Charmed condition on you for as long as you remain attuned to it.\n\nWhile you are Charmed by the orb, you can't voluntarily end your Attunement to it, and the orb casts _Suggestion_ on you at will (save DC 18), urging you to work toward the evil ends it desires. The dragon essence within the orb might want many things: the annihilation of a particular society or organization, freedom from the orb, to spread suffering in the world, to advance the worship of Tiamat, or something else the GM decides.\n\n_Spells._ The orb has 7 charges and regains 1d4 + 3 expended charges daily at dawn. If you control the orb, you can cast one of the spells on the following table from it. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost |\n| --- | --- |\n| Cure Wounds (level 9 version) | 4 |\n| Daylight | 1 |\n| Death Ward | 2 |\n| Detect Magic | 0 |\n| Scrying (save DC 18) | 3 |\n\n_Call Dragons._ While you control the orb, you can take a Magic action to cause the orb to issue a telepathic call that extends in all directions for 40 miles. Chromatic dragons in range feel compelled to come to the orb as soon as possible by the most direct route. Dragon deities such as Tiamat are unaffected by this call. Chromatic dragons drawn to the orb might be Hostile toward you for compelling them against their will. Once you have used this property, it can't be used again for 1 hour.\n\n_Destroying an Orb._ A _Dragon Orb_ has AC 20 and is destroyed if it takes damage from a +3 _Weapon_ or a _Disintegrate_ spell. Nothing else can harm it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","artifact","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Artifact","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-dragon-scale-mail","name":"Dragon Scale Mail","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":61,"action_type":null,"uses":null,"recharge":null,"summary":"Dragon Scale Mail is made of the scales of one kind of dragon.","description":"Dragon Scale Mail is made of the scales of one kind of dragon. Sometimes dragons collect their cast-off\nscales and gift them. Other times, hunters carefully preserve the hide of a dead dragon. In either case, _Dragon Scale Mail_ is highly valued.\n\nWhile wearing this armor, you gain a +1 bonus to Armor Class, you have Advantage on saving throws against the breath weapons of Dragons, and you have Resistance to one damage type determined by the kind of dragon that provided the scales (see the accompanying table).\n\nAdditionally, you can focus your senses as a Magic action to discern the distance and direction to the closest dragon within 30 miles of yourself that is of the same type as the armor. This action can't be used again until the next dawn.\n\n| Dragon | Resistance | Dragon | Resistance |\n| --- | --- | --- | --- |\n| Black | Acid | Gold | Fire |\n| Blue | Lightning | Green | Poison |\n| Brass | Fire | Red | Fire |\n| Bronze | Lightning | Silver | Cold |\n| Copper | Acid | White | Cold |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Scale Mail)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-dragon-slayer","name":"Dragon Slayer","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":62,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","description":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.\n\nThe weapon deals an extra 3d6 damage of the weapon's type if the target is a Dragon.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules"],"source_type":"srd","item_type":"Weapon (Any Simple or Martial)","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-dust-of-disappearance","name":"Dust of Disappearance","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":63,"action_type":null,"uses":null,"recharge":null,"summary":"This powder resembles fine sand.","description":"This powder resembles fine sand. There is enough of it for one use. When you take a Utilize action to throw the dust into the air, you and each creature and object within a 10-foot Emanation originating from you have the Invisible condition for 2d4 minutes. The duration is the same for all subjects, and the dust is consumed when its magic takes effect. Immediately after an affected creature makes an attack roll, deals damage, or casts a spell, the Invisible condition ends for that creature.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-dust-of-dryness","name":"Dust of Dryness","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":64,"action_type":null,"uses":null,"recharge":null,"summary":"This small packet contains 1d6 + 4 pinches of dust.","description":"This small packet contains 1d6 + 4 pinches of dust. As a Utilize action, you can sprinkle a pinch of the dust over water, turning up to a 15-foot Cube of water into one marble-sized pellet, which floats or rests near where the dust was sprinkled. The pellet's weight is negligible. A creature can take a Utilize action to smash the pellet against a hard surface, causing the pellet to shatter and release the water the dust absorbed. Doing so destroys the pellet and ends its magic.\n\nAs a Utilize action, you can sprinkle a pinch of the dust on an Elemental within 5 feet of yourself that is composed mostly of water (such as a **Water Elemental**). Such a creature exposed to a pinch of the dust makes a DC 13 Constitution saving throw, taking 10d6 Necrotic damage on a failed save or half as much damage on a successful one.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-dust-of-sneezing-and-choking","name":"Dust of Sneezing and Choking","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":65,"action_type":null,"uses":null,"recharge":null,"summary":"Found in a small container, this powder resembles Dust of Disappearance , and Identify reveals it to be such. There is enough of it for one use.","description":"Found in a small container, this powder resembles _Dust of Disappearance_, and _Identify_ reveals it to be such. There is enough of it for one use.\n\nAs a Utilize action, you can throw the dust into the air, forcing yourself and every creature in a 30-foot Emanation originating from you to make a DC 15 Constitution saving throw. Constructs, Elementals, Oozes, Plants, and Undead succeed on the save automatically.\n\nOn a failed save, a creature begins sneezing uncontrollably; it has the Incapacitated condition and is suffocating. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success. The effect also ends on any creature targeted by a _Lesser Restoration_ spell.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-dwarven-plate","name":"Dwarven Plate","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":66,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this armor, you gain a +2 bonus to Armor Class. In addition, if an effect moves you against your will along the ground, you can take a Reaction to reduce the distance you are moved by up to 10 feet.","description":"While wearing this armor, you gain a +2 bonus to Armor Class. In addition, if an effect moves you against your will along the ground, you can take a Reaction to reduce the distance you are moved by up to 10 feet.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","very rare","2024 rules"],"source_type":"srd","item_type":"Armor (Half Plate Armor or Plate Armor)","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-dwarven-thrower","name":"Dwarven Thrower","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":67,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon.","description":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. It has the Thrown property with a normal range of 20 feet and a long range of 60 feet. When you hit with a ranged attack using this weapon, it deals an extra 1d8 Force damage, or an extra 2d8 Force damage if the target is a Giant. Immediately after hitting or missing, the weapon flies back to your hand.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Warhammer)","item_rarity":"Very Rare","attunement":"Requires Attunement by a Dwarf or a Creature Attuned to a Belt of Dwarvenkind"},{"slug":"srd52-magic-item-efficient-quiver","name":"Efficient Quiver","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":68,"action_type":null,"uses":null,"recharge":null,"summary":"Each of the quiver's three compartments connects to an extradimensional space that allows the quiver to hold numerous items while never weighing more than 2 pounds.","description":"Each of the quiver's three compartments connects to an extradimensional space that allows the quiver to hold numerous items while never weighing more than 2 pounds. The shortest compartment can hold up to 60 Arrows, Bolts, or similar objects. The midsize compartment holds up to 18 Javelins or similar objects. The longest compartment holds up to 6 long objects, such as bows, Quarterstaffs, or Spears.\n\nYou can draw any item the quiver contains as if doing so from a regular quiver or scabbard.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-efreeti-bottle","name":"Efreeti Bottle","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":69,"action_type":null,"uses":null,"recharge":null,"summary":"When you take a Magic action to remove the stopper of this painted brass bottle, a cloud of thick smoke flows out of it.","description":"When you take a Magic action to remove the stopper of this painted brass bottle, a cloud of thick smoke flows out of it. At the end of your turn, the smoke disappears with a flash of harmless fire, and an **Efreeti** appears in an unoccupied space within 30 feet of you.\n\nThe first time the bottle is opened, the GM rolls on the following table to determine what happens.\n\n| 1d10 | Effect |\n| --- | --- |\n| 1 | The efreeti attacks you. After fighting for 5 rounds, the efreeti disappears, and the bottle loses its magic. |\n| 2–9 | The efreeti understands your languages and obeys your commands for 1 hour, after which it returns to the bottle, and a new stopper contains it. The stopper can't be removed for 24 hours. The next two times the bottle is opened, the same effect occurs. If the bottle is opened a fourth time, the efreeti escapes and disappears, and the bottle loses its magic. |\n| 10 | The efreeti understands your languages and can cast Wish once for you. It disappears when it grants the wish or after 1 hour, and the bottle loses its magic. |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-elemental-gem","name":"Elemental Gem","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":70,"action_type":null,"uses":null,"recharge":null,"summary":"This gem contains a mote of elemental energy.","description":"This gem contains a mote of elemental energy. When you take a Utilize action to break the gem, an elemental is summoned (see \"Monsters\" for its stat block), and the gem ceases to be magical. The elemental appears in an unoccupied space as close to the broken gem as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The type of gem determines the elemental, as shown in the following table.\n\n| Gem | Summoned Elemental |\n| --- | --- |\n| Blue sapphire | Air Elemental |\n| Emerald | Water Elemental |\n| Red corundum | Fire Elemental |\n| Yellow diamond | Earth Elemental |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-elixir-of-health","name":"Elixir of Health","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":71,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you are cured of all magical contagions. In addition, the following conditions end on you: Blinded, Deafened, Paralyzed, and Poisoned.","description":"When you drink this potion, you are cured of all magical contagions. In addition, the following conditions end on you: Blinded, Deafened, Paralyzed, and Poisoned.\n\nThe clear, red liquid has tiny bubbles of light in it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-elven-chain","name":"Elven Chain","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":72,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to Armor Class while you wear this armor. You are considered trained with this armor even if you lack training with Medium or Heavy armor.","description":"You gain a +1 bonus to Armor Class while you wear this armor. You are considered trained with this armor even if you lack training with Medium or Heavy armor.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","rare","2024 rules"],"source_type":"srd","item_type":"Armor (Chain Mail or Chain Shirt)","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-energy-bow","name":"Energy Bow","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":73,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon, which has no string.","description":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon, which has no string. Each time you pull your arm back in a firing motion, a magical arrow made of golden energy appears nocked and ready to fire. An arrow produced by this weapon deals Force damage instead of Piercing damage on a hit, and it disappears after it hits or misses its target. Until it disappears, the arrow emits Bright Light in a 20-foot radius and Dim Light for an additional 20 feet.\n\nThis weapon has the following additional properties.\n\n_Arrow of Restraint._ Whenever you use this weapon to make a ranged attack against a creature, you can try to restrain the target instead of dealing damage to it. If the arrow hits, the target must succeed on a DC 15 Strength saving throw or have the Restrained condition for 1 minute. As an action, a creature Restrained by an arrow can make a DC 20 Strength (Athletics) check to try to break the restraint, ending the effect on itself on a successful check.\n\n_Arrow of Transport._ As a Magic action, you can fire one energy arrow from this weapon at a target you can see within 60 feet of yourself. The target can be either a willing Medium or smaller creature or an object that isn't being worn or carried, provided the object is small enough to fit inside a 5-foot Cube. The arrow teleports the target to an unoccupied space you can see within 10 feet of you.\n\n_Energy Ladder._ As a Magic action, you can loose a flurry of energy arrows from this weapon at a wall up to 60 feet away from yourself. The arrows become glowing rungs that stick out of the wall, forming a magical ladder up to 60 feet long on the wall. This ladder lasts for 1 minute before disappearing.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Longbow or Shortbow)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-eversmoking-bottle","name":"Eversmoking Bottle","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":74,"action_type":null,"uses":null,"recharge":null,"summary":"As a Magic action, you can open or close this bottle.","description":"As a Magic action, you can open or close this bottle. Opening the bottle causes thick smoke to billow out, forming a cloud that fills a 60-foot Emanation originating from the bottle. The area within the smoke is Heavily Obscured.\n\nEach minute the bottle remains open, the size of the Emanation increases by 10 feet until it reaches its maximum size of 120 feet.\nClosing the bottle causes the cloud to become fixed in place until it disperses after 10 minutes. A strong wind (such as that created by the _Gust of Wind_ spell) disperses the cloud after 1 minute.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-eyes-of-charming","name":"Eyes of Charming","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":75,"action_type":null,"uses":null,"recharge":null,"summary":"These crystal lenses fit over the eyes.","description":"These crystal lenses fit over the eyes. They have 3 charges. While wearing them, you can expend 1 or more charges to cast _Charm Person_ (save DC 13). For 1 charge, you cast the level 1 version of the spell. You increase the spell's level by one for each additional charge you expend. The lenses regain all expended charges daily at dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-eyes-of-minute-seeing","name":"Eyes of Minute Seeing","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":76,"action_type":null,"uses":null,"recharge":null,"summary":"These crystal lenses fit over the eyes.","description":"These crystal lenses fit over the eyes. While wearing them, your vision improves significantly out to a range of 1 foot, granting you Darkvision within that range and Advantage on Intelligence (Investigation) checks made to examine something within that range.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-eyes-of-the-eagle","name":"Eyes of the Eagle","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":77,"action_type":null,"uses":null,"recharge":null,"summary":"These crystal lenses fit over the eyes.","description":"These crystal lenses fit over the eyes. While wearing them, you have Advantage on Wisdom (Perception) checks that rely on sight. In conditions of clear visibility, you can make out details of even extremely distant creatures and objects as small as 2 feet across.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-feather-token","name":"Feather Token","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":78,"action_type":null,"uses":null,"recharge":null,"summary":"This object looks like a feather.","description":"This object looks like a feather. Different types of feather tokens exist, each with a different single-use effect. The GM chooses the kind of token or determines it randomly by rolling on the Feather Tokens table. The type of token determines its rarity.\n\n_Anchor (Uncommon)._ You can take a Magic action to touch the token to a boat or ship. For the next 24 hours, the vessel can't be moved by any means. Touching the token to the vessel again ends the effect. When the effect ends, the token disappears.\n\n_Bird (Rare)._ You can take a Magic action to toss the token 5 feet into the air. The token disappears and an enormous, multicolored bird takes its place. The bird has the statistics of a **Roc**, but it can't attack. It obeys your simple commands and can carry up to 500 pounds while flying at its maximum speed (16 miles per hour for a maximum of 144 miles per day, with a 1-hour rest for every 3 hours of flying) or 1,000 pounds at half that speed. The bird disappears after flying its maximum distance for a day or if it drops to 0 Hit Points. You can dismiss the bird as a Magic action.\n\n_Fan (Uncommon)._ If you are on a boat or ship, you can take a Magic action to toss the token up to 10 feet in the air. The token disappears, and a giant flapping fan takes its place. The fan floats and creates a strong wind. This wind can fill the sails of one ship, increasing its speed by 5 miles per hour for 8 hours. You can dismiss the fan as a Magic action.\n\n_Swan Boat (Rare)._ You can take a Magic action to touch the token to a body of water at least 60 feet in diameter. The token disappears, and a 50-foot-long, 20-foot-wide boat shaped like a swan takes its place. The boat is self-propelled and moves across water at a speed of 6 miles per hour. You can take a Magic action while on the boat to command it to move or to turn up to 90 degrees. The boat remains for 24 hours and then disappears. You can dismiss the boat as a Magic action.\n\n_Tree (Uncommon)._ You must be outdoors to use this token. You can take a Magic action to touch it to an unoccupied space on the ground. The token disappears, and in its place a nonmagical oak tree springs into existence. The tree is 60 feet tall and has a 5-foot-diameter trunk, and its branches at the top spread out in a 20-foot radius.\n\n_Whip (Rare)._ You can take a Magic action to throw the token to a point within 10 feet of yourself. The token disappears, and a floating whip takes its place. You can then take a Bonus Action to make a melee spell attack against a creature within 10 feet of the whip, with an attack bonus of +9. On a hit, the target takes 1d6 + 5 Force damage.\n\nAs a Bonus Action, you can direct the whip to fly up to 20 feet and repeat the attack against a creature within 10 feet of the whip. The whip disappears after 1 hour, when you take a Magic action to dismiss it, or when you die or have the Incapacitated condition.\n\n**Feather Tokens**\n\n| 1d100 | Token | Rarity |\n| --- | --- | --- |\n| 01–20 | Anchor | Uncommon |\n| 21–35 | Bird | Rare |\n| 36–50 | Fan | Uncommon |\n| 51–65 | Swan boat | Rare |\n| 66–90 | Tree | Uncommon |\n| 91–00 | Whip | Rare |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","varies","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-figurine-of-wondrous-power","name":"Figurine of Wondrous Power","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":79,"action_type":null,"uses":null,"recharge":null,"summary":"A Figurine of Wondrous Power is a statuette small enough to fit in a pocket.","description":"A _Figurine of Wondrous Power_ is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine's description below. If the space where the creature would appear is occupied by other creatures or objects, or\nif there isn't enough space for the creature, the figurine doesn't become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can't be used again until a certain amount of time has passed, as specified in the figurine's description.\n\n**Bronze Griffon (Rare).** This bronze statuette is of a griffon rampant. It can become a **Griffon** for up to 6 hours. Once it has been used, it can't be used again until 5 days have passed.\n\n**Ebony Fly (Rare).** This ebony statuette, carved in the likeness of a horsefly, can become a **Giant Fly** (see the accompanying stat block) for up to 12 hours and can be ridden as a mount. Once it has been used, it can't be used again until 2 days have passed.\n\n#### Giant Fly\n\n_Large Beast, Unaligned_\n\n**AC** 11 **Initiative** +1 (11)\n**HP** 19 (3d10 + 3)\n**Speed** 30 ft., Fly 60 ft.\n\n|  | MOD | SAVE |  | MOD | SAVE |  | MOD | SAVE |  |  |  |\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\n| STR | 14 | +2 | +2 | DEX | 13 | +1 | +1 | CON | 13 | +1 | +1 |\n| INT | 2 | −4 | −4 | WIS | 10 | +0 | +0 | CHA | 3 | −4 | −4 |\n\n**Senses** Darkvision 60 ft., Passive Perception 10\n**Languages** None\n**CR** 0 (XP 0; PB +2)\n\n**Golden Lions (Rare).** These gold statuettes of lions are always created in pairs. You can use one figurine or both simultaneously. Each can become a **Lion** for up to 1 hour. Once a lion has been used, it can't be used again until 7 days have passed.\n\n**Ivory Goats (Rare).** These ivory statuettes of goats are always created in sets of three. Each goat looks unique and functions differently from the others. Their properties are as follows:\n\n**Goat of Terror.** This figurine can become a **Giant Goat** for up to 3 hours. The goat can't attack, but you can (harmlessly) remove its horns and use them as weapons. One horn becomes a _+1 Lance_, and the other becomes a _+2 Longsword_. Removing a horn requires a Magic action, and the weapons disappear and the horns return when the goat reverts to figurine form. While you ride the goat, any Hostile creature that starts its turn within\n\na 30-foot Emanation originating from the goat must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute, until you are no longer riding the goat, or until the goat reverts to figurine form. The Frightened creature repeats the save at the end of each of its turns, ending the effect on itself on a success. Once it succeeds on the save, a creature is immune to this effect for the next 24 hours. Once the figurine has been used, it can't be used again until 15 days have passed.\n\n**Goat of Traveling.** This figurine can become a Large goat with the same statistics as a **Riding Horse**. It has 24 charges, and each hour or portion thereof it spends in goat form costs 1 charge. While it has charges, you can use it as often as you wish. When it runs out of charges, it reverts to a figurine and can't be used again until 7 days have passed, when it regains all expended charges.\n\n**Goat of Travail.** This figurine can become a Giant **Goat** for up to 3 hours. Once it has been used, it can't be used again until 30 days have passed.\n\n**Marble Elephant (Rare).** This marble statuette resembles a trumpeting elephant. It can become an **Elephant** for up to 24 hours. Once it has been used, it can't be used again until 7 days have passed.\n\n**Obsidian Steed (Very Rare).** This polished obsidian horse can become a **Nightmare** for up to 24 hours. The nightmare fights only to defend itself. Once it has been used, it can't be used again until 5 days have passed.\n\nThe figurine has a 10 percent chance each time you use it to ignore your orders, including a command to revert to figurine form. If you mount the nightmare while it is ignoring your orders, you and the nightmare are instantly transported to a random location on the plane of Hades, where the nightmare reverts to figurine form.\n\n**Onyx Dog (Rare).** This onyx statuette of a dog can become a **Mastiff** for up to 6 hours. The mastiff has an Intelligence of 8 and can speak Common. It also has Blindsight with a range of 60 feet. Once it has been used, it can't be used again until 7 days have passed.\n\n**Serpentine Owl (Rare).** This serpentine statuette of an owl can become a **Giant Owl** for up to 8 hours. The owl can communicate telepathically with you at any range if you and it are on the same plane of existence. Once it has been used, it can't be used again until 2 days have passed.\n\n**Silver Raven (Uncommon).** This silver statuette of a raven can become a **Raven** for up to 12 hours. Once it has been used, it can't be used again until 2 days have passed. While in raven form, the figurine grants you the ability to cast _Animal Messenger_ on it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","varies","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-flame-tongue","name":"Flame Tongue","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":80,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this magic weapon, you can take a Bonus Action and use a command word to cause flames to engulf the damage dealing part of the weapon.","description":"While holding this magic weapon, you can take a Bonus Action and use a command word to cause flames to engulf the damage-dealing part of the weapon. These flames shed Bright Light in a 40-foot radius and Dim Light for an additional 40 feet. While the weapon is ablaze, it deals an extra 2d6 Fire damage on a hit. The flames last until you take a Bonus Action to issue the command again or until you drop, stow, or sheathe the weapon.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Any Melee Weapon)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-folding-boat","name":"Folding Boat","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":81,"action_type":null,"uses":null,"recharge":null,"summary":"This object appears as a wooden box that measures 12 inches long, 6 inches wide, and 6 inches deep.","description":"This object appears as a wooden box that measures 12 inches long, 6 inches wide, and 6 inches deep. It weighs 4 pounds and floats. It can be opened to store items inside. This item also has three command words, each requiring a Magic action to use:\n\n**First Command Word.** The box unfolds into a Rowboat.\n\n**Second Command Word.** The box unfolds into a Keelboat.\n\n**Third Command Word.** The _Folding Boat_ folds back into a box if no creatures are aboard. Any objects in the vessel that can't fit inside the box remain outside the box as it folds. Any objects in the vessel that can fit inside the box do so.\n\nWhen the box becomes a vessel, its weight becomes that of a normal vessel its size, and anything that was stored in the box remains in the boat.\n\nStatistics for the Rowboat and Keelboat appear in \"Equipment.\" If either vessel is reduced to 0 Hit Points, the _Folding Boat_ is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-frost-brand","name":"Frost Brand","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":82,"action_type":null,"uses":null,"recharge":null,"summary":"When you hit with an attack roll using this magic weapon, the target takes an extra 1d6 Cold damage. In addition, while you hold the weapon, you have Resistance to Fire damage.","description":"When you hit with an attack roll using this magic weapon, the target takes an extra 1d6 Cold damage. In addition, while you hold the weapon, you have Resistance to Fire damage.\n\nIn freezing temperatures, the weapon sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.\n\nWhen you draw this weapon, you can extinguish all nonmagical flames within 30 feet of yourself. Once used, this property can't be used again for 1 hour.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, or Shortsword)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-gauntlets-of-ogre-power","name":"Gauntlets of Ogre Power","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":83,"action_type":null,"uses":null,"recharge":null,"summary":"Your Strength is 19 while you wear these gauntlets. They have no effect on you if your Strength is 19 or higher without them.","description":"Your Strength is 19 while you wear these gauntlets. They have no effect on you if your Strength is 19 or higher without them.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-gem-of-brightness","name":"Gem of Brightness","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":84,"action_type":null,"uses":null,"recharge":null,"summary":"This prism has 50 charges. While you are holding it, you can take a Magic action and use one of three command words to cause one of the following effects:","description":"This prism has 50 charges. While you are holding it, you can take a Magic action and use one of three command words to cause one of the following effects:\n\n**First Command Word.** The gem sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. This effect doesn't expend a charge. It lasts until you take a Bonus Action to repeat the command word or until you use another function of the gem.\n\n**Second Command Word.** You expend 1 charge and cause the gem to fire a brilliant beam of light at one creature you can see within 60 feet of yourself. The creature must succeed on a DC 15 Constitution saving throw or have the Blinded condition for 1 minute. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success.\n\n**Third Command Word.** You expend 5 charges and cause the gem to flare with intense light in a 30-foot Cone. Each creature in the Cone makes a saving throw as if struck by the beam created with the second command word.\n\nWhen all of the gem's charges are expended, the gem becomes a nonmagical jewel worth 50 GP.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-gem-of-seeing","name":"Gem of Seeing","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":85,"action_type":null,"uses":null,"recharge":null,"summary":"This gem has 3 charges. As a Magic action, you can expend 1 charge. For the next 10 minutes, you have Truesight out to 120 feet when you peer through the gem.","description":"This gem has 3 charges. As a Magic action, you can expend 1 charge. For the next 10 minutes, you have Truesight out to 120 feet when you peer through the gem.\n\nThe gem regains 1d3 expended charges daily at dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-giant-slayer","name":"Giant Slayer","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":86,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","description":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.\n\nWhen you hit a Giant with this weapon, the Giant takes an extra 2d6 damage of the weapon's type and must succeed on a DC 15 Strength saving throw or have the Prone condition.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules"],"source_type":"srd","item_type":"Weapon (Any Simple or Martial)","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-glamoured-studded-leather","name":"Glamoured Studded Leather","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":87,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this armor, you gain a +1 bonus to Armor Class.","description":"While wearing this armor, you gain a +1 bonus to Armor Class. You can also take a Bonus Action to\ncause the armor to assume the appearance of a normal set of clothing or some other kind of armor. You decide what it looks like—including color, style, and accessories—but the armor retains its normal bulk and weight. The illusory appearance lasts until you use this property again or doff the armor.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","rare","2024 rules"],"source_type":"srd","item_type":"Armor (Studded Leather Armor)","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-gloves-of-missile-snaring","name":"Gloves of Missile Snaring","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":88,"action_type":null,"uses":null,"recharge":null,"summary":"If you're hit by an attack roll made with a Ranged or Thrown weapon while wearing these gloves, you can take a Reaction to reduce the damage by 1d10 plus your Dexterity modifier if you have a free hand.","description":"If you're hit by an attack roll made with a Ranged or Thrown weapon while wearing these gloves, you can take a Reaction to reduce the damage by 1d10 plus your Dexterity modifier if you have a free hand. If you reduce the damage to 0, you can catch the ammunition or weapon if it is small enough for you to hold in that hand.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-gloves-of-swimming-and-climbing","name":"Gloves of Swimming and Climbing","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":89,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing these gloves, you have a Climb Speed and a Swim Speed equal to your Speed, and you gain a +5 bonus to Strength (Athletics) checks made to climb or swim.","description":"While wearing these gloves, you have a Climb Speed and a Swim Speed equal to your Speed, and you gain a +5 bonus to Strength (Athletics) checks made to climb or swim.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-gloves-of-thievery","name":"Gloves of Thievery","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":90,"action_type":null,"uses":null,"recharge":null,"summary":"These gloves are imperceptible while worn. While wearing them, you gain a +5 bonus to Dexterity (Sleight of Hand) checks.","description":"These gloves are imperceptible while worn. While wearing them, you gain a +5 bonus to Dexterity (Sleight of Hand) checks.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-goggles-of-night","name":"Goggles of Night","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":91,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing these dark lenses, you have Darkvision out to 60 feet. If you already have Darkvision, wearing the goggles increases its range by 60 feet.","description":"While wearing these dark lenses, you have Darkvision out to 60 feet. If you already have Darkvision, wearing the goggles increases its range by 60 feet.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-hammer-of-thunderbolts","name":"Hammer of Thunderbolts","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":92,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","description":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.\n\nThe weapon has 5 charges. You can expend 1 charge and make a ranged attack with the weapon, hurling it as if it had the Thrown property with a normal range of 20 feet and a long range of 60 feet. If the attack hits, the weapon unleashes a thunderclap audible out to 300 feet. The target and every creature within 30 feet of it other than you must succeed on a DC 17 Constitution saving throw or have the Stunned condition until the end of your next turn. Immediately after hitting or missing, the weapon flies back to your hand. The weapon regains 1d4 + 1 expended charges daily at dawn.\n\n_Giant's Bane._ While you are attuned to the weapon and wearing either a _Belt of Giant Strength_ or _Gauntlets of Ogre Power_ to which you are also attuned, you gain the following benefits:\n\n_Giants' Bane._ When you roll a 20 on the d20 for an attack roll made with this weapon against a Giant, the creature must succeed on a DC 17 Constitution saving throw or die.\n\n_Might of Giants._ The Strength score bestowed by your _Belt of Giant Strength_ or _Gauntlets of Ogre Power_ increases by 4, to a maximum of 30.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Maul or Warhammer)","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-handy-haversack","name":"Handy Haversack","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":93,"action_type":null,"uses":null,"recharge":null,"summary":"This backpack has a central pouch and two side pouches, each of which is an extradimensional space.","description":"This backpack has a central pouch and two side pouches, each of which is an extradimensional space. Each side pouch can hold up to 200 pounds of material, not exceeding a volume of 25 cubic feet. The central pouch can hold up to 500 pounds of material, not exceeding a volume of 64 cubic feet. The haversack always weighs 5 pounds, regardless of its contents.\n\nRetrieving an item from the haversack requires a Utilize action or a Bonus Action (your choice). When you reach into the haversack for a specific item, the item is always magically on top.\n\nIf any of its pouches is overloaded, pierced, or torn, the haversack ruptures and is destroyed. If the haversack is destroyed, its contents are lost forever, although an Artifact always turns up again somewhere. If the haversack is turned inside out, its contents spill forth unharmed, and the haversack must be put right before it can be used again.\n\nEach pouch of the haversack holds enough air for 10 minutes of breathing, divided by the number of breathing creatures inside.\n\nPlacing the haversack inside an extradimensional space created by a _Bag of Holding_, _Portable Hole_, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate and not behind Total Cover is sucked through it and deposited in a random location on the Astral Plane. The gate then closes. The gate is one-way only and can't be reopened.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-hat-of-disguise","name":"Hat of Disguise","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":94,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this hat, you can cast the Disguise Self spell. The spell ends if the hat is removed.","description":"While wearing this hat, you can cast the _Disguise Self_ spell. The spell ends if the hat is removed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-hat-of-many-spells","name":"Hat of Many Spells","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":95,"action_type":null,"uses":null,"recharge":null,"summary":"This pointed hat has the following properties.","description":"This pointed hat has the following properties.\n\n_Spellcasting Focus._ While holding the hat, you can use it as a Spellcasting Focus for your Wizard spells. Any spell you cast using the hat gains a special Somatic component: you must reach into the hat and \"pull\" the spell out of it.\n_Unknown Spell._ While holding the hat, you can try to cast a level 1+ spell you don't know. The spell must be on the Wizard spell list, it must be of a level you can cast, and it can't have Material components costing more than 1,000 GP. Once you decide on the spell, you must expend a spell slot of the spell's level. Then, to determine whether you cast the spell, make an Intelligence (Arcana) check (DC 10 plus the spell's level). On a successful check, you cast the spell using its normal casting time, and you can't use this property again until you finish a Short or Long Rest. On a failed check, you fail to cast the spell and a random effect occurs instead, determined by rolling on the following table.\n\nAny spell you cast from the hat uses your spell save DC and spell attack bonus.\n\n| 1d100 | Effect |\n| --- | --- |\n| 01–50 | You cast a random spell determined by rolling 1d10: on a **1**, *Enlarge/Reduce* (enlarge effect); on a **2**, *Enlarge/Reduce* (reduce effect); on a **3**, *Faerie Fire*; on a **4**, *Fireball*; on a **5**, *Gust of Wind*; on a **6**, *Invisibility* (cast on yourself); on a **7**, *Lightning Bolt*; on an **8**, *Phantasmal Force*; on a **9**, *Polymorph*; on a **10**, *Stinking Cloud*. |\n| 51–55 | You have the Stunned condition until the end of your next turn, believing something awesome just happened. |\n| 56–60 | A harmless swarm of butterflies fills a 10-foot Cube within 30 feet of yourself. The swarm disperses after 1 minute. |\n| 61–65 | You pull a nonmagical object out of the hat. Roll 1d4 to determine the object: on a **1**, a vial of Acid; on a **2**, a flask of Alchemist's Fire; on a **3**, a Crowbar; on a **4**, a lit Torch. |\n| 66–70 | You suffer a bout of magic sickness and have the Poisoned condition for 1 hour. |\n| 71–75 | You have the Petrified condition until the end of your next turn. |\n| 76–80 | You pull a nonmagical object out of the hat. Roll 1d4 to determine the object: on a **1**, a Dagger; on a **2**, a Rope with a Grappling Hook tied to one end; on a **3**, a bag of Caltrops; on a **4**, a gem worth 50 GP. |\n| 81–85 | A creature appears in an unoccupied space as close to you as possible. The creature isn't under your control and acts as it normally would, and it disappears after 1 hour or when it drops to 0 Hit Points. Roll 1d4 to determine the creature: on a **1**, a **Camel**; on a **2**, a **Constrictor Snake**; on a **3**, an **Elephant**; on a **4**, a **Mule**. |\n| 86–90 | A Hostile **Swarm of Bats** flies out of the hat, occupies your space, and attacks you. |\n| 91–95 | A vertical, 10-foot-diameter, two-way portal to another plane of existence opens in an unoccupied space within 30 feet of you and remains open until the end of your next turn. The GM determines where it leads. |\n| 96–00 | You pull a magic item out of the hat. Roll 1d6 to determine the item's rarity: on a **1–3**, Common; on a **4–5**, Uncommon; on a **6**, Rare. The GM chooses the item, which disappears after 1 hour if it's not consumed or destroyed before then. |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":"Requires Attunement by a Wizard"},{"slug":"srd52-magic-item-headband-of-intellect","name":"Headband of Intellect","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":96,"action_type":null,"uses":null,"recharge":null,"summary":"Your Intelligence is 19 while you wear this headband. It has no effect on you if your Intelligence is 19 or higher without it.","description":"Your Intelligence is 19 while you wear this headband. It has no effect on you if your Intelligence is 19 or higher without it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-helm-of-brilliance","name":"Helm of Brilliance","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":97,"action_type":null,"uses":null,"recharge":null,"summary":"This helm is set with 1d10 diamonds, 2d10 rubies, 3d10 fire opals, and 4d10 opals. Any gem pried from the helm crumbles to dust. When all the gems are removed or destroyed, the helm loses its magic.","description":"This helm is set with 1d10 diamonds, 2d10 rubies, 3d10 fire opals, and 4d10 opals. Any gem pried from the helm crumbles to dust. When all the gems are removed or destroyed, the helm loses its magic.\n\nYou gain the following benefits while wearing the helm.\n\n_Diamond Light._ As long as it has at least one diamond, the helm emits a 30-foot Emanation. When at least one Undead is within that area, the Emanation is filled with Dim Light. Any Undead that starts its turn in that area takes 1d6 Radiant damage.\n\n_Fire Opal Flames._ As long as the helm has at least one fire opal, you can take a Magic action to cause one weapon you are holding to burst into flames. The flames emit Bright Light in a 10-foot radius and Dim Light for an additional 10 feet. The flames are harmless to you and the weapon. When you hit with an attack using the blazing weapon, the target takes an extra 1d6 Fire damage. The flames last until you take a Bonus Action to extinguish them or until you drop or stow the weapon.\n\n_Ruby Resistance._ As long as the helm has at least one ruby, you have Resistance to Fire damage.\n\n_Spells._ You can cast one of the following spells (save DC 18), using one of the helm's gems of the specified type as a component: _Daylight_ (opal), _Fireball_ (fire opal), _Prismatic Spray_ (diamond), or _Wall of Fire_ (ruby). The gem is destroyed when the spell is cast and disappears from the helm.\n\n_Taking Fire Damage._ Roll 1d20 if you are wearing the helm and take Fire damage as a result of failing\na saving throw against a spell. On a roll of 1, the helm emits beams of light from its remaining gems and is then destroyed. Each creature within a 60-foot Emanation originating from you must succeed on a DC 17 Dexterity saving throw or be struck by a beam, taking Radiant damage equal to the number of gems in the helm.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-helm-of-comprehending-languages","name":"Helm of Comprehending Languages","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":98,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this helm, you can cast Comprehend Languages from it.","description":"While wearing this helm, you can cast _Comprehend Languages_ from it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-helm-of-telepathy","name":"Helm of Telepathy","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":99,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this helm, you have telepathy with a range of 30 feet, and you can cast Detect Thoughts or Suggestion (save DC 13) from the helm.","description":"While wearing this helm, you have telepathy with a range of 30 feet, and you can cast _Detect Thoughts_ or _Suggestion_ (save DC 13) from the helm. Once either spell is cast from the helm, that spell can't be cast from it again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-helm-of-teleportation","name":"Helm of Teleportation","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":100,"action_type":null,"uses":null,"recharge":null,"summary":"This helm has 3 charges. While wearing it, you can expend 1 charge to cast Teleport from it. The helm regains 1d3 expended charges daily at dawn.","description":"This helm has 3 charges. While wearing it, you can expend 1 charge to cast _Teleport_ from it. The helm regains 1d3 expended charges daily at dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-holy-avenger","name":"Holy Avenger","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":101,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a Fiend or an Undead with it, that creature takes an extra 2d10 Radiant damage.","description":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a Fiend or an Undead with it, that creature takes an extra 2d10 Radiant damage.\n\nWhile you hold the drawn weapon, it creates a 10-foot Emanation originating from you. You and all creatures Friendly to you in the Emanation have Advantage on saving throws against spells and other magical effects. If you have 17 or more levels in the Paladin class, the size of the Emanation increases to 30 feet.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Any Simple or Martial)","item_rarity":"Legendary","attunement":"Requires Attunement by a Paladin"},{"slug":"srd52-magic-item-horn-of-blasting","name":"Horn of Blasting","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":102,"action_type":null,"uses":null,"recharge":null,"summary":"You can take a Magic action to blow the horn, which emits a thunderous blast in a 30 foot Cone that is audible out to 600 feet.","description":"You can take a Magic action to blow the horn, which emits a thunderous blast in a 30-foot Cone that is audible out to 600 feet. Each creature in the Cone makes a DC 15 Constitution saving throw. On a failed save, a creature takes 5d8 Thunder damage and has the Deafened condition for 1 minute. On a successful save, a creature takes half as much damage only. Glass or crystal objects in the Cone that aren't being worn or carried take 10d8 Thunder damage.\n\nEach use of the horn's magic has a 20 percent chance of causing the horn to explode. The explosion deals 10d6 Force damage to the user and destroys the horn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-horn-of-valhalla","name":"Horn of Valhalla","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":103,"action_type":null,"uses":null,"recharge":null,"summary":"You can take a Magic action to blow this horn.","description":"You can take a Magic action to blow this horn. In response, warrior spirits from the plane of Ysgard appear in unoccupied spaces within 60 feet of you. Each spirit uses the **Berserker** stat block and returns to Ysgard after 1 hour or when it drops to 0 Hit Points. The spirits look like living, breathing warriors, and they have Immunity to the Charmed and Frightened conditions. Once you use the horn, it can't be used again until 7 days have passed.\n\nFour types of _Horn of Valhalla_ are known to exist, each made of a different metal. The horn's type determines how many spirits it summons, as well as the requirement for its use. The GM chooses the horn's type or determines it randomly by rolling on the following table.\n\nIf you blow the horn without meeting its requirement, the summoned spirits attack you. If you meet the requirement, they are Friendly to you and your allies and follow your commands.\n\n| 1d100 | Horn Type | Spirits | Requirement |\n| --- | --- | --- | --- |\n| 01–40 | Silver | 2 | None |\n| 41–75 | Brass | 3 | Proficiency with all Simple weapons |\n| 76–90 | Bronze | 4 | Training with all Medium armor |\n| 91–00 | Iron | 5 | Proficiency with all Martial weapons |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","varies","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-horseshoes-of-a-zephyr","name":"Horseshoes of a Zephyr","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":104,"action_type":null,"uses":null,"recharge":null,"summary":"These horseshoes come in a set of four.","description":"These horseshoes come in a set of four. As a Magic action, you can touch one of the horseshoes to the hoof of a horse or similar creature, whereupon the horseshoe affixes itself to the hoof. Removing a horseshoe also takes a Magic action.\n\nWhile all four shoes are affixed to the hooves of a horse or similar creature, they allow the creature to move normally while floating 4 inches above a surface. This effect means the creature can cross or stand above nonsolid or unstable surfaces, such as water or lava. The creature leaves no tracks and ignores Difficult Terrain. In addition, the creature can travel for up to 12 hours a day without gaining Exhaustion levels from extended travel.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-horseshoes-of-speed","name":"Horseshoes of Speed","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":105,"action_type":null,"uses":null,"recharge":null,"summary":"These horseshoes come in a set of four.","description":"These horseshoes come in a set of four. As a Magic action, you can touch one of the horseshoes to the hoof of a horse or similar creature, whereupon the horseshoe affixes itself to the hoof. Removing a horseshoe also takes a Magic action.\n\nWhile all four horseshoes are attached to the same creature, its Speed is increased by 30 feet.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-immovable-rod","name":"Immovable Rod","category":"Rod","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":106,"action_type":null,"uses":null,"recharge":null,"summary":"This iron rod has a button on one end.","description":"This iron rod has a button on one end. You can take a Utilize action to press the button, which causes the rod to become magically fixed in place. Until you or another creature takes a Utilize action to push the button again, the rod doesn't move, even if it defies gravity. The rod can hold up to 8,000 pounds of weight. More weight causes the rod to deactivate and fall. A creature can take a Utilize action to make a DC 30 Strength (Athletics) check, moving the fixed rod up to 10 feet on a successful check.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","rod","uncommon","2024 rules"],"source_type":"srd","item_type":"Rod","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-instant-fortress","name":"Instant Fortress","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":107,"action_type":null,"uses":null,"recharge":null,"summary":"As a Magic action, you can place this 1 inch adamantine statuette on the ground and, using a command word, cause it to grow rapidly into a square adamantine tower.","description":"As a Magic action, you can place this 1-inch adamantine statuette on the ground and, using a command word, cause it to grow rapidly into a square adamantine tower. Repeating the command word causes the tower to revert to statuette form, which works only if the tower is empty. Each creature in the area where the tower appears is pushed to an unoccupied space outside but next to the tower. Objects in the area that aren't being worn or carried are also pushed clear of the tower.\n\nThe tower is 20 feet on a side and 30 feet high, with arrow slits on all sides and a battlement atop it. Its interior is divided into two floors, with a ladder, staircase, or ramp (your choice) connecting them. This ladder, staircase, or ramp ends at a trapdoor leading to the roof. When created, the tower has a single door at ground level on the side facing you. The door opens only at your command, which you can issue as a Bonus Action. It is immune to the _Knock_ spell and similar magic.\n\nMagic prevents the tower from being tipped over. The roof, the door, and the walls each have AC 20; HP 100; Immunity to Bludgeoning, Piercing, and Slashing damage except that which is dealt by siege equipment; and Resistance to all other damage.\n\nShrinking the tower back down to statuette form doesn't repair damage to the tower. Only a _Wish_ spell can repair the tower (this use of the spell counts as replicating a spell of level 8 or lower). Each casting of _Wish_ causes the tower to regain all its Hit Points.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ioun-stone","name":"Ioun Stone","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":108,"action_type":null,"uses":null,"recharge":null,"summary":"Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of Ioun Stones exist, each type a distinct combination of shape and color.","description":"Roughly marble sized, _Ioun Stones_ are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of _Ioun Stones_ exist, each type a distinct combination of shape and color.\n\nWhen you take a Magic action to toss an _Ioun Stone_ into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you while doing so. You can have up to three _Ioun Stones_ orbiting your head at the same time.\n\nEach _Ioun Stone_ orbiting your head is considered to be an object you are wearing. The orbiting stone avoids contact with other creatures and objects, adjusting its orbit to avoid collisions and thwarting all attempts by other creatures to attack or snatch it.\n\nAs a Utilize action, you can seize and stow any number of _Ioun Stones_ orbiting your head. If your Attunement to an _Ioun Stone_ ends while it's orbiting your head, the stone falls as though you had dropped it.\n\nThe type of stone determines its rarity and effects.\n\n_Absorption (Very Rare)_. While this pale lavender ellipsoid orbits your head, you can take a Reaction to cancel a spell of level 4 or lower cast by a creature you can see. A canceled spell has no effect, and any resources used to cast it are wasted. Once the stone has canceled 20 levels of spells, it burns out, turns dull gray, and loses its magic.\n\n_Agility (Very Rare)_. Your Dexterity increases by 2, to a maximum of 20, while this deep-red sphere orbits your head.\n\n_Awareness (Rare)_. While this dark-blue rhomboid orbits your head, you have Advantage on Initiative rolls and Wisdom (Perception) checks.\n\n_Fortitude (Very Rare)_. Your Constitution increases by 2, to a maximum of 20, while this pink rhomboid orbits your head.\n\n_Greater Absorption (Legendary)_. While this marbled lavender and green ellipsoid orbits your head, you can take a Reaction to cancel a spell of level 8 or lower cast by a creature you can see. A canceled spell has no effect, and any resources used to cast it are wasted. Once the stone has canceled 20 levels of spells, it burns out, turns dull gray, and loses its magic.\n\n_Insight (Very Rare)_. Your Wisdom increases by 2, to a maximum of 20, while this incandescent blue sphere orbits your head.\n\n_Intellect (Very Rare)_. Your Intelligence increases by 2, to a maximum of 20, while this marbled scarlet and blue sphere orbits your head.\n\n_Leadership (Very Rare)_. Your Charisma increases by 2, to a maximum of 20, while this marbled pink and green sphere orbits your head.\n_Mastery (Legendary)._ Your Proficiency Bonus increases by 1 while this pale green prism orbits your head.\n\n_Protection (Rare)._ You gain a +1 bonus to Armor Class while this dusty-rose prism orbits your head.\n\n_Regeneration (Legendary)._ You regain 15 Hit Points at the end of each hour this pearly white spindle orbits your head if you have at least 1 Hit Point.\n\n_Reserve (Rare)._ This vibrant purple prism stores spells cast into it, holding them until you use them. The stone can store up to 4 levels of spells at a time. When found, it contains 1d4 levels of stored spells chosen by the GM.\n\nAny creature can cast a spell of level 1 through 4 into the stone by touching it as the spell is cast. The spell has no effect, other than to be stored in the stone. If the stone can't hold the spell, the spell is expended without effect. The level of the slot used to cast the spell determines how much space it uses.\n\nWhile this stone orbits your head, you can cast any spell stored in it. The spell uses the slot level, spell save DC, spell attack bonus, and spellcasting ability of the original caster but is otherwise treated as if you cast the spell. The spell cast from the stone is no longer stored in it, freeing up space.\n\n_Strength (Very Rare)._ Your Strength increases by 2, to a maximum of 20, while this pale blue rhomboid orbits your head.\n\n_Sustenance (Rare)._ You don't need to eat or drink while this clear spindle orbits your head.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","varies","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Varies","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-iron-bands","name":"Iron Bands","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":109,"action_type":null,"uses":null,"recharge":null,"summary":"This rusty iron sphere measures 3 inches in diameter and weighs 1 pound.","description":"This rusty iron sphere measures 3 inches in diameter and weighs 1 pound. You can take a Magic action to throw the sphere at a Huge or smaller creature you can see within 60 feet of yourself. As the sphere moves through the air, it opens into a tangle of metal bands.\n\nMake a ranged attack roll with an attack bonus equal to your Dexterity modifier plus your Proficiency Bonus. On a hit, the target has the Restrained condition until you take a Bonus Action to issue a command that releases it. Doing so or missing with the attack causes the bands to contract and become a sphere once more.\n\nA creature that can touch the bands, including the one Restrained, can take an action to make a DC 20 Strength (Athletics) check to break the iron bands. On a successful check, the item is destroyed, and the Restrained creature is freed. On a failed check, any further attempts made by that creature automatically fail until 24 hours have elapsed.\n\nOnce the bands are used, they can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-iron-flask","name":"Iron Flask","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":110,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this brass stoppered iron flask, you can take a Magic action to target a creature that you can see within 60 feet of yourself.","description":"While holding this brass-stoppered iron flask, you can take a Magic action to target a creature that you can see within 60 feet of yourself. If the flask is empty and the target is native to a plane of existence other than the one you're on, the target must succeed on a DC 17 Wisdom saving throw or be trapped in the flask. If the target has been trapped by the flask before, it has Advantage on the save. Once trapped, a creature remains in the flask until released. The flask can hold only one creature at a time. A creature trapped in the flask doesn't age and doesn't need to breathe, eat, or drink.\n\nYou can take a Magic action to remove the flask's stopper and release the creature in the flask. The creature then obeys your commands for 1 hour, understanding those commands even if it doesn't know the language in which the commands are given. If you issue no commands or give the creature a command that is likely to result in its death or imprisonment, it defends itself but otherwise takes no actions. At the end of the duration, the creature acts in accordance with its normal disposition and alignment.\n\nAn _Identify_ spell reveals if the flask contains a creature, but the only way to determine the type of creature is to open the flask. A newly discovered _Iron Flask_ might already contain a creature chosen by the GM.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-javelin-of-lightning","name":"Javelin of Lightning","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":111,"action_type":null,"uses":null,"recharge":null,"summary":"Each time you make an attack roll with this magic weapon and hit, you can have it deal Lightning damage instead of Piercing damage.","description":"Each time you make an attack roll with this magic weapon and hit, you can have it deal Lightning damage instead of Piercing damage.\n\n_Lightning Bolt._ When you throw this weapon at a target no farther than 120 feet from you, you can forgo making a ranged attack roll and instead turn the weapon into a bolt of lightning. This bolt forms a 5-foot-wide Line between you and the target. The target and each other creature in the Line (excluding you) makes a DC 13 Dexterity saving throw, taking 4d6 Lightning damage on a failed save or half as much damage on a successful one. Immediately after dealing this damage, the weapon reappears in your hand. This property can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","uncommon","2024 rules"],"source_type":"srd","item_type":"Weapon (Javelin)","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-lantern-of-revealing","name":"Lantern of Revealing","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":112,"action_type":null,"uses":null,"recharge":null,"summary":"While lit, this hooded lantern burns for 6 hours on 1 pint of oil, shedding Bright Light in a 30 foot radius and Dim Light for an additional 30 feet.","description":"While lit, this hooded lantern burns for 6 hours on 1 pint of oil, shedding Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. Invisible creatures and objects are visible as long as they are in the lantern's Bright Light. You can take a Utilize\naction to lower the hood, reducing the lantern's light to Dim Light in a 5-foot radius.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-luck-blade","name":"Luck Blade","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":113,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. While the weapon is on your person, you also gain a +1 bonus to saving throws.","description":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. While the weapon is on your person, you also gain a +1 bonus to saving throws.\n\n_Luck._ If the weapon is on your person, you can call on its luck (no action required) to reroll one failed D20 Test if you don't have the Incapacitated condition. You must use the second roll. Once used, this property can't be used again until the next dawn.\n\n_Wish._ The weapon has 1d3 charges. While holding it, you can expend 1 charge and cast _Wish_ from it. Once used, this property can't be used again until the next dawn. The weapon loses this property if it has no charges.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, Sickle, or Shortsword)","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-mace-of-disruption","name":"Mace of Disruption","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":114,"action_type":null,"uses":null,"recharge":null,"summary":"When you hit a Fiend or an Undead with this magic weapon, that creature takes an extra 2d6 Radiant damage.","description":"When you hit a Fiend or an Undead with this magic weapon, that creature takes an extra 2d6 Radiant damage. If the target has 25 Hit Points or fewer after taking this damage, it must succeed on a DC 15 Wisdom saving throw or be destroyed. On a successful save, the creature has the Frightened condition until the end of your next turn.\n\n_Light._ While you hold this weapon, it sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Mace)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-mace-of-smiting","name":"Mace of Smiting","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":115,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. The bonus increases to +3 when you use the weapon to attack a Construct.","description":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. The bonus increases to +3 when you use the weapon to attack a Construct.\n\nWhen you roll a 20 on an attack roll made with this weapon, the target takes an extra 7 Bludgeoning damage, or 14 Bludgeoning damage if it's a Construct. If a Construct has 25 Hit Points or fewer after taking this damage, it is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules"],"source_type":"srd","item_type":"Weapon (Mace)","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-mace-of-terror","name":"Mace of Terror","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":116,"action_type":null,"uses":null,"recharge":null,"summary":"This magic weapon has 3 charges and regains 1d3 expended charges daily at dawn.","description":"This magic weapon has 3 charges and regains 1d3 expended charges daily at dawn. While holding the weapon, you can take a Magic action and expend 1 charge to release a wave of terror from it. Each creature of your choice within 30 feet of you must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute. While\n\nFrightened in this way, a creature must spend its turns trying to move as far away from you as it can, and it can't make Opportunity Attacks. For its action, it can use only the Dash action or try to escape from an effect that prevents it from moving. If it has nowhere it can move, the creature can take the Dodge action. At the end of each of its turns, a creature repeats the save, ending the effect on itself on a success.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Mace)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-mantle-of-spell-resistance","name":"Mantle of Spell Resistance","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":117,"action_type":null,"uses":null,"recharge":null,"summary":"You have Advantage on saving throws against spells while you wear this cloak.","description":"You have Advantage on saving throws against spells while you wear this cloak.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-manual-of-bodily-health","name":"Manual of Bodily Health","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":118,"action_type":null,"uses":null,"recharge":null,"summary":"This book contains health and nutrition tips, and its words are charged with magic.","description":"This book contains health and nutrition tips, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book's contents and practicing its guidelines, your Constitution increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-manual-of-gainful-exercise","name":"Manual of Gainful Exercise","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":119,"action_type":null,"uses":null,"recharge":null,"summary":"This book describes fitness exercises, and its words are charged with magic.","description":"This book describes fitness exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book's contents and practicing its guidelines, your Strength increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-manual-of-golems","name":"Manual of Golems","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":120,"action_type":null,"uses":null,"recharge":null,"summary":"This tome contains information and incantations necessary to make a particular type of golem.","description":"This tome contains information and incantations necessary to make a particular type of golem. The GM chooses the type or determines it randomly by rolling on the accompanying table. To decipher and use the manual, you must be a spellcaster with at least two level 5 spell slots. A creature that can't use a _Manual of Golems_ and attempts to read it takes 6d6 Psychic damage.\n\nTo create a golem, you must spend the time shown on the table, working without interruption with the manual at hand and resting no more than 8 hours per day. You must also pay the specified cost to purchase supplies.\n\nOnce you finish creating the golem, the book is consumed in eldritch flames. The golem becomes animate when the ashes of the manual are sprinkled on it. See \"Monsters\" for the golem's stat block. The golem is under your control, and it understands and obeys your commands.\n\n| 1d20 | Golem | Time | Cost |\n| --- | --- | --- | --- |\n| 1–5 | Clay Golem | 30 days | 65,000 GP |\n| 6–17 | Flesh Golem | 60 days | 50,000 GP |\n| 18 | Iron Golem | 120 days | 100,000 GP |\n| 19–20 | Stone Golem | 90 days | 80,000 GP |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-manual-of-quickness-of-action","name":"Manual of Quickness of Action","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":121,"action_type":null,"uses":null,"recharge":null,"summary":"This book contains coordination and balance exercises, and its words are charged with magic.","description":"This book contains coordination and balance exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book's contents and practicing its guidelines, your Dexterity increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-marvelous-pigments","name":"Marvelous Pigments","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":122,"action_type":null,"uses":null,"recharge":null,"summary":"This fine wooden box contains 1d4 pots of pigment and a brush (weighing 1 pound in total).","description":"This fine wooden box contains 1d4 pots of pigment and a brush (weighing 1 pound in total).\n\nUsing the brush and expending 1 pot of pigment, you can paint any number of three-dimensional objects and terrain features (such as walls, doors, trees, flowers, weapons, webs, and pits), provided these elements are all confined to a 20-foot Cube. The effort takes 10 minutes (regardless of the number of elements you create), during which time you must remain in the Cube, and requires Concentration. If your Concentration is broken or you leave the Cube before the work is done, all the painted elements vanish, and the pot of pigment is wasted.\n\nWhen the work is done, all the painted objects and terrain features become real. Thus, painting a door on a wall creates an actual door, which can be opened to whatever is beyond. Painting a pit creates a real pit, the entire depth of which must lie within the 20-foot Cube.\n\nNo object created by a pot of pigment can have a value greater than 25 GP, and the total value of all objects created by a pot of pigment can't exceed 500 GP. If you paint objects of greater value (such as a large pile of gold), they look authentic, but close inspection reveals they're made from paste, cookies, or some other worthless material.\n\nIf you paint a form of energy such as fire or lightning, the energy dissipates as soon as you complete the painting, doing no harm.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-medallion-of-thoughts","name":"Medallion of Thoughts","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":123,"action_type":null,"uses":null,"recharge":null,"summary":"The medallion has 5 charges. While wearing it, you can expend 1 charge to cast Detect Thoughts (save DC 13) from it. The medallion regains 1d4 expended charges daily at dawn.","description":"The medallion has 5 charges. While wearing it, you can expend 1 charge to cast _Detect Thoughts_ (save DC 13) from it. The medallion regains 1d4 expended charges daily at dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-mirror-of-life-trapping","name":"Mirror of Life Trapping","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":124,"action_type":null,"uses":null,"recharge":null,"summary":"When this 4 foot tall, 2 foot wide mirror is viewed indirectly, its surface shows faint images of creatures.","description":"When this 4-foot-tall, 2-foot-wide mirror is viewed indirectly, its surface shows faint images of creatures. The mirror weighs 50 pounds, and it has AC 11, HP 10, Immunity to Poison and Psychic damage, and Vulnerability to Bludgeoning damage. It shatters and is destroyed when reduced to 0 Hit Points.\n\nIf the mirror is hanging on a vertical surface and you are within 5 feet of it, you can take a Magic action and use a command word to activate it. It remains activated until you take a Magic action and repeat the command word to deactivate it.\n\nAny creature other than you that sees its reflection in the activated mirror while within 30 feet of the mirror must succeed on a DC 15 Charisma saving throw or be trapped, along with anything it is wearing or carrying, in one of the mirror's twelve extradimensional cells. A creature that knows the mirror's nature makes the save with Advantage, and Constructs succeed on the save automatically.\n\nAn extradimensional cell is an infinite expanse filled with thick fog that reduces visibility to 10 feet. Creatures trapped in the mirror's cells don't age, and they don't need to eat, drink, or sleep. A creature trapped within a cell can escape using magic that permits planar travel. Otherwise, the creature is confined to the cell until freed.\n\nIf the mirror traps a creature but its twelve extradimensional cells are already occupied, the mirror frees one trapped creature at random to accommodate the new prisoner. A freed creature appears in an unoccupied space within sight of the mirror but facing away from it. If the mirror is shattered, all creatures it contains are freed and appear in unoccupied spaces near it.\n\nWhile within 5 feet of the mirror, you can take a Magic action to name one creature trapped in it or call out a particular cell by number. The creature named or contained in the named cell appears as an image on the mirror's surface. You and the creature can then communicate.\n\nIn a similar way, you can take a Magic action and use a second command word to free one creature trapped in the mirror. The freed creature appears, along with its possessions, in the unoccupied space nearest to the mirror and facing away from it.\n\nPlacing the mirror inside an extradimensional space created by a _Bag of Holding_, _Portable Hole_, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate and not behind Total Cover is sucked through it to a random location on the Astral Plane. The gate then closes. The gate is one-way only and can't be reopened.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-mithral-armor","name":"Mithral Armor","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":125,"action_type":null,"uses":null,"recharge":null,"summary":"Mithral is a light, flexible metal.","description":"Mithral is a light, flexible metal. Armor made of this substance can be worn under normal clothes. If the armor normally imposes Disadvantage on Dexterity (Stealth) checks or has a Strength requirement, the mithral version of the armor doesn't.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","uncommon","2024 rules"],"source_type":"srd","item_type":"Armor (Any Medium or Heavy, Except Hide Armor)","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-mysterious-deck","name":"Mysterious Deck","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":126,"action_type":null,"uses":null,"recharge":null,"summary":"Usually found in a box or pouch, this deck contains a number of cards made of ivory or vellum.","description":"Usually found in a box or pouch, this deck contains a number of cards made of ivory or vellum. Most (75 percent) of these decks have thirteen cards, but some have twenty-two. Use the appropriate column of the Mysterious Deck table when randomly determining cards drawn from the deck.\n\nBefore you draw a card, you must declare how many cards you intend to draw and then draw them randomly. Any cards drawn in excess of this number have no effect. Otherwise, as soon as you draw a card from the deck, its magic takes effect. You must draw each card no more than 1 hour after the previous draw. If you fail to draw the chosen number, the remaining number of cards fly from the deck on their own and take effect all at once.\n\nOnce a card is drawn, it disappears. Unless the card is the Fool or Jester, the card reappears in the deck, making it possible to draw the same card twice. (Once the Fool or Jester has left the deck, reroll on the table if that card comes up again.)\n\n**Mysterious Deck**\n\n| 1d100 (13-Card Deck) | 1d100 (22-Card Deck) | Card |\n| --- | --- | --- |\n| — | 01–05 | Balance |\n| — | 06–10 | Comet |\n| — | 11–14 | Donjon |\n| 01–08 | 15–18 | Euryale |\n| — | 19–23 | Fates |\n| 09–16 | 24–27 | Flames |\n| — | 28–31 | Fool |\n| — | 32–36 | Gem |\n| 17–24 | 37–41 | Jester |\n| 25–32 | 42–46 | Key |\n| 33–40 | 47–51 | Knight |\n| 41–48 | 52–56 | Moon |\n| — | 57–60 | Puzzle |\n| 49–56 | 61–64 | Rogue |\n| 57–64 | 65–68 | Ruin |\n| — | 69–73 | Sage |\n\n| 1d100 (13-Card Deck) | 1d100 (22-Card Deck) | Card |\n| --- | --- | --- |\n| 65–72 | 74–77 | Skull |\n| 73–80 | 78–82 | Star |\n| 81–88 | 83–87 | Sun |\n| — | 88–91 | Talons |\n| 89–96 | 92–96 | Throne |\n| 97–00 | 97–00 | Void |\n\nEach card's effect is described below.\n\n_Balance._ You can increase one of your ability scores by 2, to a maximum of 22, provided you also decrease another one of your ability scores by 2. You can't decrease an ability that has a score of 5 or lower. Alternatively, you can choose not to adjust your ability scores, in which case this card has no effect.\n\n_Comet._ The next time you enter combat against one or more Hostile creatures, you can select one of them as your foe when you roll Initiative. If you reduce your foe to 0 Hit Points during that combat, you have Advantage on Death Saving Throws for 1 year. If someone else reduces your chosen foe to 0 Hit Points or you don't choose a foe, this card has no effect.\n\n_Donjon._ You disappear and become entombed in a state of suspended animation in an extradimensional sphere. Everything you're wearing and carrying disappears with you except for Artifacts, which stay behind in the space you occupied when you disappeared. You remain imprisoned until you are found and removed from the sphere. You can't be located by any Divination magic, but a _Wish_ spell can reveal the location of your prison. You draw no more cards.\n\n_Euryale._ The card's medusa-like visage curses you. You take a −2 penalty to saving throws while cursed in this way. Only a god or the magic of the Fates card can end this curse.\n\n_Fates._ Reality's fabric unravels and spins anew, allowing you to avoid or erase one event as if it never happened. You can use the card's magic as soon as you draw the card or at any other time before you die.\n\n_Flames._ A powerful devil becomes your enemy. The devil seeks your ruin and torments you, savoring your suffering before attempting to slay you. This enmity lasts until either you or the devil dies.\n\n_Fool._ You have Disadvantage on D20 Tests for the next 72 hours. Draw another card; this draw doesn't count as one of your declared draws.\n\n_Gem._ Twenty-five pieces of jewelry worth 2,000 GP each or fifty gems worth 1,000 GP each appear at your feet.\n\n_Jester._ You have Advantage on D20 Tests for the next 72 hours, or you can draw two additional cards beyond your declared draws.\n\n_Key._ A Rare or rarer magic weapon with which you are proficient appears on your person. The GM chooses the weapon.\n\n_Knight._ You gain the service of a **Knight**, who magically appears in an unoccupied space you choose within 30 feet of yourself. The knight has the same alignment as you and serves you loyally until death, believing the two of you have been drawn together by fate. Work with your GM to create a name and backstory for this NPC. The GM can use a different stat block to represent the knight, as desired.\n\n_Moon._ You gain the ability to cast _Wish_ 1d3 times.\n\n_Puzzle._ Permanently reduce your Intelligence or Wisdom by 1d4 + 1 (to a minimum score of 1). You can draw one additional card beyond your declared draws.\n\n_Rogue._ An NPC of the GM's choice becomes Hostile toward you. You don't know the identity of this NPC until they or someone else reveals it. Nothing less than a _Wish_ spell or divine intervention can end the NPC's hostility toward you.\n\n_Ruin._ All forms of wealth that you carry or own, other than magic items, are lost to you. Portable property vanishes. Businesses, buildings, and land you own are lost in a way that alters reality the least. Any documentation that proves you should own something lost to this card also disappears.\n\n_Sage._ At any time you choose within one year of drawing this card, you can ask a question in meditation and mentally receive a truthful answer to that question.\n\n_Skull._ An **Avatar of Death** (see the accompanying stat block) appears in an unoccupied space as close to you as possible. The avatar targets only you with its attacks, appearing as a ghostly skeleton clad in a tattered black robe and carrying a spectral scythe. The avatar disappears when it drops to 0 Hit Points or you die. If an ally of yours deals damage to the avatar, that ally summons another **Avatar of Death**. The new avatar appears in an unoccupied space as close to that ally as possible and targets only that ally with its attacks. You and your allies can each summon only one avatar as a consequence of this draw. A creature slain by an avatar can't be restored to life.\n\n_Star._ Increase one of your ability scores by 2, to a maximum of 24.\n\n_Sun._ A magic item (chosen by the GM) appears on your person. In addition, you gain 10 Temporary Hit Points daily at dawn until you die.\n\n_Talons._ Every magic item you wear or carry disintegrates. Artifacts in your possession vanish instead.\n\n_Throne._ You gain proficiency and Expertise in your choice of History, Insight, Intimidation, or Persuasion. In addition, you gain rightful ownership of a small keep somewhere in the world. However, the keep is currently home to one or more monsters, which must be cleared out before you can claim the keep as yours.\n\n_Void._ Your soul is drawn from your body and contained in an object in a place of the GM's choice. One or more powerful beings guard the place. While your soul is trapped in this way, your body is inert, ceases aging, and requires no food, air, or water. A _Wish_ spell can't return your soul to your body, but the spell reveals the location of the object that holds your soul. You draw no more cards.\n\n#### Avatar of Death\n\n_Medium Undead, Neutral Evil_\n\n**AC** 20 **Initiative** +3 (13) <br>\n**HP** Half the HP maximum of its summoner <br>\n**Speed** 60 ft., Fly 60 ft. (hover) <br>\n\n|  |  | MOD | SAVE |  |  | MOD | SAVE |  |  | MOD | SAVE |\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\n| STR | 16 | +3 | +3 | DEX | 16 | +3 | +3 | CON | 16 | +3 | +3 |\n| INT | 16 | +3 | +3 | WIS | 16 | +3 | +3 | CHA | 16 | +3 | +3 |\n\n**Immunities** Necrotic, Poison; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned, Unconscious<br>\n**Senses** Truesight 60 ft., Passive Perception 13<br>\n**Languages** All languages known to its summoner<br>\n**CR** None (XP 0; PB equals its summoner's)\n\n### Traits\n\n<hr>\n\n**_Incorporeal Movement._** The avatar can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.\n\n### Actions\n\n<hr>\n\n**_Multiattack._** The avatar makes a number of Reaping Scythe attacks equal to half the summoner's Proficiency Bonus (rounded up).\n\n**_Reaping Scythe._** _Melee Attack Roll:_ Automatic hit, reach 5 ft. _Hit:_ 7 (1d8 + 3) Slashing damage plus 4 (1d8) Necrotic damage.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-necklace-of-adaptation","name":"Necklace of Adaptation","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":127,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this necklace, you can breathe normally in any environment, and you have Advantage on saving throws made to avoid or end the Poisoned condition.","description":"While wearing this necklace, you can breathe normally in any environment, and you have Advantage on saving throws made to avoid or end the Poisoned condition.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-necklace-of-fireballs","name":"Necklace of Fireballs","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":128,"action_type":null,"uses":null,"recharge":null,"summary":"This necklace has 1d6 + 3 beads hanging from it.","description":"This necklace has 1d6 + 3 beads hanging from it. You can take a Magic action to detach a bead and throw it up to 60 feet away. When it reaches the end of its trajectory, the bead detonates as a level 3 _Fireball_ (save DC 15).\n\nYou can hurl multiple beads, or even the whole necklace, at one time. When you do so, increase the damage of the _Fireball_ by 1d6 for each bead after the first (maximum 12d6).","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-necklace-of-prayer-beads","name":"Necklace of Prayer Beads","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":129,"action_type":null,"uses":null,"recharge":null,"summary":"This necklace has 1d4 + 2 magic beads made from aquamarine, black pearl, or topaz.","description":"This necklace has 1d4 + 2 magic beads made from aquamarine, black pearl, or topaz. It also has many nonmagical beads made from stones such as amber, bloodstone, citrine, coral, jade, pearl, or quartz. If a magic bead is removed from the necklace, that bead loses its magic.\n\nSix types of magic beads exist. The GM decides the type of each bead on the necklace or determines it randomly by rolling on the table below. A necklace can have more than one bead of the same type. To use one, you must be wearing the necklace. Each bead contains a spell that you can cast from it as a Bonus Action (using your spell save DC if a save is necessary). Once a magic bead's spell is cast, that bead can't be used again until the next dawn.\n\n| 1d20 | Bead | Spell |\n| --- | --- | --- |\n| 1–6 | Bead of Blessing | Bless |\n| 7–12 | Bead of Curing | Cure Wounds (level 2 version) |\n| 13–16 | Bead of Favor | Greater Restoration |\n| 17–18 | Bead of Smiting | Shining Smite |\n| 19 | Bead of Summons | Guardian of Faith |\n| 20 | Bead of Wind Walking | Wind Walk |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement by a Cleric, Druid, or Paladin"},{"slug":"srd52-magic-item-nine-lives-stealer","name":"Nine Lives Stealer","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":130,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon.","description":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon.\n\n**_Life Stealing._** The weapon has 1d8 + 1 charges. When you attack a creature that has fewer than 100 Hit Points with this weapon and roll a 20 on the d20 for the attack roll, the creature must succeed on a DC 15 Constitution saving throw or be slain instantly as the sword tears its life force from its body. Constructs and Undead succeed on the save automatically. The weapon loses 1 charge if the creature is slain. When the weapon has no charges remaining, it loses this property.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Any Simple or Martial)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-oathbow","name":"Oathbow","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":131,"action_type":null,"uses":null,"recharge":null,"summary":"When you nock an arrow on this bow, it whispers in Elvish, \"Swift defeat to my enemies.\" When you use this weapon to make a ranged attack, you can utter or sign the following command words: \"Swift death to you who hav…","description":"When you nock an arrow on this bow, it whispers in Elvish, \"Swift defeat to my enemies.\" When you use this weapon to make a ranged attack, you can utter or sign the following command words: \"Swift death to you who have wronged me.\" The target of your attack becomes your sworn enemy until it dies or until dawn 7 days later. You can have only one such sworn enemy at a time. When your sworn enemy dies, you can choose a new one after the next dawn.\n\nWhen you make a ranged attack roll with this weapon against your sworn enemy, you have Advantage on the roll. In addition, your target gains no benefit from Half Cover or Three-Quarters Cover, and you suffer no Disadvantage due to long range. If the attack hits, your sworn enemy takes an extra 3d6 Piercing damage.\n\nWhile your sworn enemy lives, you have Disadvantage on attack rolls with all other weapons.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Longbow or Shortbow)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-oil-of-etherealness","name":"Oil of Etherealness","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":132,"action_type":null,"uses":null,"recharge":null,"summary":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it's wearing and carrying (one additional vial is required for each size category above Medium).","description":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it's wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes. The affected creature then gains the effect of the _Etherealness_ spell for 1 hour.\n\nBeads of this cloudy, gray oil form on the outside of its container and quickly evaporate.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-oil-of-sharpness","name":"Oil of Sharpness","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":133,"action_type":null,"uses":null,"recharge":null,"summary":"One vial of this oil can coat one Melee weapon or twenty pieces of ammunition, but only ammunition and Melee weapons that are nonmagical and deal Slashing or Piercing damage are affected.","description":"One vial of this oil can coat one Melee weapon or twenty pieces of ammunition, but only ammunition and Melee weapons that are nonmagical and deal Slashing or Piercing damage are affected. Applying the oil takes 1 minute, after which the oil magically seeps into whatever it coats, turning the coated weapon into a _+3 Weapon_ or the coated ammunition into _+3 Ammunition_.\n\nThis clear, gelatinous oil sparkles with tiny, ultrathin silver shards.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","very rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-oil-of-slipperiness","name":"Oil of Slipperiness","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":134,"action_type":null,"uses":null,"recharge":null,"summary":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it's wearing and carrying (one additional vial is required for each size category above Medium).","description":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it's wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes. The affected creature then gains the effect of the _Freedom of Movement_ spell for 8 hours.\n\nAlternatively, the oil can be poured on the ground as a Magic action, where it covers a 10-foot square, duplicating the effect of the _Grease_ spell in that area for 8 hours.\n\nThis sticky, black unguent is thick and heavy, but it flows quickly when poured.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","uncommon","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-pearl-of-power","name":"Pearl of Power","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":135,"action_type":null,"uses":null,"recharge":null,"summary":"While this pearl is on your person, you can take a Magic action to regain one expended spell slot of level 3 or lower. Once you use the pearl, it can't be used again until the next dawn.","description":"While this pearl is on your person, you can take a Magic action to regain one expended spell slot of level 3 or lower. Once you use the pearl, it can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement by a Spellcaster"},{"slug":"srd52-magic-item-periapt-of-health","name":"Periapt of Health","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":136,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this pendant, you can take a Magic action to regain 2d4 + 2 Hit Points. Once used, this property can't be used again until the next dawn.","description":"While wearing this pendant, you can take a Magic action to regain 2d4 + 2 Hit Points. Once used, this property can't be used again until the next dawn.\n\nIn addition, you have Advantage on saving throws to avoid or end the Poisoned condition while you wear this pendant.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-periapt-of-proof-against-poison","name":"Periapt of Proof against Poison","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":137,"action_type":null,"uses":null,"recharge":null,"summary":"This delicate silver chain has a brilliant cut black gem pendant. While you wear it, you have Immunity to the Poisoned condition and Poison damage.","description":"This delicate silver chain has a brilliant-cut black gem pendant. While you wear it, you have Immunity to the Poisoned condition and Poison damage.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-periapt-of-wound-closure","name":"Periapt of Wound Closure","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":138,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this pendant, you gain the following benefits.","description":"While wearing this pendant, you gain the following benefits.\n\n**_Life Preservation._** Whenever you make a Death Saving Throw, you can change a roll of 9 or lower to a 10, turning a failed save into a successful one.\n\n**_Natural Healing Boost._** Whenever you roll a Hit Point Die to regain Hit Points, double the number of Hit Points it restores.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-philter-of-love","name":"Philter of Love","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":139,"action_type":null,"uses":null,"recharge":null,"summary":"The next time you see a creature within 10 minutes after drinking this philter, you are charmed by that creature and have the Charmed condition for 1 hour.","description":"The next time you see a creature within 10 minutes after drinking this philter, you are charmed by that creature and have the Charmed condition for 1 hour.\n\nThis rose-hued, effervescent liquid contains one easy-to-miss bubble shaped like a heart.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","uncommon","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-pipes-of-haunting","name":"Pipes of Haunting","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":140,"action_type":null,"uses":null,"recharge":null,"summary":"These pipes have 3 charges and regain 1d3 expended charges daily at dawn.","description":"These pipes have 3 charges and regain 1d3 expended charges daily at dawn. You can take a Magic action to play them and expend 1 charge to create an eerie, spellbinding tune. Each creature of your choice within 30 feet of you must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute. A creature that fails the save repeats it at the end of each of its turns, ending the effect on itself on a success. A creature that succeeds on its save is immune to the effect of these pipes for 24 hours.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-pipes-of-the-sewers","name":"Pipes of the Sewers","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":141,"action_type":null,"uses":null,"recharge":null,"summary":"While these pipes are on your person, ordinary rats and giant rats are Indifferent toward you and won't attack you unless you threaten or harm them.","description":"While these pipes are on your person, ordinary rats and giant rats are Indifferent toward you and won't attack you unless you threaten or harm them.\n\nThe pipes have 3 charges and regain 1d3 expended charges daily at dawn. If you play the pipes as a Magic action, you can take a Bonus Action to expend 1 to 3 charges, calling forth one Swarm of Rats with each expended charge if enough rats are within half a mile of you to be called in this fashion (as determined by the GM). If there aren't enough rats to form a swarm, the charge is wasted. Called swarms move toward the music by the shortest available route but aren't under your control otherwise.\n\nWhenever a Swarm of Rats that isn't under another creature's control comes within 30 feet of you while you are playing the pipes, the swarm makes a DC 15 Wisdom saving throw. On a successful save, the swarm behaves as it normally would and can't be swayed by the pipes' music for the next 24 hours. On a failed save, the swarm is swayed by the pipes' music and becomes Friendly to you and your allies for as long as you continue to play the pipes each round as a Magic action. A Friendly swarm obeys your commands. If you issue no commands to a Friendly swarm, it defends itself but otherwise takes no actions. If a Friendly swarm starts its turn more than 30 feet away from you, your control over that swarm ends, and the swarm behaves as it normally would and can't be swayed by the pipes' music for the next 24 hours.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-plate-armor-of-etherealness","name":"Plate Armor of Etherealness","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":142,"action_type":null,"uses":null,"recharge":null,"summary":"While you're wearing this armor, you can take a Magic action and use a command word to gain the effect of the Etherealness spell.","description":"While you're wearing this armor, you can take a Magic action and use a command word to gain the effect of the _Etherealness_ spell. The spell ends immediately if you remove the armor or take a Magic action to repeat the command word. This property of the armor can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Half Plate Armor or Plate Armor)","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-portable-hole","name":"Portable Hole","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":143,"action_type":null,"uses":null,"recharge":null,"summary":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter.","description":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter.\n\nYou can take a Magic action to unfold a _Portable Hole_ and place it on or against a solid surface, whereupon the _Portable Hole_ creates an\nextradimensional hole 10 feet deep. The cylindrical space within the hole exists on a different plane of existence, so it can't be used to create open passages. Any creature inside an open _Portable Hole_ can exit the hole by climbing out of it.\n\nYou can take a Magic action to close a _Portable Hole_ by taking hold of the edges of the cloth and folding it up. Folding the cloth closes the hole, and any creatures or objects within remain in the extradimensional space. No matter what's in it, the hole weighs next to nothing.\n\nIf the hole is folded up, a creature within the hole's extradimensional space can take an action to make a DC 10 Strength (Athletics) check. On a successful check, the creature forces its way out and appears within 5 feet of the _Portable Hole_. A closed _Portable Hole_ holds enough air for 1 hour of breathing, divided by the number of breathing creatures inside.\n\nPlacing a _Portable Hole_ inside an extradimensional space created by a _Bag of Holding_, _Handy Haversack_, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate and not behind Total Cover is sucked through it and deposited in a random location on the Astral Plane. The gate then closes. The gate is one-way only and can't be reopened.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-animal-friendship","name":"Potion of Animal Friendship","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":144,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you can cast the level 3 version of the Animal Friendship spell (save DC 13).","description":"When you drink this potion, you can cast the level 3 version of the _Animal Friendship_ spell (save DC 13).\n\nAgitating this potion's muddy liquid brings little bits into view: a fish scale, a hummingbird feather, a cat claw, or a squirrel hair.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","uncommon","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-potion-of-clairvoyance","name":"Potion of Clairvoyance","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":145,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain the effect of the Clairvoyance spell (no Concentration required).","description":"When you drink this potion, you gain the effect of the _Clairvoyance_ spell (no Concentration required).\n\nAn eyeball bobs in this potion's yellowish liquid but vanishes when the potion is opened.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-climbing","name":"Potion of Climbing","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":146,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain a Climb Speed equal to your Speed for 1 hour. During this time, you have Advantage on Strength (Athletics) checks to climb.","description":"When you drink this potion, you gain a Climb Speed equal to your Speed for 1 hour. During this time, you have Advantage on Strength (Athletics) checks to climb.\n\nThis potion is separated into brown, silver, and gray layers resembling bands of stone. Shaking the bottle fails to mix the colors.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","common","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Common","attunement":null},{"slug":"srd52-magic-item-potion-of-diminution","name":"Potion of Diminution","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":147,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain the \"reduce\" effect of the Enlarge/Reduce spell for 1d4 hours (no Concentration required).","description":"When you drink this potion, you gain the \"reduce\" effect of the _Enlarge/Reduce_ spell for 1d4 hours (no Concentration required).\n\nThe red in the potion's liquid continuously contracts to a tiny bead and then expands to color the clear liquid around it. Shaking the bottle fails to interrupt this process.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-flying","name":"Potion of Flying","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":148,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain a Fly Speed equal to your Speed for 1 hour and can hover. If you're in the air when the potion wears off, you fall unless you have some other means of staying aloft.","description":"When you drink this potion, you gain a Fly Speed equal to your Speed for 1 hour and can hover. If you're in the air when the potion wears off, you fall unless you have some other means of staying aloft.\n\nThis potion's clear liquid floats at the top of its container and has cloudy white impurities drifting in it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","very rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-gaseous-form","name":"Potion of Gaseous Form","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":149,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain the effect of the Gaseous Form spell for 1 hour (no Concentration required) or until you end the effect as a Bonus Action.","description":"When you drink this potion, you gain the effect of the _Gaseous Form_ spell for 1 hour (no Concentration required) or until you end the effect as a Bonus Action.\n\nThis potion's container seems to hold fog that moves and pours like water.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-giant-strength","name":"Potion of Giant Strength","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":150,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, your Strength score changes for 1 hour. The type of giant determines the score (see the table below). The potion has no effect on you if your Strength is equal to or greater than that score.","description":"When you drink this potion, your Strength score changes for 1 hour. The type of giant determines the score (see the table below). The potion has no effect on you if your Strength is equal to or greater than that score.\n\nThis potion's transparent liquid has floating in it a sliver of light resembling a giant's fingernail.\n\n| Potion | Str. | Rarity |\n| --- | --- | --- |\n| Potion of Giant Strength (hill) | 21 | Uncommon |\n| Potion of Giant Strength (frost or stone) | 23 | Rare |\n| Potion of Giant Strength (fire) | 25 | Rare |\n| Potion of Giant Strength (cloud) | 27 | Very Rare |\n| Potion of Giant Strength (storm) | 29 | Legendary |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","varies","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-potion-of-growth","name":"Potion of Growth","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":151,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain the \"enlarge\" effect of the Enlarge/Reduce spell for 10 minutes (no Concentration required).","description":"When you drink this potion, you gain the \"enlarge\" effect of the _Enlarge/Reduce_ spell for 10 minutes (no Concentration required).\n\nThe red in the potion's liquid continuously expands from a tiny bead to color the clear liquid around it and then contracts. Shaking the bottle fails to interrupt this process.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","uncommon","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-potions-of-healing","name":"Potions of Healing","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":152,"action_type":null,"uses":null,"recharge":null,"summary":"You regain Hit Points when you drink this potion. The number of Hit Points depends on the potion's rarity, as shown in the table below.","description":"You regain Hit Points when you drink this potion. The number of Hit Points depends on the potion's rarity, as shown in the table below.\n\nWhatever its potency, the potion's red liquid glimmers when agitated.\n\n| Potion | HP Regained | Rarity |\n| --- | --- | --- |\n| Potion of Healing | 2d4 + 2 | Common |\n| Potion of Healing (greater) | 4d4 + 4 | Uncommon |\n| Potion of Healing (superior) | 8d4 + 8 | Rare |\n| Potion of Healing (supreme) | 10d4 + 20 | Very Rare |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","varies","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-potion-of-heroism","name":"Potion of Heroism","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":153,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain 10 Temporary Hit Points that last for 1 hour. For the same duration, you are under the effect of the Bless spell (no Concentration required).","description":"When you drink this potion, you gain 10 Temporary Hit Points that last for 1 hour. For the same duration, you are under the effect of the _Bless_ spell (no Concentration required).\n\nThis potion's blue liquid bubbles and steams as if boiling.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-invisibility","name":"Potion of Invisibility","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":154,"action_type":null,"uses":null,"recharge":null,"summary":"This potion's container looks empty but feels as though it holds liquid.","description":"This potion's container looks empty but feels as though it holds liquid. When you drink the potion, you have the Invisible condition for 1 hour. The effect ends early if you make an attack roll, deal damage, or cast a spell.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-invulnerability","name":"Potion of Invulnerability","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":155,"action_type":null,"uses":null,"recharge":null,"summary":"For 1 minute after you drink this potion, you have Resistance to all damage.","description":"For 1 minute after you drink this potion, you have Resistance to all damage.\n\nThis potion's syrupy liquid looks like liquefied iron.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-longevity","name":"Potion of Longevity","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":156,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, your physical age is reduced by 1d6 + 6 years, to a minimum of 13 years.","description":"When you drink this potion, your physical age is reduced by 1d6 + 6 years, to a minimum of 13 years. Each time you subsequently drink a _Potion of Longevity_, there is 10 percent cumulative chance that you instead age by 1d6 + 6 years.\n\nSuspended in this amber liquid is a tiny heart that, against all reason, is still beating. These ingredients vanish when the potion is opened.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","very rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-mind-reading","name":"Potion of Mind Reading","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":157,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain the effect of the Detect Thoughts spell (save DC 13) for 10 minutes (no Concentration required).","description":"When you drink this potion, you gain the effect of the _Detect Thoughts_ spell (save DC 13) for 10 minutes (no Concentration required).\n\nThis potion's dense, purple liquid has an ovoid cloud of pink floating in it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-poison","name":"Potion of Poison","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":158,"action_type":null,"uses":null,"recharge":null,"summary":"This concoction looks, smells, and tastes like a Potion of Healing or another beneficial potion. However, it is actually poison masked by illusion magic. Identify reveals its true nature.","description":"This concoction looks, smells, and tastes like a _Potion of Healing_ or another beneficial potion. However, it is actually poison masked by illusion magic. _Identify_ reveals its true nature.\n\nIf you drink this potion, you take 4d6 Poison damage and must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 hour.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","uncommon","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-potion-of-resistance","name":"Potion of Resistance","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":159,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you have Resistance to one type of damage for 1 hour. The GM chooses the type or determines it randomly by rolling on the following table.","description":"When you drink this potion, you have Resistance to one type of damage for 1 hour. The GM chooses the type or determines it randomly by rolling on the following table.\n\n| 1d10 | Damage Type | 1d10 | Damage Type |\n| --- | --- | --- | --- |\n| 1 | Acid | 6 | Necrotic |\n| 2 | Cold | 7 | Poison |\n| 3 | Fire | 8 | Psychic |\n| 4 | Force | 9 | Radiant |\n| 5 | Lightning | 10 | Thunder |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","uncommon","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-potion-of-speed","name":"Potion of Speed","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":160,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, you gain the effect of the Haste spell for 1 minute (no Concentration required) without suffering the wave of lethargy that typically occurs when the effect ends.","description":"When you drink this potion, you gain the effect of the _Haste_ spell for 1 minute (no Concentration required) without suffering the wave of lethargy that typically occurs when the effect ends.\n\nThis potion's yellow fluid is streaked with black and swirls on its own.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","very rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-vitality","name":"Potion of Vitality","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":161,"action_type":null,"uses":null,"recharge":null,"summary":"When you drink this potion, it removes any Exhaustion levels you have and ends the Poisoned condition on you. For the next 24 hours, you regain the maximum number of Hit Points for any Hit Point Die you spend.","description":"When you drink this potion, it removes any Exhaustion levels you have and ends the Poisoned condition on you. For the next 24 hours, you regain the maximum number of Hit Points for any Hit Point Die you spend.\n\nThis potion's crimson liquid regularly pulses with dull light, calling to mind a heartbeat.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","very rare","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-potion-of-water-breathing","name":"Potion of Water Breathing","category":"Potion","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":162,"action_type":null,"uses":null,"recharge":null,"summary":"You can breathe underwater for 24 hours after drinking this potion. This potion's cloudy green fluid smells of the sea and has a jellyfish like bubble floating in it.","description":"You can breathe underwater for 24 hours after drinking this potion.\nThis potion's cloudy green fluid smells of the sea and has a jellyfish-like bubble floating in it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","potion","uncommon","2024 rules"],"source_type":"srd","item_type":"Potion","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-quarterstaff-of-the-acrobat","name":"Quarterstaff of the Acrobat","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":163,"action_type":null,"uses":null,"recharge":null,"summary":"You have a +2 bonus to attack rolls and damage rolls made with this magic weapon.","description":"You have a +2 bonus to attack rolls and damage rolls made with this magic weapon.\n\nWhile holding this weapon, you can cause it to emit green Dim Light out to 10 feet, either as a Bonus Action or after you roll Initiative, or you can extinguish the light as a Bonus Action.\n\nWhile holding this weapon, you can take a Bonus Action to alter its form, turning it into a 6-inch rod (for ease of storage) or a 10-foot pole, or reverting it a Quarterstaff; the weapon will elongate only as far as the surrounding space allows.\n\nIn certain forms, the weapon has the following additional properties.\n\n_Acrobatic Assist (Quarterstaff and 10-Foot Pole Forms Only)._ While holding this weapon, you have Advantage on Dexterity (Acrobatics) checks.\n\n_Attack Deflection (Quarterstaff Form Only)._ When you are hit by an attack while holding the weapon, you can take a Reaction to twirl the weapon around you, gaining a +5 bonus to your Armor Class against the triggering attack, potentially causing the attack to miss you. You can't use this property again until you finish a Short or Long Rest.\n\n_Ranged Weapon (Quarterstaff Form Only)._ This weapon has the Thrown property with a normal range of 30 feet and a long range of 120 feet. Immediately after you make a ranged attack with the weapon, it flies back to your hand.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Quarterstaff)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-animal-influence","name":"Ring of Animal Influence","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":164,"action_type":null,"uses":null,"recharge":null,"summary":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. While wearing the ring, you can expend 1 charge to cast one of the following spells (save DC 13) from it:","description":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. While wearing the ring, you can expend 1 charge to cast one of the following spells (save DC 13) from it:\n\n- _Animal Friendship_\n- _Fear_ (affects Beasts only)\n- _Speak with Animals_","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-ring-of-djinni-summoning","name":"Ring of Djinni Summoning","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":165,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you can take a Magic action to summon a particular Djinni from the Elemental Plane of Air.","description":"While wearing this ring, you can take a Magic action to summon a particular **Djinni** from the Elemental Plane of Air. The djinni appears in an unoccupied space you choose within 120 feet of yourself. It remains as long as you maintain Concentration, to a maximum of 1 hour, or until it drops to 0 Hit Points.\n\nWhile summoned, the djinni is Friendly to you and your allies, and it obeys your commands. If you fail to command it, the djinni defends itself against attackers but takes no other actions.\n\nAfter the djinni departs, it can't be summoned again for 24 hours, and the ring becomes nonmagical if the djinni dies.\n\n_Rings of Djinni Summoning_ are often created by the djinn they summon and given to mortals as gifts of friendship or tokens of esteem.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-elemental-command","name":"Ring of Elemental Command","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":166,"action_type":null,"uses":null,"recharge":null,"summary":"Each Ring of Elemental Command is linked to one of the four Elemental Planes.","description":"Each _Ring of Elemental Command_ is linked to one of the four Elemental Planes. The GM chooses or randomly determines the linked plane. For example, a _Ring of Elemental Command_ (air) is linked to the Elemental Plane of Air.\n\nEvery _Ring of Elemental Command_ has the following two properties:\n\n**Elemental Bane.** While wearing the ring, you have Advantage on attack rolls against Elementals and they have Disadvantage on attack rolls against you.\n\n**Elemental Compulsion.** While wearing the ring, you can take a Magic action to try to compel an Elemental you see within 60 feet of yourself. The Elemental makes a DC 18 Wisdom saving throw. On a failed save, the Elemental has the Charmed condition until the start your next turn, and you determine what it does with its move and action on its next turn.\n\n_Elemental Focus._ While wearing the ring, you benefit from additional properties corresponding to the ring's linked Elemental Plane:\n\n**Air.** You know Auran, you have Resistance to Lightning damage, and you have a Fly Speed equal to your Speed and can hover.\n\n**Earth.** You know Terran, and you have Resistance to Acid damage. Terrain composed of rubble, rocks, or dirt isn't Difficult Terrain for you. In addition, you can move through solid earth or rock as if those areas were Difficult Terrain without disturbing the matter through which you pass. If you end your turn in solid earth or rock, you are shunted out to the nearest unoccupied space you last occupied.\n\n**Fire.** You know Ignan, and you have Immunity to Fire damage.\n\n**Water.** You know Aquan, you gain a Swim Speed of 60 feet, and you can breathe underwater.\n\n_Spellcasting._ The ring has 5 charges and regains 1d4 + 1 expended charges daily at dawn. While wearing the ring, you can cast a spell from it. Choose the spell from the list of available spells based on the Elemental Plane the ring is linked to, as shown in the following table. The table indicates how many charges you must expend to cast the spell, which has a save DC of 18.\n\n| Plane | Spells (Charges) |\n| --- | --- |\n| Air | *Chain Lightning* (3 charges), *Feather Fall* (0 charges), *Gust of Wind* (2 charges), *Wind Wall* (1 charge) |\n| Earth | *Earthquake* (5 charges), *Stone Shape* (2 charges), *Stoneskin* (3 charges), *Wall of Stone* (3 charges) |\n| Fire | *Burning Hands* (1 charge), *Fireball* (2 charges), *Fire Storm* (4 charges), *Wall of Fire* (3 charges) |\n| Water | *Create or Destroy Water* (1 charge), *Ice Storm* (2 charges), *Tsunami* (5 charges), *Wall of Ice* (3 charges), *Water Walk* (2 charges) |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-evasion","name":"Ring of Evasion","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":167,"action_type":null,"uses":null,"recharge":null,"summary":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. When you fail a Dexterity saving throw while wearing the ring, you can take a Reaction to expend 1 charge to succeed on that save instead.","description":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. When you fail a Dexterity saving throw while wearing the ring, you can take a Reaction to expend 1 charge to succeed on that save instead.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-feather-falling","name":"Ring of Feather Falling","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":168,"action_type":null,"uses":null,"recharge":null,"summary":"When you fall while wearing this ring, you descend 60 feet per round and take no damage from falling.","description":"When you fall while wearing this ring, you descend 60 feet per round and take no damage from falling.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-free-action","name":"Ring of Free Action","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":169,"action_type":null,"uses":null,"recharge":null,"summary":"While you wear this ring, Difficult Terrain doesn't cost you extra movement. In addition, magic can neither reduce any of your Speeds nor cause you to have the Paralyzed or Restrained condition.","description":"While you wear this ring, Difficult Terrain doesn't cost you extra movement. In addition, magic can neither reduce any of your Speeds nor cause you to have the Paralyzed or Restrained condition.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-invisibility","name":"Ring of Invisibility","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":170,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you can take a Magic action to give yourself the Invisible condition. You remain Invisible until the ring is removed or until you take a Bonus Action to become visible again.","description":"While wearing this ring, you can take a Magic action to give yourself the Invisible condition. You remain Invisible until the ring is removed or until you take a Bonus Action to become visible again.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-jumping","name":"Ring of Jumping","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":171,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you can cast Jump from it, but can target only yourself when you do so.","description":"While wearing this ring, you can cast _Jump_ from it, but can target only yourself when you do so.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-mind-shielding","name":"Ring of Mind Shielding","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":172,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, know your alignment, or know your creature type.","description":"While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, know your alignment, or know your creature type. Creatures can telepathically communicate with you only if you allow it.\n\nYou can take a Magic action to cause the ring to become imperceptible until you take another Magic action to make it perceptible, until you remove the ring, or until you die.\n\nIf you die while wearing the ring, your soul enters it, unless it already houses a soul. You can remain in the ring or depart for the afterlife. As long as your soul is in the ring, you can telepathically communicate with any creature wearing it. A wearer can't prevent this telepathic communication.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-protection","name":"Ring of Protection","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":173,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +1 bonus to Armor Class and saving throws while wearing this ring.","description":"You gain a +1 bonus to Armor Class and saving throws while wearing this ring.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-regeneration","name":"Ring of Regeneration","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":174,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you regain 1d6 Hit Points every 10 minutes if you have at least 1 Hit Point.","description":"While wearing this ring, you regain 1d6 Hit Points every 10 minutes if you have at least 1 Hit Point. If you lose a body part, the ring causes the missing part to regrow and return to full functionality after 1d6 + 1 days if you have at least 1 Hit Point the whole time.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-resistance","name":"Ring of Resistance","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":175,"action_type":null,"uses":null,"recharge":null,"summary":"You have Resistance to one damage type while wearing this ring. The gemstone in the ring indicates the type, which the GM chooses or determines randomly by rolling on the following table.","description":"You have Resistance to one damage type while wearing this ring. The gemstone in the ring indicates the type, which the GM chooses or determines randomly by rolling on the following table.\n\n| 1d10 | Damage Type | Gemstone |\n| --- | --- | --- |\n| 1 | Acid | Pearl |\n| 2 | Cold | Tourmaline |\n| 3 | Fire | Garnet |\n| 4 | Force | Sapphire |\n| 5 | Lightning | Citrine |\n| 6 | Necrotic | Jet |\n| 7 | Poison | Amethyst |\n| 8 | Psychic | Jade |\n| 9 | Radiant | Topaz |\n| 10 | Thunder | Spinel |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-ring-of-shooting-stars","name":"Ring of Shooting Stars","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":176,"action_type":null,"uses":null,"recharge":null,"summary":"You can cast Dancing Lights or Light from the ring.","description":"You can cast _Dancing Lights_ or _Light_ from the ring.\n\nThe ring has 6 charges and regains 1d6 expended charges daily at dawn. You can expend its charges to use the properties below.\n\n**_Faerie Fire._** You can expend 1 charge to cast _Faerie Fire_ from the ring.\n\n**_Lightning Spheres._** You can expend 2 charges as a Magic action to create up to four 3-foot-diameter spheres of lightning. Each sphere appears in an unoccupied space you can see within 120 feet of yourself. The spheres last as long as you maintain Concentration, up to 1 minute. Each sphere sheds Dim Light in a 30-foot radius.\n\nAs a Bonus Action, you can move each sphere up to 30 feet, but no farther than 120 feet away from yourself. The first time the sphere comes within 5 feet of a creature other than you that isn't behind Total Cover, the sphere discharges lightning at that creature and disappears. That creature makes a DC 15 Dexterity saving throw. On a failed save, the creature takes Lightning damage based on the number of spheres you created, as shown in the following table. On a successful save, the creature takes half as much damage.\n\n| Number of Spheres | Lightning Damage | Number of Spheres | Lightning Damage |\n| --- | --- | --- | --- |\n| 1 | 4d12 | 3 | 2d6 |\n| 2 | 5d4 | 4 | 2d4 |\n\n_Shooting Stars._ You can expend 1 to 3 charges as a Magic action. For every charge you expend, you launch a glowing mote of light from the ring at a point you can see within 60 feet of yourself. Each creature in a 15-foot Cube originating from that point is showered in sparks and makes a DC 15 Dexterity saving throw, taking 5d4 Radiant damage on a failed save or half as much damage on a successful one.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-spell-storing","name":"Ring of Spell Storing","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":177,"action_type":null,"uses":null,"recharge":null,"summary":"This ring stores spells cast into it, holding them until the attuned wearer uses them.","description":"This ring stores spells cast into it, holding them until the attuned wearer uses them. The ring can store up to 5 levels worth of spells at a time. When found, it contains 1d6 − 1 levels of stored spells chosen by the GM.\n\nAny creature can cast a spell of level 1 through 5 into the ring by touching the ring as the spell is cast. The spell has no effect other than to be stored in the ring. If the ring can't hold the spell, the spell is expended without effect. The level of the slot used to cast the spell determines how much space it uses.\n\nWhile wearing this ring, you can cast any spell stored in it. The spell uses the slot level, spell save DC, spell attack bonus, and spellcasting ability of the original caster but is otherwise treated as if you cast the spell. The spell cast from the ring is no longer stored in it, freeing up space.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-spell-turning","name":"Ring of Spell Turning","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":178,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you have Advantage on saving throws against spells.","description":"While wearing this ring, you have Advantage on saving throws against spells. If you succeed on the save for a spell of level 7 or lower, the spell has no effect on you. If that spell targeted only you and didn't create an area of effect, you can take a Reaction to deflect the spell back at the spell's caster; the caster must make a saving throw against the spell using their own spell save DC.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-swimming","name":"Ring of Swimming","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":179,"action_type":null,"uses":null,"recharge":null,"summary":"You have a Swim Speed of 40 feet while wearing this ring.","description":"You have a Swim Speed of 40 feet while wearing this ring.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","uncommon","2024 rules"],"source_type":"srd","item_type":"Ring","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-ring-of-telekinesis","name":"Ring of Telekinesis","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":180,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you can cast Telekinesis from it.","description":"While wearing this ring, you can cast _Telekinesis_ from it.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-the-ram","name":"Ring of the Ram","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":181,"action_type":null,"uses":null,"recharge":null,"summary":"This ring has 3 charges and regains 1d3 expended charges daily at dawn.","description":"This ring has 3 charges and regains 1d3 expended charges daily at dawn. While wearing the ring, you can take a Magic action to expend 1 to 3 charges to make a ranged spell attack against one creature you can see within 60 feet of yourself. The ring produces a spectral ram's head and makes its attack roll with a +7 bonus. On a hit, for each charge you spend, the target takes 2d10 Force damage and is pushed 5 feet away from you.\n\nAlternatively, you can expend 1 to 3 of the ring's charges as a Magic action to try to break a nonmagical object you can see within 60 feet of yourself that isn't being worn or carried. The ring makes a Strength check with a +5 bonus for each charge you spend.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-three-wishes","name":"Ring of Three Wishes","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":182,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you can expend 1 of its 3 charges to cast Wish from it. The ring becomes nonmagical when you use the last charge.","description":"While wearing this ring, you can expend 1 of its 3 charges to cast _Wish_ from it. The ring becomes nonmagical when you use the last charge.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","legendary","2024 rules"],"source_type":"srd","item_type":"Ring","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-ring-of-warmth","name":"Ring of Warmth","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":183,"action_type":null,"uses":null,"recharge":null,"summary":"If you take Cold damage while wearing this ring, the ring reduces the damage you take by 2d8.","description":"If you take Cold damage while wearing this ring, the ring reduces the damage you take by 2d8.\n\nIn addition, while wearing this ring, you and everything you wear and carry are unharmed by temperatures of 0 degrees Fahrenheit or lower.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-ring-of-water-walking","name":"Ring of Water Walking","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":184,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you cast Water Walk from it, targeting only yourself.","description":"While wearing this ring, you cast _Water Walk_ from it, targeting only yourself.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","uncommon","2024 rules"],"source_type":"srd","item_type":"Ring","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-ring-of-x-ray-vision","name":"Ring of X-ray Vision","category":"Ring","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":185,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this ring, you can take a Magic action to gain X ray vision with a range of 30 feet for 1 minute.","description":"While wearing this ring, you can take a Magic action to gain X-ray vision with a range of 30 feet for 1 minute. To you, solid objects within that radius appear transparent and don't prevent light from passing through them. The vision can penetrate 1 foot of stone, 1 inch of common metal, or up to 3 feet of wood or dirt. Thicker substances or a thin sheet of lead block the vision.\n\nWhenever you use the ring again before taking a Long Rest, you must succeed on a DC 15 Constitution saving throw or gain 1 Exhaustion level.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","ring","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Ring","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-robe-of-eyes","name":"Robe of Eyes","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":186,"action_type":null,"uses":null,"recharge":null,"summary":"This robe is adorned with eyelike patterns. While you wear the robe, you gain the following benefits:","description":"This robe is adorned with eyelike patterns. While you wear the robe, you gain the following benefits:\n\n**All-Around Vision.** The robe gives you Advantage on Wisdom (Perception) checks that rely on sight.\n\n**Special Senses.** You have Darkvision and Truesight, both with a range of 120 feet.\n\n_Drawbacks._ A _Light_ spell cast on the robe or a _Daylight_ spell cast within 5 feet of the robe gives you the Blinded condition for 1 minute. At the end of each of your turns, you make a Constitution saving throw (DC 11 for _Light_ or DC 15 for _Daylight_), ending the condition on yourself on a success.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-robe-of-scintillating-colors","name":"Robe of Scintillating Colors","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":187,"action_type":null,"uses":null,"recharge":null,"summary":"This robe has 3 charges, and it regains 1d3 expended charges daily at dawn.","description":"This robe has 3 charges, and it regains 1d3 expended charges daily at dawn. While you wear it, you can take a Magic action and expend 1 charge to cause the garment to display a shifting pattern of dazzling hues until the end of your next turn. During this time, the robe sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet, and creatures that can see you have Disadvantage on attack rolls against you. Any creature in the Bright Light that can see you when the robe's power is activated must succeed on a DC 15 Wisdom saving throw or have the Stunned condition until the effect ends.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-robe-of-stars","name":"Robe of Stars","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":188,"action_type":null,"uses":null,"recharge":null,"summary":"This black or dark blue robe is embroidered with small white or silver stars. You gain a +1 bonus to saving throws while you wear it.","description":"This black or dark-blue robe is embroidered with small white or silver stars. You gain a +1 bonus to saving throws while you wear it.\n\nSix stars, located on the robe's upper-front portion, are particularly large. While wearing this robe, you can take a Magic action to remove one of the stars and expend it to cast the level 5 version of _Magic Missile_. Daily at dusk, 1d6 removed stars reappear on the robe.\n\nWhile you wear the robe, you can take a Magic action to enter the Astral Plane along with everything you are wearing and carrying. You remain there until you take a Magic action to return to the plane you were on. You reappear in the last space you occupied or, if that space is occupied, the nearest unoccupied space.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-robe-of-the-archmagi","name":"Robe of the Archmagi","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":189,"action_type":null,"uses":null,"recharge":null,"summary":"This elegant garment is made from exquisite cloth and adorned with runes.","description":"This elegant garment is made from exquisite cloth and adorned with runes.\n\nYou gain these benefits while wearing the robe.\n\n_Armor._ If you aren't wearing armor, your base Armor Class is 15 plus your Dexterity modifier.\n\n_Magic Resistance._ You have Advantage on saving throws against spells and other magical effects.\n\n_War Mage._ Your spell save DC and spell attack bonus each increase by 2.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement by a Sorcerer, Warlock, or Wizard"},{"slug":"srd52-magic-item-robe-of-useful-items","name":"Robe of Useful Items","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":190,"action_type":null,"uses":null,"recharge":null,"summary":"This robe has cloth patches of various shapes and colors covering it.","description":"This robe has cloth patches of various shapes and colors covering it. While wearing the robe, you can take a Magic action to detach one of the patches, causing it to become the object or creature it represents. Once the last patch is removed, the robe becomes an ordinary garment.\n\nThe robe has two of each of the following patches:\n\n- Bullseye Lantern (filled and lit)\n- Dagger\n- Mirror\n- Pole\n- Rope (coiled)\n- Sack\n\nIn addition, the robe has 4d4 other patches. The GM chooses the patches or determines them randomly by rolling on the following table.\n\n| 1d100 | Patch |\n| --- | --- |\n| 01–08 | Bag of 100 GP |\n| 09–15 | Silver coffer (1 foot long, 6 inches wide and deep) worth 500 GP |\n| 16–22 | Iron door (up to 10 feet wide and 10 feet high, barred on one side of your choice), which you can place in an opening you can reach; it conforms to fit the opening, attaching and hinging itself |\n| 23–30 | 10 gems worth 100 GP each |\n| 31–44 | Wooden ladder (24 feet long) |\n| 45–51 | Riding Horse with a Riding Saddle |\n| 52–59 | Open pit (a 10-foot Cube), which you can place on the ground within 10 feet of yourself |\n| 60–68 | 4 Potions of Healing |\n| 69–75 | Rowboat (12 feet long) |\n| 76–83 | Spell Scroll containing one spell of level 1, 2, or 3 (your choice) |\n| 84–90 | 2 Mastiffs |\n| 91–96 | Window (2 feet by 4 feet, up to 2 feet deep), which you can place on a vertical surface you can reach |\n| 97–00 | Portable Ram |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-rod-of-absorption","name":"Rod of Absorption","category":"Rod","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":191,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this rod, you can take a Reaction to absorb a spell that is targeting only you and doesn't create an area of effect.","description":"While holding this rod, you can take a Reaction to absorb a spell that is targeting only you and doesn't create an area of effect. The absorbed spell's effect is canceled, and the spell's energy—not the spell itself—is stored in the rod. The energy has the same level as the spell when it was cast. A canceled spell dissipates with no effect, and any resources used to cast it are wasted. The rod can absorb and store up to 50 levels of energy over the course of its existence. Once the rod absorbs 50 levels of energy, it can't absorb more. If you are targeted by a spell that the rod can't store, the rod has no effect on that spell.\n\nWhen you become attuned to the rod, you know how many levels of energy the rod has absorbed over the course of its existence and how many levels of spell energy it currently has stored.\n\nIf you are a spellcaster holding the rod, you can convert energy stored in it into spell slots to cast spells you have prepared or know. You can create spell slots only of a level equal to or lower than your own spell slots, up to a maximum of level 5. You use the stored levels in place of your slots but otherwise cast the spell as normal. For example, you can use 3 levels stored in the rod as a level 3 spell slot.\n\nA newly found rod typically has 1d10 levels of spell energy stored in it. A rod that can no longer absorb spell energy and has no energy remaining becomes nonmagical.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","rod","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Rod","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-rod-of-alertness","name":"Rod of Alertness","category":"Rod","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":192,"action_type":null,"uses":null,"recharge":null,"summary":"This rod has the following properties.","description":"This rod has the following properties.\n\n_Alertness._ While holding the rod, you have Advantage on Wisdom (Perception) checks and on Initiative rolls.\n\n_Spells._ While holding the rod, you can cast the following spells from it:\n\n- _Detect Evil and Good_\n- _Detect Magic_\n- _Detect Poison and Disease_\n- _See Invisibility_\n\n_Protective Aura._ As a Magic action, you can plant the haft end of the rod in the ground, whereupon the rod's head sheds Bright Light in a 60-foot radius and Dim Light for an additional 60 feet. While in that Bright Light, you and your allies gain a +1 bonus to Armor Class and saving throws and can sense the location of any Invisible creature that is also in the Bright Light.\n\nThe rod's head stops glowing and the effect ends after 10 minutes or when a creature takes a Magic action to pull the rod from the ground. Once used, this property can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","rod","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Rod","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-rod-of-lordly-might","name":"Rod of Lordly Might","category":"Rod","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":193,"action_type":null,"uses":null,"recharge":null,"summary":"This rod has a flanged head, and it functions as a magic Mace that grants a +3 bonus to attack rolls and damage rolls made with it.","description":"This rod has a flanged head, and it functions as a magic Mace that grants a +3 bonus to attack rolls and damage rolls made with it. The rod has properties associated with six different buttons that are set in a row along the haft. It has three other properties as well, detailed below.\n\n_Buttons._ You can press one of the following buttons as a Bonus Action; a button's effect lasts until you push a different button or until you push the same button again, which causes the rod to revert to its normal form:\n\n**Button 1.** A fiery blade sprouts from the end opposite the rod's flanged head. The flames shed Bright Light in a 40-foot radius and Dim Light for an additional 40 feet, and the blade functions as a magic Longsword or Shortsword (your choice) that deals an extra 2d6 Fire damage on a hit.\n\n**Button 2.** The rod's flanged head folds down and two crescent-shaped blades spring out, transforming the rod into a magic Battleaxe that grants a +3 bonus to attack rolls and damage rolls made with it.\n\n**Button 3.** The rod's flanged head folds down, a spear point springs from the rod's tip, and the rod's handle lengthens into a 6-foot haft, transforming the rod into a magic Spear that grants a +3 bonus to attack rolls and damage rolls made with it.\n\n**Button 4.** The rod transforms into a climbing pole up to 50 feet long (you specify the length), though the rod's buttons remain within your reach. In surfaces as hard as granite, a spike at the bottom and three hooks at the top anchor the pole. Horizontal bars 3 inches long fold out from the sides, 1 foot apart, forming a ladder. The pole can bear up to 4,000 pounds. More weight or lack of solid anchoring causes the rod to revert to its normal form.\n\n**Button 5.** The rod transforms into a handheld battering ram and grants its user a +10 bonus to Strength (Athletics) checks made to break through doors, barricades, and other barriers.\n\n**Button 6.** The rod assumes or remains in its normal form and indicates magnetic north. (Nothing happens if this function of the rod is used in a location that has no magnetic north.) The rod also gives you knowledge of your approximate depth beneath the ground or your height above it.\n\n_Drain Life._ When you hit a creature with a melee attack using the rod, you can force the target to make a DC 17 Constitution saving throw. On a failed save, the target takes an extra 4d6 Necrotic damage, and you regain a number of Hit Points equal to half that Necrotic damage. Once used, this property can't be used again until the next dawn.\n\n_Paralyze._ When you hit a creature with a melee attack using the rod, you can force the target to make a DC 17 Constitution saving throw. On a failed save, the target has the Paralyzed condition for 1 minute. The target repeats the save at the end of each of its turns, ending the effect on a success. Once used, this property can't be used again until the next dawn.\n\n_Terrify._ While holding the rod, you can take a Magic action to force each creature you can see within 30 feet of yourself to make a DC 17 Wisdom saving throw. On a failed save, a target has the Frightened condition for 1 minute. A Frightened target repeats the save at the end of each of its turns, ending the effect on itself on a success. Once used, this property can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","rod","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Rod","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-rod-of-resurrection","name":"Rod of Resurrection","category":"Rod","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":194,"action_type":null,"uses":null,"recharge":null,"summary":"The rod has 5 charges. While you hold it, you can cast one of the following spells from it: Heal (expends 1 charge) or Resurrection (expends 5 charges).","description":"The rod has 5 charges. While you hold it, you can cast one of the following spells from it: _Heal_ (expends 1 charge) or _Resurrection_ (expends 5 charges).\n\nThe rod regains 1 expended charge daily at dawn. If you expend the last charge, roll 1d20. On a 1, the rod disappears in a harmless burst of radiance.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","rod","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Rod","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-rod-of-rulership","name":"Rod of Rulership","category":"Rod","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":195,"action_type":null,"uses":null,"recharge":null,"summary":"You can take a Magic action to present the rod and command obedience from each creature of your choice that you can see within 120 feet of yourself.","description":"You can take a Magic action to present the rod and command obedience from each creature of your choice that you can see within 120 feet of yourself. Each target must succeed on a DC 15 Wisdom saving throw or have the Charmed condition for 8 hours. While Charmed in this way, the creature regards you as its trusted leader. If harmed by you or your allies or commanded to do something contrary to its nature, a target ceases to be Charmed in this way. Once used, this property can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","rod","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Rod","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-rod-of-security","name":"Rod of Security","category":"Rod","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":196,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this rod, you can take a Magic action to activate it.","description":"While holding this rod, you can take a Magic action to activate it. The rod then instantly transports you and up to 199 other willing creatures you can see to a demiplane. You choose the form the demiplane takes. It could be a tranquil garden, a cheery tavern, an immense palace, a tropical island, a fantastic carnival, or whatever else you can imagine. Regardless of its nature, the demiplane contains enough water and food to sustain its visitors, and the demiplane's environment can't harm its occupants. Everything else that can be interacted with there can exist only there. For example, a flower picked from a garden there disappears if it is taken outside the demiplane.\n\nFor each hour spent in the demiplane, a visitor regains Hit Points as if it had spent 1 Hit Point Die. Also, creatures don't age while there, although time passes normally. Visitors can remain there for up to 200 days divided by the number of creatures present (round down).\n\nWhen the time runs out or you take a Magic action to end the effect, all visitors reappear in the location they occupied when you activated the rod or an unoccupied space nearest that location. Once used, this property can't be used again until 10 days have passed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","rod","very rare","2024 rules"],"source_type":"srd","item_type":"Rod","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-rope-of-climbing","name":"Rope of Climbing","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":197,"action_type":null,"uses":null,"recharge":null,"summary":"This 60 foot length of rope can hold up to 3,000 pounds.","description":"This 60-foot length of rope can hold up to 3,000 pounds. While holding one end of the rope, you can take a Magic action to command the other end of the rope to animate and move toward a destination you choose, up to the rope's length away from you. That end moves 10 feet on your turn when you first command it and 10 feet at the start of each of your subsequent turns until reaching its destination or until you tell it to stop. You can also tell the rope to fasten itself securely to an object or to unfasten itself, to knot or unknot itself, or to coil itself for carrying.\n\nIf you tell the rope to knot, large knots appear at 1-foot intervals along the rope. While knotted, the rope shortens to a 50-foot length and grants Advantage on ability checks made to climb using the rope.\n\nThe rope has AC 20, HP 20, and Immunity to Poison and Psychic damage. It regains 1 Hit Point every 5 minutes as long as it has at least 1 Hit Point. If the rope drops to 0 Hit Points, it is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-rope-of-entanglement","name":"Rope of Entanglement","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":198,"action_type":null,"uses":null,"recharge":null,"summary":"This rope is 30 feet long.","description":"This rope is 30 feet long. While holding one end of the rope, you can take a Magic action to command the other end to dart forward and entangle one creature you can see within 20 feet of yourself. The target must succeed on a DC 15 Dexterity saving throw or have the Restrained condition. You can release the target by letting go of your end of the rope (causing the rope to coil up in the target's space) or by using a Bonus Action to repeat the command (causing the rope to coil up in your hand).\n\nA target Restrained by the rope can take an action to make its choice of a DC 15 Strength (Athletics) or Dexterity (Acrobatics) check. On a successful check, the target is no longer Restrained by the rope. If you're still holding onto the rope when a target escapes from it, you can take a Reaction to command the rope to coil up in your hand; otherwise, the rope coils up in the target's space.\n\nThe rope has AC 20, HP 20, and Immunity to Poison and Psychic damage. It regains 1 Hit Point every 5 minutes as long as it has at least 1 Hit Point. If the rope drops to 0 Hit Points, it is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-scarab-of-protection","name":"Scarab of Protection","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":199,"action_type":null,"uses":null,"recharge":null,"summary":"This beetle shaped medallion provides three benefits while it is on your person.","description":"This beetle-shaped medallion provides three benefits while it is on your person.\n\n_Defense._ You gain a +1 bonus to Armor Class.\n\n_Preservation._ The scarab has 12 charges. If you fail a saving throw against a Necromancy spell or a harmful effect originating from an Undead, you can take a Reaction to expend 1 charge and turn the failed save into a successful one. The scarab crumbles into powder and is destroyed when its last charge is expended.\n\n_Spell Resistance._ You have Advantage on saving throws against spells.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-scimitar-of-speed","name":"Scimitar of Speed","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":200,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. In addition, you can make one attack with it as a Bonus Action on each of your turns.","description":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. In addition, you can make one attack with it as a Bonus Action on each of your turns.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Scimitar)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-sending-stones","name":"Sending Stones","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":201,"action_type":null,"uses":null,"recharge":null,"summary":"Sending Stones come in pairs, with each stone carved to match the other so the pairing is easily recognized.","description":"_Sending Stones_ come in pairs, with each stone carved to match the other so the pairing is easily recognized. While you touch one stone, you can cast _Sending_ from it. The target is the bearer of the other stone. If no creature bears the other stone, you know that fact as soon as you use the stone, and you don't cast the spell.\n\nOnce _Sending_ is cast using either stone, the stones can't be used again until the next dawn. If one of the stones in a pair is destroyed, the other one becomes nonmagical.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-sentinel-shield","name":"Sentinel Shield","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":202,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this Shield, you have Advantage on Initiative rolls and Wisdom (Perception) checks. The Shield is emblazoned with a symbol of an eye.","description":"While holding this Shield, you have Advantage on Initiative rolls and Wisdom (Perception) checks. The Shield is emblazoned with a symbol of an eye.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","uncommon","2024 rules"],"source_type":"srd","item_type":"Armor (Shield)","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-shield-1-2-or-3","name":"Shield, +1, +2, or +3","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":203,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this Shield, you have a bonus to Armor Class determined by the Shield's rarity, in addition to the Shield's normal bonus to AC.","description":"While holding this Shield, you have a bonus to Armor Class determined by the Shield's rarity, in addition to the Shield's normal bonus to AC.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","varies","2024 rules"],"source_type":"srd","item_type":"Armor (Shield)","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-shield-of-missile-attraction","name":"Shield of Missile Attraction","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":204,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this Shield, you have Resistance to damage from attacks made with Ranged weapons.","description":"While holding this Shield, you have Resistance to damage from attacks made with Ranged weapons.\n\n_Curse._ This Shield is cursed. Attuning to it curses you until you are targeted by a _Remove Curse_ spell or similar magic. Removing the Shield fails to end the curse on you. Whenever an attack with a Ranged weapon targets a creature within 10 feet of you, the curse causes you to become the target instead.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Shield)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-shield-of-the-cavalier","name":"Shield of the Cavalier","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":205,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this Shield, you have a +2 bonus to Armor Class. This bonus is in addition to the Shield's normal bonus to AC.","description":"While holding this Shield, you have a +2 bonus to Armor Class. This bonus is in addition to the Shield's normal bonus to AC.\n\nThe Shield has the following additional properties that you can use while holding it.\n\n_Forceful Bash._ When you take the Attack action, you can make one of the attack rolls using the Shield against a target within 5 feet of yourself. Apply your Proficiency Bonus and Strength modifier to the attack roll. On a hit, the Shield deals Force damage to the target equal to 2d6 + 2 plus your Strength modifier, and if the target is a creature, you can push it up to 10 feet directly away from yourself. If the creature is your size or smaller, you can also knock it down, giving it the Prone condition.\n\n_Protective Field._ As a Reaction, when you or an ally you can see within 5 feet of you is targeted by an attack or makes a saving throw against an area of effect, you can use the Shield to create an immobile 5-foot Emanation originating from you. When the Emanation appears, any creatures or objects not fully contained within it are pushed into the nearest unoccupied spaces outside it. The attack or area of effect that triggered the Reaction has no effect on creatures and objects inside the Emanation, which lasts as long as you maintain Concentration, up to 1 minute. Nothing can pass into or out of the Emanation. A creature or object inside the Emanation can't be damaged by attacks or effects originating from outside, nor can a creature inside the Emanation damage anything outside it. Once this property is used, it can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Shield)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-slippers-of-spider-climbing","name":"Slippers of Spider Climbing","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":206,"action_type":null,"uses":null,"recharge":null,"summary":"While you wear these light shoes, you can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free.","description":"While you wear these light shoes, you can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free. You have a Climb Speed equal to your Speed. However, the slippers don't allow you to move this way on a slippery surface, such as one covered by ice or oil.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-sovereign-glue","name":"Sovereign Glue","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":207,"action_type":null,"uses":null,"recharge":null,"summary":"This viscous, milky white substance can form a permanent adhesive bond between any two objects.","description":"This viscous, milky-white substance can form a permanent adhesive bond between any two objects. It must be stored in a jar or flask that has been coated inside with _Oil of Slipperiness_. When found, a container contains 1d6 + 1 ounces.\n\nOne ounce of the glue can cover a 1-foot square surface. Applying an ounce of _Sovereign Glue_ takes a Utilize action, and the applied glue takes 1 minute to set. Once it has done so, the bond it creates can be broken only by the application of _Universal Solvent_ or _Oil of Etherealness_, or with a _Wish_ spell.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-spellguard-shield","name":"Spellguard Shield","category":"Armor","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":208,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this Shield, you have Advantage on saving throws against spells and other magical effects, and spell attack rolls have Disadvantage against you.","description":"While holding this Shield, you have Advantage on saving throws against spells and other magical effects, and spell attack rolls have Disadvantage against you.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","armor","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Armor (Shield)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-spell-scroll","name":"Spell Scroll","category":"Scroll","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":209,"action_type":null,"uses":null,"recharge":null,"summary":"A Spell Scroll bears the words of a single spell, written in a mystical cipher.","description":"A _Spell Scroll_ bears the words of a single spell, written in a mystical cipher. If the spell is on your spell list, you can read the scroll and cast its spell without Material components. Otherwise, the scroll is unintelligible. Casting the spell by reading the scroll requires the spell's normal casting time. Once the spell is cast, the scroll crumbles to dust. If the casting is interrupted, the scroll isn't lost.\n\nIf the spell is on your spell list but of a higher level than you can normally cast, you make an ability check using your spellcasting ability to determine whether you cast the spell. The DC equals 10 plus the spell's level. On a failed check, the spell disappears from the scroll with no other effect.\n\nThe level of the spell on the scroll determines the spell's saving throw DC and attack bonus, as well as the scroll's rarity, as shown in the following table.\n\n| Spell Level | Rarity | Save DC | Attack Bonus |\n| --- | --- | --- | --- |\n| Cantrip | Common | 13 | +5 |\n| 1 | Common | 13 | +5 |\n| 2 | Uncommon | 13 | +5 |\n| 3 | Uncommon | 15 | +7 |\n| 4 | Rare | 15 | +7 |\n| 5 | Rare | 17 | +9 |\n| 6 | Very Rare | 17 | +9 |\n| 7 | Very Rare | 18 | +10 |\n| 8 | Very Rare | 18 | +10 |\n| 9 | Legendary | 19 | +11 |\n\n_Copying a Scroll into a Spellbook._ A Wizard spell on a _Spell Scroll_ can be copied into a spellbook. When a spell is copied in this way, the copier must succeed on an Intelligence (Arcana) check with a DC equal to 10 plus the spell's level. On a successful check, the spell is copied. Whether the check succeeds or fails, the _Spell Scroll_ is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","scroll","varies","2024 rules"],"source_type":"srd","item_type":"Scroll","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-sphere-of-annihilation","name":"Sphere of Annihilation","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":210,"action_type":null,"uses":null,"recharge":null,"summary":"This 2 foot diameter black sphere is a hole in the multiverse, hovering in space and stabilized by a magical field surrounding it.","description":"This 2-foot-diameter black sphere is a hole in the multiverse, hovering in space and stabilized by a magical field surrounding it.\n\nThe sphere obliterates all matter it passes through and all matter that passes through it. Artifacts are the exception. Unless an Artifact is susceptible to damage from a _Sphere of Annihilation_, it passes through the sphere unscathed. Anything else that touches the sphere but isn't wholly engulfed and obliterated by it takes 8d10 Force damage.\n\n_Controlling the Sphere._ A _Sphere of Annihilation_ is stationary until someone takes control of it. If you are within 60 feet of a sphere, you can take a Magic action to make a DC 25 Intelligence (Arcana) check. On a successful check, you control the sphere until the start of your next turn, and if it was under another creature's control, that creature loses control of the sphere. On a failed check, the sphere moves 10 feet toward you in a straight line.\n\nWhile in control of the sphere, you can take a Bonus Action to cause it to move in one direction of your choice, up to a number of feet equal to 5 times your Intelligence modifier (minimum 5 feet). Any creature whose space the sphere enters must succeed on a DC 19 Dexterity saving throw or be touched by it, taking 8d10 Force damage. A creature reduced to 0 Hit Points by this damage is obliterated, leaving its possessions behind but no other physical remains.\n\n_Sphere Interactions._ If the sphere comes into contact with a planar portal (such as that created by the _Gate_ spell) or an extradimensional space (such as that within a _Portable Hole_), the GM determines randomly what happens using the following table.\n\n| 1d100 | Result |\n| --- | --- |\n| 01–50 | The sphere is destroyed. |\n| 51–85 | The sphere moves through the portal or into the extradimensional space. |\n| 86–00 | A spatial rift sends the sphere and each creature and object within 180 feet of the sphere to a random plane of existence. |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-staff-of-charming","name":"Staff of Charming","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":211,"action_type":null,"uses":null,"recharge":null,"summary":"This staff has 10 charges. While holding the staff, you can use any of its properties:","description":"This staff has 10 charges. While holding the staff, you can use any of its properties:\n\n**Cast Spell.** You can expend 1 of the staff's charges to cast _Charm Person_, _Command_, or _Comprehend Languages_ from it using your spell save DC.\n\n**Reflect Enchantment.** If you succeed on a saving throw against an Enchantment spell that targets only you, you can take a Reaction to expend 1 charge from the staff and turn the spell back on its caster as if you had cast the spell.\n\n**Resist Enchantment.** If you fail a saving throw against an Enchantment spell that targets only you, you can turn your failed save into a successful one. You can't use this property of the staff again until the next dawn.\n\n_Regaining Charges._ The staff regains 1d8 + 2 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff crumbles to dust and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Rare","attunement":"Requires Attunement by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard"},{"slug":"srd52-magic-item-staff-of-fire","name":"Staff of Fire","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":212,"action_type":null,"uses":null,"recharge":null,"summary":"You have Resistance to Fire damage while you hold this staff.","description":"You have Resistance to Fire damage while you hold this staff.\n\n_Spells._ The staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost | Spell | Charge Cost |\n| --- | --- | --- | --- |\n| *Burning Hands* | 1 | *Wall of Fire* | 4 |\n| *Fireball* | 3 |  |  |\n\n_Regaining Charges._ The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff crumbles into cinders and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Very Rare","attunement":"Requires Attunement by a Druid, Sorcerer, Warlock, or Wizard"},{"slug":"srd52-magic-item-staff-of-frost","name":"Staff of Frost","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":213,"action_type":null,"uses":null,"recharge":null,"summary":"You have Resistance to Cold damage while you hold this staff.","description":"You have Resistance to Cold damage while you hold this staff.\n\n_Spells._ The staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost | Spell | Charge Cost |\n| --- | --- | --- | --- |\n| *Cone of Cold* | 5 | *Ice Storm* | 4 |\n| *Fog Cloud* | 1 | *Wall of Ice* | 4 |\n\n_Regaining Charges._ The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff turns to water and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Very Rare","attunement":"Requires Attunement by a Druid, Sorcerer, Warlock, or Wizard"},{"slug":"srd52-magic-item-staff-of-healing","name":"Staff of Healing","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":214,"action_type":null,"uses":null,"recharge":null,"summary":"This staff has 10 charges.","description":"This staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spellcasting ability modifier. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost |\n| --- | --- |\n| *Cure Wounds* | 1 charge per spell level (maximum 4 for a level 4 spell) |\n| *Lesser Restoration* | 2 |\n| *Mass Cure Wounds* | 5 |\n\n_Regaining Charges._ The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff vanishes in a flash of light, lost forever.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Rare","attunement":"Requires Attunement by a Bard, Cleric, or Druid"},{"slug":"srd52-magic-item-staff-of-power","name":"Staff of Power","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":215,"action_type":null,"uses":null,"recharge":null,"summary":"This staff has 20 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it.","description":"This staff has 20 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you gain a +2 bonus to Armor Class, saving throws, and spell attack rolls.\n\n_Spells._ While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost |\n| --- | --- |\n| *Cone of Cold* | 5 |\n| *Fireball* (level 5 version) | 5 |\n| *Globe of Invulnerability* | 6 |\n| *Hold Monster* | 5 |\n| *Levitate* | 2 |\n| *Lightning Bolt* (level 5 version) | 5 |\n| *Magic Missile* | 1 |\n| *Ray of Enfeeblement* | 1 |\n| *Wall of Force* | 5 |\n\n_Regaining Charges._ The staff regains 2d8 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff retains its +2 bonus to attack rolls and damage rolls but loses all other properties. On a 20, the staff regains 1d8 + 2 charges.\n\n_Retributive Strike._ You can take a Magic action to break the staff over your knee or against a solid surface. The staff is destroyed and releases its magic in an explosion that fills a 30-foot Emanation originating from itself. You have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take Force damage equal to 16 times the number of charges in the staff. Each other creature in the area makes a DC 17 Dexterity saving throw. On a failed save, a creature takes Force damage equal to 4 times the number of charges in the staff. On a successful save, a creature takes half as much damage.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Very Rare","attunement":"Requires Attunement by a Sorcerer, Warlock, or Wizard"},{"slug":"srd52-magic-item-staff-of-striking","name":"Staff of Striking","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":216,"action_type":null,"uses":null,"recharge":null,"summary":"This staff can be wielded as a magic Quarterstaff that grants a +3 bonus to attack rolls and damage rolls made with it.","description":"This staff can be wielded as a magic Quarterstaff that grants a +3 bonus to attack rolls and damage rolls made with it.\n\nThe staff has 10 charges. When you hit with a melee attack using it, you can expend up to 3 charges. For each charge you expend, the target takes an extra 1d6 Force damage.\n\n_Regaining Charges._ The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff becomes a nonmagical Quarterstaff.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-staff-of-swarming-insects","name":"Staff of Swarming Insects","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":217,"action_type":null,"uses":null,"recharge":null,"summary":"This staff has 10 charges.","description":"This staff has 10 charges.\n\n_Insect Cloud._ While holding the staff, you can take a Magic action and expend 1 charge to cause a swarm of harmless flying insects to fill a 30-foot Emanation originating from you. The insects remain for 10 minutes, making the area Heavily Obscured for creatures other than you. A strong wind (like that created by _Gust of Wind_) disperses the swarm and ends the effect.\n\n_Spells._ While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC and spell attack modifier. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost |\n| --- | --- |\n| *Giant Insect* | 4 |\n| *Insect Plague* | 5 |\n\n_Regaining Charges._ The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, a swarm of insects consumes and destroys the staff, then disperses.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Rare","attunement":"Requires Attunement by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard"},{"slug":"srd52-magic-item-staff-of-the-magi","name":"Staff of the Magi","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":218,"action_type":null,"uses":null,"recharge":null,"summary":"This staff has 50 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While you hold it, you gain a +2 bonus to spell attack rolls.","description":"This staff has 50 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While you hold it, you gain a +2 bonus to spell attack rolls.\n\n_Spell Absorption._ While holding the staff, you have Advantage on saving throws against spells. In addition, you can take a Reaction when another creature casts a spell that targets only you. If you do, the staff absorbs the magic of the spell, canceling its effect and gaining a number of charges equal to the absorbed spell's level. However, if doing so brings the staff's total number of charges above 50, the staff explodes as if you activated its Retributive Strike (see below).\n\n_Spells._ While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost |\n| --- | --- |\n| *Arcane Lock* | 0 |\n| *Conjure Elemental* | 7 |\n| *Detect Magic* | 0 |\n| *Dispel Magic* | 3 |\n| *Enlarge/Reduce* | 0 |\n| *Fireball* (level 7 version) | 7 |\n| *Flaming Sphere* | 2 |\n| *Ice Storm* | 4 |\n| *Invisibility* | 2 |\n| *Knock* | 2 |\n| *Light* | 0 |\n| *Lightning Bolt* (level 7 version) | 7 |\n| *Passwall* | 5 |\n| *Plane Shift* | 7 |\n| *Protection from Evil and Good* | 0 |\n| *Telekinesis* | 5 |\n| *Wall of Fire* | 4 |\n| *Web* | 2 |\n\n_Regaining Charges._ The staff regains 4d6 + 2 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 20, the staff regains 1d12 + 1 charges.\n\n_Retributive Strike._ You can take a Magic action to break the staff over your knee or against a solid surface. The staff is destroyed and releases its magic in an explosion that fills a 30-foot Emanation originating from itself. You have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take Force damage equal to 16 times the number of charges in the staff. Each other creature in the area makes a DC 17 Dexterity saving throw. On a failed save, a creature takes Force damage equal to 6 times the number of charges in the staff. On a successful save, a creature takes half as much damage.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Legendary","attunement":"Requires Attunement by a Sorcerer, Warlock, or Wizard"},{"slug":"srd52-magic-item-staff-of-the-python","name":"Staff of the Python","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":219,"action_type":null,"uses":null,"recharge":null,"summary":"As a Magic action, you can throw this staff so that it lands in an unoccupied space within 10 feet of you, causing the staff to become a Giant Constrictor Snake in that space.","description":"As a Magic action, you can throw this staff so that it lands in an unoccupied space within 10 feet of you, causing the staff to become a **Giant Constrictor Snake** in that space. The snake is under your control and shares your Initiative count, taking its turn immediately after yours.\n\nOn your turn, you can mentally command the snake (no action required) if it is within 60 feet of you and you don't have the Incapacitated condition. You decide what action the snake takes and where it moves during its turn, or you can issue it a general command, such as to attack your enemies or guard a location. Absent commands from you, the snake defends itself.\n\nAs a Bonus Action, you can command the snake to revert to staff form in its current space, and you can't use the staff's property again for 1 hour. If the snake is reduced to 0 Hit Points, it dies and reverts to its staff form; the staff then shatters and is destroyed. If the snake reverts to staff form before losing all its Hit Points, it regains all of them.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-staff-of-the-woodlands","name":"Staff of the Woodlands","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":220,"action_type":null,"uses":null,"recharge":null,"summary":"This staff has 6 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you have a +2 bonus to spell attack rolls.","description":"This staff has 6 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you have a +2 bonus to spell attack rolls.\n\n_Spells._ While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost |\n| --- | --- |\n| *Animal Friendship* | 1 |\n| *Awaken* | 5 |\n| *Barkskin* | 2 |\n| *Locate Animals or Plants* | 2 |\n| *Pass without Trace* | 2 |\n| *Speak with Animals* | 1 |\n| *Speak with Plants* | 3 |\n| *Wall of Thorns* | 6 |\n\n_Tree Form._ You can take a Magic action to plant one end of the staff in earth in an unoccupied space and expend 1 charge to transform the staff into a healthy tree. The tree is 60 feet tall and has a 5-foot-diameter trunk, and its branches at the top spread out in a 20-foot radius. The tree appears ordinary but radiates a faint aura of Transmutation magic that can be discerned with the _Detect Magic_ spell. While touching the tree and using a Magic action, you return the staff to its normal form. Any creature in the tree falls when the tree reverts to a staff.\n\n_Regaining Charges._ The staff regains 1d6 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff loses its properties and becomes a nonmagical Quarterstaff.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Rare","attunement":"Requires Attunement by a Druid"},{"slug":"srd52-magic-item-staff-of-thunder-and-lightning","name":"Staff of Thunder and Lightning","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":221,"action_type":null,"uses":null,"recharge":null,"summary":"This staff can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it.","description":"This staff can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. It also has the following additional properties. Once one of these properties is used, it can't be used again until the next dawn.\n\n_Lightning._ When you hit with a melee attack using the staff, you can cause the target to take an extra 2d6 Lightning damage (no action required).\n\n_Thunder._ When you hit with a melee attack using the staff, you can cause the staff to emit a crack of thunder audible out to 300 feet (no action required). The target you hit must succeed on a DC 17 Constitution saving throw or have the Stunned condition until the end of your next turn.\n\n**_Thunder and Lightning._** Immediately after you hit with a melee attack using the staff, you can take a Bonus Action to use the Lightning and Thunder properties (see above) at the same time. Doing so doesn't expend the daily use of those properties, only the use of this one.\n\n_Lightning Strike._ You can take a Magic action to cause a bolt of lightning to leap from the staff's tip in a Line that is 5 feet wide and 120 feet long. Each creature in that Line makes a DC 17 Dexterity saving throw, taking 9d6 Lightning damage on a failed save or half as much damage on a successful one.\n\n_Thunderclap._ You can take a Magic action to cause the staff to produce a thunderclap audible out to 600 feet. Every creature within a 60-foot Emanation originating from you makes a DC 17 Constitution saving throw. On a failed save, a creature takes 2d6 Thunder damage and has the Deafened condition for 1 minute. On a successful save, a creature takes half as much damage only.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-staff-of-withering","name":"Staff of Withering","category":"Staff","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":222,"action_type":null,"uses":null,"recharge":null,"summary":"This staff has 3 charges and regains 1d3 expended charges daily at dawn.","description":"This staff has 3 charges and regains 1d3 expended charges daily at dawn.\n\nThe staff can be wielded as a magic Quarterstaff. On a hit, it deals damage as a normal Quarterstaff, and you can expend 1 charge to deal an extra 2d10 Necrotic damage to the target and force it to make a DC 15 Constitution saving throw. On a failed save, the target has Disadvantage for 1 hour on any ability check or saving throw that uses Strength or Constitution.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","staff","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Staff","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-stone-of-controlling-earth-elementals","name":"Stone of Controlling Earth Elementals","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":223,"action_type":null,"uses":null,"recharge":null,"summary":"While touching this 5 pound stone to the ground, you can take a Magic action to summon an Earth Elemental .","description":"While touching this 5-pound stone to the ground, you can take a Magic action to summon an **Earth Elemental**. The elemental appears in an unoccupied space you choose within 30 feet of yourself, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The stone can't be used this way again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-stone-of-good-luck-luckstone","name":"Stone of Good Luck (Luckstone)","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":224,"action_type":null,"uses":null,"recharge":null,"summary":"While this polished agate is on your person, you gain a +1 bonus to ability checks and saving throws.","description":"While this polished agate is on your person, you gain a +1 bonus to ability checks and saving throws.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-sun-blade","name":"Sun Blade","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":225,"action_type":null,"uses":null,"recharge":null,"summary":"This item appears to be a sword hilt.","description":"This item appears to be a sword hilt.\n\n_Blade of Radiance._ While grasping the hilt, you can take a Bonus Action to cause a blade of pure radiance to spring into existence or make the blade disappear. While the blade exists, this magic weapon functions as a Longsword with the Finesse property. If you are proficient with Longswords or Shortswords, you are proficient with the _Sun Blade_.\n\nYou gain a +2 bonus to attack rolls and damage rolls made with this weapon, which deals Radiant damage instead of Slashing damage. When you hit an Undead with it, that target takes an extra 1d8 Radiant damage.\n\n_Sunlight._ The sword's luminous blade emits Bright Light in a 15-foot radius and Dim Light for an additional 15 feet. The light is sunlight. While the blade persists, you can take a Magic action to expand or reduce its radius of Bright Light and Dim Light by 5 feet each, to a maximum of 30 feet each or a minimum of 10 feet each.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Longsword)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-sword-of-life-stealing","name":"Sword of Life Stealing","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":226,"action_type":null,"uses":null,"recharge":null,"summary":"When you attack a creature with this magic weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 15 Necrotic damage if it isn't a Construct or an Undead, and you gain Temporary Hit Points equ…","description":"When you attack a creature with this magic weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 15 Necrotic damage if it isn't a Construct or an Undead, and you gain Temporary Hit Points equal to the amount of Necrotic damage taken.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, or Shortsword)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-sword-of-sharpness","name":"Sword of Sharpness","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":227,"action_type":null,"uses":null,"recharge":null,"summary":"When you attack an object with this magic weapon and hit, maximize your weapon damage dice against the target.","description":"When you attack an object with this magic weapon and hit, maximize your weapon damage dice against the target.\n\nWhen you attack a creature with this weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 14 Slashing damage and gains 1 Exhaustion level.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Glaive, Greatsword, Longsword, or Scimitar)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-sword-of-wounding","name":"Sword of Wounding","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":228,"action_type":null,"uses":null,"recharge":null,"summary":"When you hit a creature with an attack using this magic weapon, the target takes an extra 2d6 Necrotic damage and must succeed on a DC 15 Constitution saving throw or be unable to regain Hit Points for 1 hour.","description":"When you hit a creature with an attack using this magic weapon, the target takes an extra 2d6 Necrotic damage and must succeed on a DC 15 Constitution saving throw or be unable to regain Hit Points for 1 hour. The target repeats the save at the end of each of its turns, ending the effect on itself on a success.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, or Shortsword)","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-talisman-of-pure-good","name":"Talisman of Pure Good","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":229,"action_type":null,"uses":null,"recharge":null,"summary":"This talisman is a mighty symbol of goodness. A Fiend or an Undead that touches the talisman takes 8d6 Radiant damage and takes the damage again each time it ends its turn holding or carrying the talisman.","description":"This talisman is a mighty symbol of goodness. A Fiend or an Undead that touches the talisman takes 8d6 Radiant damage and takes the damage again each time it ends its turn holding or carrying the talisman.\n\n_Holy Symbol._ You can use the talisman as a Holy Symbol. You gain a +2 bonus to spell attack rolls while you wear or hold it.\n\n_Pure Rebuke._ The talisman has 7 charges. While wearing or holding the talisman, you can take a Magic action to expend 1 charge and target one creature you can see on the ground within 120 feet of yourself. A flaming fissure opens under the target, and the target makes a DC 20 Dexterity saving throw. If the target is a Fiend or an Undead, it has Disadvantage on the save. On a failed save, the target falls into the fissure and is destroyed, leaving no remains. On a successful save, the target isn't cast into the fissure but takes 4d6 Psychic damage from the ordeal. In either case, the fissure then closes, leaving no trace of its existence. When you expend the last charge, the talisman disperses into motes of golden light and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement by a Cleric or Paladin"},{"slug":"srd52-magic-item-talisman-of-the-sphere","name":"Talisman of the Sphere","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":230,"action_type":null,"uses":null,"recharge":null,"summary":"While holding or wearing this talisman, you have Advantage on any Intelligence (Arcana) check you make to control a Sphere of Annihilation .","description":"While holding or wearing this talisman, you have Advantage on any Intelligence (Arcana) check you make to control a _Sphere of Annihilation_. In addition, when you start your turn in control of a _Sphere of Annihilation_, you can take a Magic action to move it 10 feet plus a number of additional feet equal to 10 times your Intelligence modifier. This movement doesn't have to be in a straight line.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-talisman-of-ultimate-evil","name":"Talisman of Ultimate Evil","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":231,"action_type":null,"uses":null,"recharge":null,"summary":"This item symbolizes unrepentant evil.","description":"This item symbolizes unrepentant evil. A creature that isn't a Fiend or an Undead that touches the talisman takes 8d6 Necrotic damage and takes the damage again each time it ends its turn holding or carrying the talisman.\n\n_Holy Symbol._ You can use the talisman as a Holy Symbol. You gain a +2 bonus to spell attack rolls while you wear or hold it.\n\n_Ultimate End._ The talisman has 6 charges. While wearing or holding the talisman, you can take a Magic action to expend 1 charge and target one creature you can see on the ground within 120 feet of yourself. A flaming fissure opens under the target, and the target makes a DC 20 Dexterity saving throw. If the target is a Celestial, it has Disadvantage on the save. On a failed save, the target falls into the fissure and is destroyed, leaving no remains. On a successful save, the target isn't cast into the fissure but takes 4d6 Psychic damage from the ordeal. In either case, the fissure then closes, leaving no trace of its existence. When you expend the last charge, the talisman dissolves into foul-smelling slime and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-thunderous-greatclub","name":"Thunderous Greatclub","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":232,"action_type":null,"uses":null,"recharge":null,"summary":"While you are attuned to this magic weapon, your Strength is 20 unless your Strength is already equal to or greater than that score.","description":"While you are attuned to this magic weapon, your Strength is 20 unless your Strength is already equal to or greater than that score. The weapon deals an extra 1d8 Thunder damage to any creature it hits and an extra 3d8 Thunder damage to objects it hits that aren't being worn or carried.\n\nThe weapon has the following additional properties.\n\n_Clap of Thunder._ As a Magic action, you can strike the weapon against a hard surface to create a loud clap of thunder audible out to 300 feet. You also create a 30-foot Cone of thunderous energy. Each creature in the Cone must succeed on a DC 15 Strength saving throw or have the Prone condition. Nonmagical objects in the Cone that aren't being worn or carried take 3d8 Thunder damage.\n\n_Earthquake._ As a Magic action, you can strike the weapon against the ground to create an intense seismic disturbance in a 50-foot-radius circle centered on the point of impact. Structures in contact with the ground in that area take 50 Bludgeoning damage, and each creature on the ground in that area must succeed on a DC 20 Dexterity saving throw or have the Prone condition. If that creature is also concentrating, it must succeed on a DC 20 Constitution saving throw, or its Concentration is broken. In addition, you can cause a 30-foot-deep, 10-foot-wide fissure to open up on the ground anywhere in the area. Any creature on a spot where the fissure opens must make a DC 20 Dexterity saving throw, falling into the fissure on a failed save or moving with the fissure's edge on a successful one. Any structure on a spot where the fissure opens collapses into the fissure. Once you use this property, it can't be used again until the next dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Greatclub)","item_rarity":"Very Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-tome-of-clear-thought","name":"Tome of Clear Thought","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":233,"action_type":null,"uses":null,"recharge":null,"summary":"This book contains memory and logic exercises, and its words are charged with magic.","description":"This book contains memory and logic exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book's contents and practicing its guidelines, your Intelligence increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-tome-of-leadership-and-influence","name":"Tome of Leadership and Influence","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":234,"action_type":null,"uses":null,"recharge":null,"summary":"This book contains guidelines for influencing and charming others, and its words are charged with magic.","description":"This book contains guidelines for influencing and charming others, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book's contents and practicing its guidelines, your Charisma increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-tome-of-understanding","name":"Tome of Understanding","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":235,"action_type":null,"uses":null,"recharge":null,"summary":"This book contains intuition and insight exercises, and its words are charged with magic.","description":"This book contains intuition and insight exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book's contents and practicing its guidelines, your Wisdom increases by 2, to a maximum of 30. The manual then loses its magic, but regains it in a century.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","very rare","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Very Rare","attunement":null},{"slug":"srd52-magic-item-trident-of-fish-command","name":"Trident of Fish Command","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":236,"action_type":null,"uses":null,"recharge":null,"summary":"This magic weapon has 3 charges, and it regains 1d3 expended charges daily at dawn. While you carry it, you can expend 1 charge to cast Dominate Beast (save DC 15) from it on a Beast that has a Swim Speed.","description":"This magic weapon has 3 charges, and it regains 1d3 expended charges daily at dawn. While you carry it, you can expend 1 charge to cast _Dominate Beast_ (save DC 15) from it on a Beast that has a Swim Speed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Trident)","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-universal-solvent","name":"Universal Solvent","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":237,"action_type":null,"uses":null,"recharge":null,"summary":"This tube holds milky liquid with a strong alcohol smell. When found, a tube contains 1d6 + 1 ounces.","description":"This tube holds milky liquid with a strong alcohol smell. When found, a tube contains 1d6 + 1 ounces.\n\nYou can take a Utilize action to pour 1 or more ounces of solvent from the tube onto a surface within reach. Each ounce instantly dissolves up to 1 square foot of adhesive it touches, including _Sovereign Glue_.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-vicious-weapon","name":"Vicious Weapon","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":238,"action_type":null,"uses":null,"recharge":null,"summary":"This magic weapon deals an extra 2d6 damage to any creature it hits. This extra damage is of the same type as the weapon's normal damage.","description":"This magic weapon deals an extra 2d6 damage to any creature it hits. This extra damage is of the same type as the weapon's normal damage.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","rare","2024 rules"],"source_type":"srd","item_type":"Weapon (Any Simple or Martial)","item_rarity":"Rare","attunement":null},{"slug":"srd52-magic-item-vorpal-sword","name":"Vorpal Sword","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":239,"action_type":null,"uses":null,"recharge":null,"summary":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. In addition, the weapon ignores Resistance to Slashing damage.","description":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. In addition, the weapon ignores Resistance to Slashing damage.\n\nWhen you use this weapon to attack a creature that has at least one head and roll a 20 on the d20 for the attack roll, you cut off one of the creature's heads. The creature dies if it can't survive without the lost head. A creature is immune to this effect if it has Immunity to Slashing damage, if it doesn't have or need a head, or if the GM decides that the creature is too big for its head to be cut off with this weapon. Such a creature instead takes an extra 30 Slashing damage from the hit. If the creature has Legendary Resistance, it can expend one daily use of that trait to avoid losing its head, taking the extra damage instead.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","legendary","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Glaive, Greatsword, Longsword, or Scimitar)","item_rarity":"Legendary","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-wand-of-binding","name":"Wand of Binding","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":240,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges.","description":"This wand has 7 charges.\n\n_Spells._ While holding the wand, you can cast one of the spells (save DC 17) on the following table from it. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost |\n| --- | --- |\n| *Hold Monster* | 5 |\n| *Hold Person* | 2 |\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-wand-of-enemy-detection","name":"Wand of Enemy Detection","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":241,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges.","description":"This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge. For 1 minute, you know the direction of the nearest creature Hostile to you within 60 feet, but not its distance from you. The wand can sense the presence of Hostile creatures that are Invisible, ethereal, disguised, or hidden, as well as those in plain sight. The effect ends if you stop holding the wand.\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-wand-of-fear","name":"Wand of Fear","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":242,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges.","description":"This wand has 7 charges.\n\n_Spells._ While holding the wand, you can cast one of the spells (save DC 15) on the following table from it. The table indicates how many charges you must expend to cast the spell.\n\n| Spell | Charge Cost |\n| --- | --- |\n| *Command* (flee or grovel only) | 1 |\n| *Fear* (60-foot Cone) | 3 |\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-wand-of-fireballs","name":"Wand of Fireballs","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":243,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges.","description":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast _Fireball_ (save DC 15) from it. For 1 charge, you cast the level 3 version of the spell. You can increase the spell's level by 1 for each additional charge you expend.\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Rare","attunement":"Requires Attunement by a Spellcaster"},{"slug":"srd52-magic-item-wand-of-lightning-bolts","name":"Wand of Lightning Bolts","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":244,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges.","description":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast _Lightning Bolt_ (save DC 15) from it. For 1 charge, you cast the level 3 version of the spell. You can increase the spell's level by 1 for each additional charge you expend.\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Rare","attunement":"Requires Attunement by a Spellcaster"},{"slug":"srd52-magic-item-wand-of-magic-detection","name":"Wand of Magic Detection","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":245,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 3 charges. While holding it, you can expend 1 charge to cast Detect Magic from it. The wand regains 1d3 expended charges daily at dawn.","description":"This wand has 3 charges. While holding it, you can expend 1 charge to cast _Detect Magic_ from it. The wand regains 1d3 expended charges daily at dawn.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","uncommon","2024 rules"],"source_type":"srd","item_type":"Wand","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-wand-of-magic-missiles","name":"Wand of Magic Missiles","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":246,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges.","description":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast _Magic Missile_ from it. For 1 charge, you cast the level 1 version of the spell. You can increase the spell's level by 1 for each additional charge you expend.\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","uncommon","2024 rules"],"source_type":"srd","item_type":"Wand","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-wand-of-paralysis","name":"Wand of Paralysis","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":247,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges.","description":"This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge to cause a thin blue ray to streak from the tip toward a creature you can see within 60 feet of yourself. The target must succeed on a DC 15 Constitution saving throw or have the Paralyzed condition for 1 minute. At the end of each of the target's turns, it repeats the save, ending the effect on itself on a success.\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Rare","attunement":"Requires Attunement by a Spellcaster"},{"slug":"srd52-magic-item-wand-of-polymorph","name":"Wand of Polymorph","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":248,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges. While holding it, you can expend 1 charge to cast Polymorph (save DC 15) from it.","description":"This wand has 7 charges. While holding it, you can expend 1 charge to cast _Polymorph_ (save DC 15) from it.\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","very rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Very Rare","attunement":"Requires Attunement by a Spellcaster"},{"slug":"srd52-magic-item-wand-of-secrets","name":"Wand of Secrets","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":249,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 3 charges and regains 1d3 expended charges daily at dawn.","description":"This wand has 3 charges and regains 1d3 expended charges daily at dawn. While holding it, you can take a Magic action to expend 1 charge, and if a secret door or trap is within 60 feet of you, the wand pulses and points at the one nearest to you.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","uncommon","2024 rules"],"source_type":"srd","item_type":"Wand","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-wand-of-the-war-mage-1-2-or-3","name":"Wand of the War Mage, +1, +2, or +3","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":250,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this wand, you gain a bonus to spell attack rolls determined by the wand's rarity. In addition, you ignore Half Cover when making a spell attack roll.","description":"While holding this wand, you gain a bonus to spell attack rolls determined by the wand's rarity. In addition, you ignore Half Cover when making a spell attack roll.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","varies","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Varies","attunement":"Requires Attunement by a Spellcaster"},{"slug":"srd52-magic-item-wand-of-web","name":"Wand of Web","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":251,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges. While holding it, you can expend 1 charge to cast Web (save DC 13) from it.","description":"This wand has 7 charges. While holding it, you can expend 1 charge to cast _Web_ (save DC 13) from it.\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Uncommon","attunement":"Requires Attunement by a Spellcaster"},{"slug":"srd52-magic-item-wand-of-wonder","name":"Wand of Wonder","category":"Wand","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":252,"action_type":null,"uses":null,"recharge":null,"summary":"This wand has 7 charges.","description":"This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge while choosing a point within 120 feet of yourself. That location becomes the point of origin of a spell or other magical effect determined by rolling on the Wand of Wonder Effects table. Spells cast from the wand have a save DC of 15. If a spell's maximum range is normally less than 120 feet, it becomes 120 feet when cast from the wand. If an effect has multiple possible subjects, the GM determines randomly which among them are affected.\n\n_Regaining Charges._ The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll 1d20. On a 1, the wand crumbles into dust and is destroyed.\n\n**Wand of Wonder Effects**\n\n| 1d100 | Effect |\n| --- | --- |\n| 01–20 | You cast a spell originating from the chosen point. Roll 1d10 to determine the spell: on a 1–2, Darkness; on a 3–4, Faerie Fire; on a 5–6, Fireball; on a 7–8, Slow; on a 9–10, Stinking Cloud. |\n| 21–25 | Nothing happens at the chosen point of origin. Instead, you have the Stunned condition until the start of your next turn, believing something awesome just happened. |\n| 26–30 | You cast Gust of Wind. The Line created by the spell extends from you to the chosen point of origin. |\n| 31–35 | Nothing happens at the chosen point of origin. Instead, you take 1d6 Psychic damage. |\n| 36–40 | Heavy rain falls for 1 minute in a 120-foot-high, 60-foot-radius Cylinder centered on the chosen point of origin. During that time, the area of effect is Lightly Obscured. |\n| 41–45 | A cloud of 600 oversized butterflies fills a 60-foot-high, 30-foot-radius Cylinder centered on the chosen point of origin. The butterflies remain for 10 minutes, during which time the area of effect is Heavily Obscured. |\n| 46–50 | You cast Lightning Bolt. The Line created by the spell extends from you to the chosen point of origin. |\n| 51–55 | The creature closest to the chosen point of origin is enlarged as if you had cast Enlarge/ Reduce on it. If the target isn't you and can't be affected by that spell, you become the target instead. |\n| 56–60 | A magically formed creature appears in an unoccupied space as close to the chosen point of origin as possible. The creature isn't under your control, acts as it normally would, and disappears after 1 hour or when it drops to 0 Hit Points. Roll 1d4 to determine which creature appears. On a 1, a Rhinoceros appears; on a 2, an Elephant appears; and on a 3–4, a Rat appears. |\n| 61–64 | Grass covers a 60-foot-radius circle of ground, with the center of that circle as close to the chosen point of origin as possible. Grass that's already there grows to ten times its normal size and remains overgrown for 1 minute. |\n\n| 1d100 | Effect |\n| --- | --- |\n| 65–68 | An object of the GM's choice disappears into the Ethereal Plane. The object must be neither worn nor carried, within 120 feet of the chosen point of origin, and no larger than 10 feet in any dimension. If there are no such objects in range, nothing happens. |\n| 69–72 | Nothing happens at the chosen point of origin. Instead, you shrink as if you had cast Enlarge/ Reduce on yourself and remain in that state for 1 minute. |\n| 73–77 | Leaves grow from the creature nearest to the chosen point of origin. Unless they are picked off, the leaves turn brown and fall off after 24 hours. |\n| 78–82 | Nothing happens at the chosen point of origin. Instead, a burst of colorful, shimmering light extends from you in a 30-foot Emanation. Each creature in the area must succeed on a DC 15 Constitution saving throw or have the Blinded condition for 1 minute. A creature repeats the save at the end of each of its turns, ending the effect on itself on a success. |\n| 83–87 | Nothing happens at the chosen point of origin. Instead, you cast Invisibility on yourself. |\n| 88–92 | Nothing happens at the chosen point of origin. Instead, a stream of 1d4 × 10 gems, each worth 1 GP, shoots from the wand's tip in a Line 30 feet long and 5 feet wide toward the chosen point of origin. Each gem deals 1 Bludgeoning damage, and the total damage of the gems is divided equally among all creatures in the Line. |\n| 93–97 | You cast Polymorph, targeting the creature closest to the chosen point of origin. Roll 1d4 to determine the target's new form. On a 1, the new form is a Black Bear; on a 2, the new form is a Giant Wasp; on a 3–4, the new form is a Frog. |\n| 98–00 | The creature closest to the chosen point of origin makes a DC 15 Constitution saving throw. On a failed save, the creature has the Restrained condition and begins to turn to stone. While Restrained in this way, the creature repeats the save at the end of its next turn. On a successful save, the effect ends. On a failed save, the creature has the Petrified condition instead of the Restrained condition. The petrification lasts until the creature is freed by the Greater Restoration spell or similar magic. |","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wand","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wand","item_rarity":"Rare","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-weapon-1-2-or-3","name":"Weapon, +1, +2, or +3","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":253,"action_type":null,"uses":null,"recharge":null,"summary":"You have a bonus to attack rolls and damage rolls made with this magic weapon. The bonus is determined by the weapon's rarity.","description":"You have a bonus to attack rolls and damage rolls made with this magic weapon. The bonus is determined by the weapon's rarity.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","varies","2024 rules"],"source_type":"srd","item_type":"Weapon (Any Simple or Martial)","item_rarity":"Varies","attunement":null},{"slug":"srd52-magic-item-weapon-of-warning","name":"Weapon of Warning","category":"Weapon","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":254,"action_type":null,"uses":null,"recharge":null,"summary":"As long as this weapon is within your reach and you are attuned to it, you and allies within 30 feet of you gain the following benefits.","description":"As long as this weapon is within your reach and you are attuned to it, you and allies within 30 feet of you gain the following benefits.\n\n_Alarm._ The weapon magically awakens each subject who is sleeping naturally when combat begins. This benefit doesn't wake a subject from magically induced sleep.\n\n_Supernatural Readiness._ Each subject has Advantage on its Initiative rolls.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","weapon","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Weapon (Any Simple or Martial)","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-well-of-many-worlds","name":"Well of Many Worlds","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":255,"action_type":null,"uses":null,"recharge":null,"summary":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter.","description":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter.\n\nYou can take a Magic action to unfold the _Well of Many Worlds_ and place it on a solid surface, whereupon it forms a two-way, 6-foot-diameter, circular portal to another world or plane of existence. Each time the item opens a portal, the GM decides where it leads. The portal remains open until a creature within 5 feet of it takes a Magic action to close it by taking hold of the edges of the cloth and folding it up.\n\nOnce the _Well of Many Worlds_ has opened a portal, it can't do so again for 1d8 hours.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","legendary","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Legendary","attunement":null},{"slug":"srd52-magic-item-wind-fan","name":"Wind Fan","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":256,"action_type":null,"uses":null,"recharge":null,"summary":"While holding this fan, you can cast Gust of Wind (save DC 13) from it.","description":"While holding this fan, you can cast _Gust of Wind_ (save DC 13) from it. Each subsequent time the fan is used before the next dawn, it has a cumulative 20 percent chance of not working; if the fan fails to work, it tears into useless, nonmagical tatters.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":null},{"slug":"srd52-magic-item-winged-boots","name":"Winged Boots","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":257,"action_type":null,"uses":null,"recharge":null,"summary":"These boots have 4 charges and regain 1d4 expended charges daily at dawn.","description":"These boots have 4 charges and regain 1d4 expended charges daily at dawn. While wearing the boots, you can take a Magic action to expend 1 charge, gaining a Fly Speed of 30 feet for 1 hour. If you are flying when the duration expires, you descend at a rate of 30 feet per round until you land.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","uncommon","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Uncommon","attunement":"Requires Attunement"},{"slug":"srd52-magic-item-wings-of-flying","name":"Wings of Flying","category":"Wondrous Item","ability_kind":"magic_item","class_key":null,"level_required":null,"feature_order":258,"action_type":null,"uses":null,"recharge":null,"summary":"While wearing this cloak, you can take a Magic action to turn the cloak into a pair of wings on your back.","description":"While wearing this cloak, you can take a Magic action to turn the cloak into a pair of wings on your back. The wings lasts for 1 hour or until you end the effect early as a Magic action. The wings give you a Fly Speed of 60 feet. If you are aloft when the wings disappear, you fall. When the wings disappear, you can't use them again for 1d12 hours.","prerequisite":null,"repeatable":false,"source":"SRD 5.2.1 (2024)","tags":["magic item","wondrous item","rare","2024 rules","attunement"],"source_type":"srd","item_type":"Wondrous Item","item_rarity":"Rare","attunement":"Requires Attunement"}]$magic_item_data$::jsonb)
)
insert into public.abilities (
  slug,
  name,
  category,
  ability_kind,
  class_key,
  level_required,
  feature_order,
  is_system,
  source_type,
  action_type,
  uses,
  recharge,
  summary,
  description,
  prerequisite,
  repeatable,
  source,
  tags,
  item_type,
  item_rarity,
  attunement,
  created_by
)
select
  item->>'slug',
  item->>'name',
  item->>'category',
  item->>'ability_kind',
  nullif(item->>'class_key', ''),
  (item->>'level_required')::integer,
  (item->>'feature_order')::integer,
  true,
  item->>'source_type',
  nullif(item->>'action_type', ''),
  nullif(item->>'uses', ''),
  nullif(item->>'recharge', ''),
  nullif(item->>'summary', ''),
  item->>'description',
  nullif(item->>'prerequisite', ''),
  coalesce((item->>'repeatable')::boolean, false),
  nullif(item->>'source', ''),
  array(select jsonb_array_elements_text(item->'tags')),
  nullif(item->>'item_type', ''),
  nullif(item->>'item_rarity', ''),
  nullif(item->>'attunement', ''),
  null
from magic_item_data
on conflict (slug) do update set
  name = excluded.name,
  category = excluded.category,
  ability_kind = excluded.ability_kind,
  class_key = excluded.class_key,
  level_required = excluded.level_required,
  feature_order = excluded.feature_order,
  is_system = true,
  source_type = excluded.source_type,
  action_type = excluded.action_type,
  uses = excluded.uses,
  recharge = excluded.recharge,
  summary = excluded.summary,
  description = excluded.description,
  prerequisite = excluded.prerequisite,
  repeatable = excluded.repeatable,
  source = excluded.source,
  tags = excluded.tags,
  item_type = excluded.item_type,
  item_rarity = excluded.item_rarity,
  attunement = excluded.attunement,
  updated_at = now()
where not public.abilities.dm_edited;

commit;
